__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Страж, когда я смогу посетить кладбище академии? Там похоронены великие души, которые наверняка принесут мне необычные вдохновения! Не волнуйся, я обещаю больше не раскапывать эти трупы для ближайшего рассмотрения..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Разные разговоры: о манекенах"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Подожди! Я придумал новый способ выражения, который потрясет весь мир живописи!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Я — Погоня за светом и Чёрная Чёрная тень, я — цвет, я... есть сама живопись!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Шшш... Какой цвет, которого я никогда не видел, сияет в вашем духовном мире... Что это такое..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_100338_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Какой потрясающий черный цвет! Я когда-то собрал много растворения для рисования, но в итоге все эти картины исчезли. Цвета из первичной вселенной, все картины были поглощены и забыты никем... Разве не лучше?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Позволь мне подойти ближе... Позволь мне увидеть больше! Эти светотени, эти цвета, эти позы... В сравнении с ними все, что я рисовал раньше, - это просто куча мусора..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_100340_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Дуллсейн всегда говорит мне, как его кулинария полна художественного чувства, он заставляет меня посмотреть, но еда и искусство совершенно не связаны! Не только нужно тратить драгоценное время на сложные процессуальные работы с трупами, но и, с трудом создав блюдо, соответствующее и формой, и цветом, следует его жевать и поглощать! Это просто преступление против искусства!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Нгх…"},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Ужасный модель..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Нет нет нет, опять ужасная картина... Где найти вдохновение? На кладбище? Или на месте казни..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Хотя я считаю, что такое искусство, как скульптура, несколько слишком жестким и формальным, но та скульптор по имени Санг, ее резец обладает выразительностью, выходящей за рамки этого вида искусства... Она действительно редкий гений!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Свободные разговоры: о Санге"
  },
  Voice_100345_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Шань\" будет разблокировано"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Ты видишь эту картину, Страж? Это мой портрет для вас. Посмотрите на то, как вы поедаете тела, как это очаровательно! Я знаю, что не все могут понять мои произведения, но ту безумную красоту, которую передает эта картина, вы, конечно, уже ощутили, не так ли?! Для меня этого уже достаточно, совершенно достаточно..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_100346_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Вы только что сказали, что хотите купить эту картину... Это Правда?! Спасибо вам, Страж! Очень, очень немногие люди способны оценить это..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_100347_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Страж, у тебя есть время, чтобы снова стать моей моделью? По сравнению с тем, что я видела на тебе в прошлый раз, другие модели совершенно тратят моё время..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Свидетельство новой жизни в этой картине!"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "Смотри на эти живые линии!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "У меня есть предчувствие, что то, что создаст эта кисть, удивит всех!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ах! Носят новаторские краски... Я нанесу их в самых подходящих местах!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Здесь как раз подходящее место, чтобы вдохновляться! У меня снова появились идеи для творчества, Страж, у вас есть время посетить мою художественную студию? Давайте, давайте!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_100353_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Да, да! Победа, омытая кровью! Какой замечательный композиций!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Нгх…"},
  Voice_100355_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "Ах! Садитесь, Страж. Быть моим моделем - это трудная работа. Не беспокойтесь, я определенно создам для вас удивительную картину."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_100356_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Художник должен видеть только своё произведение и не обращать внимания на чужие взгляды, но я не могу этого сделать… с первого момента, когда я взял в руки кисть, я хотел передать истинную красоту всем."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_100357_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Это напоминает мне о тех временах, когда я был в художественной академии. Хотя профессора и студенты, в основном, были полными невеждами в искусстве, всегда находились один-два понимающих человека, которые могли увидеть красоту в моих работах."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Какое безумное искусство создаст это дикое представление?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Моя палитра!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "Боль тоже является искусством……"
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ах! Я вижу это... Слепой глаз, скрытый под бездной, космическая картина конечного мироздания... Пожалуйста, подождите немного, Страж, мы почти завершили!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_100362_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Моя кисть сделана из моих большеберцовых костей. Палитра, эти цвета я собрал на кладбищах двадцати городов... И моя драгоценная кожаная холст! Страж, возьмите это и нарисуйте мой портрет! Нет-нет-нет, вам не нужны никакие навыки живописи... Я уверен, что когда эта глубинная духовная Резонанс проявится на холсте, это будет самая прекрасная картина, которую я когда-либо мог представить...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_100363_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Я — Погоня за светом и Чёрная Чёрная тень, я — цвет, я... есть сама живопись!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Попробуй этот цвет!"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "Суть искусства заключается в безумии...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Вы имеете в виду, что в следующий раз можно попытаться сделать крупный план этой части в работе? Хмм... Я вообще не думал об этом! Какой гениальный поиск!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_100368_AwakerVoiceContent = {
    Text = "Осторожно!"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "Суть искусства заключается в безумии...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "Моя палитра!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "О! Эти плавные челюсти, яркие глаза, идеальная фигура и, и этот звездно-богатый духовный мир... Я Художник Пикман, могу ли я с честью пригласить вас стать моей моделью?"
  },
  Voice_100371_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_100372_AwakerVoiceContent = {
    Text = "Я верю в искусство, которое является безумным, беспокойным, музыка Гамельна совершенно иная, такая строгая, как те мрачные надгробия кладбища. Но почему-то, я всегда вижу в этих аккуратных нотах наибольший хаос из глубин Вселенной..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Разные разговоры: о Гамельне"
  },
  Voice_100372_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Хамлин\" будет разблокировано"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Смотри, Страж! Вечный, сумасшедший образ на холсте, как он пленителен, как же это безнадежно! Только в этом предельном безумии и боли зацветает искусство…"
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_100373_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ах! Извините, Страж... Я увидел на вас невиданные виды... Боязненные и привлекательные, более пугающие, чем бездны..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_100374_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Я действительно не понимаю, почему, если у людей есть возможность, они не становятся живыми мертвецами? Эта кроваво-сумасшедшая красота не интереснее быть бесстрастным человеком в большом особняке?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ха!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Наказание зла!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Наказание зла!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Я признаю, что у нее есть талант воровать, но леди не должна использовать такие подлые приемы, то, что я хочу, пусть все «добровольно» отдают мне, не так ли?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_117791_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Хахаха, мои, мои, все конфеты Митхага теперь мои! Что еще ждать? Следуй за этой ведьмой, и мы скоро захватим все кондитерские Лондиниума!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_117792_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Не дадите? Тогда эта дама точно предпримет меры!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Ты спрашиваешь, как начинка этих конфет попадает внутрь; совершенно не можешь найти никаких швов или дырок, я бы хотел, чтобы человек, придумавший эти конфеты, пошел работать в ресторан Митхаг и каждый день изобретал бы новые десерты для леди!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Ты разозлил ведьму!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Раньше я всегда считал, что конфеты слишком просты и не элегантны по сравнению с тортами. Теперь я понимаю, что недооценивал эти маленькие вещи в цветных пластиковой обертке. Особенно по сравнению с тортами, у этих конфет срок годности гораздо длиннее. Не бойся испортиться, и я хочу накопить их столько, сколько смогу!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Ты нашел новый вид конфет? Дай-ка посмотрю... Что это? Эта кольцевая конфета выглядит слишком смешно, разве есть кольца размером с яйцо?! Постой, что ты имеешь в виду, даруя мне кольцо? Объясни мне ясно!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_117797_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Говорят, что за ведьмой обычно следует таинственный черный кот, выбрать ту дикаю кошку из кампуса, это слишком неприлично для леди, так что решено, пусть ты носишь кошачьи ушки, чтобы быть моей маленькой черной кошкой."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_117798_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Сопротивление бесполезно."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "Ля-ля-ля!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "В мире действительно есть ведьмы? Они живут одни в лесах, где даже нет тени человека. Кто готовит им еду, стирает белье и делает десерты? Если они не могут поесть даже полдник, то в чем смысл такой жизни? Я задумываюсь об этом и не выдерживаю."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_117801_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "Ведьма пришла!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "У тебя еще есть шоколад? Отлично, отдай мне его. Что такое? Твое — это мое, разве это не законно?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_117803_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Ты спрашиваешь меня, какая конфета мне нравится больше? Дай подумать, ореховая карамель имеет хороший послевкусие, шоколад с карамелью тоже вкусный, классическая мягкая конфета с клубничной начинкой и травяная начинка действительно интересные, есть еще одна, которую можно тянуть очень-очень долго - она цвета меда... Не могу выбрать, каждая конфета уникальна, в любом случае, в тыквенной корзине их много, так что какую захочу, такую и возьму!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_117804_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Моя текущая жизненная цель — попробовать все конфеты в мире; стоит только подумать, что существует так много не счесть конфет, которые ждут меня, как я полон мотивации просыпаться каждый день. Ты говоришь о торт? Торт — это моя другая жизненная цель."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_117805_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Не смотри на него, хоть он и выглядит как ребенок, на самом деле он стар, его уже давно пора в землю закопать. Не говоря о конфетах, его не интересует ничто, что нравится живым. Поэтому сладости, которые ты хочешь ему подарить, лучше отдай мне, я тот, кто не подведет их."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Болтовня · О Тулу"
  },
  Voice_117806_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Если я стану ведьмой, я должна быть ведьмой, живущей в роскошном дворце, в дворце должно быть шумно и весело, я найму десять лучших поваров, чтобы они каждый день готовили для меня разные торты и конфеты... Ты говоришь, что это называется принцессой? Что ж, я могу быть принцессой-ведьмой!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_117807_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Эй, быстро приготовь несколько видов зубной пасты, нет, я не ел много конфет, у меня нет кариеса, просто немного болело, когда я спал ночью……"
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Болтовня·о конфетах"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Хотя правила ресторана Митхага часто раздражают, их умение готовить десерты, хм... все же терпимо."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "В этом мире действительно существует столько темных, отвратительных мест; вместо того, чтобы беспокоиться о разрушении мира, лучше съесть несколько конфет до этого."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Ой!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Хотя теперь нет тех ковров из ягнячьего меха, ожерелий из черных жемчугов и шелковых пижам из Востока, но просыпаться каждый день в комнате, заполненной конфетами, и, тянув руку, касаться полного ведра с тыквой, такая жизнь, возможно, и есть то, чем должно быть счастье... Эй, не смей радоваться так самодовольно, тебе еще предстоит служить этой барышне!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_117812_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Проклятый Митхаг, осмелившийся отвлечь меня от конфет, как бы не так, я же их съел!"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Что происходит? Ты хочешь сладостей? Хм, я не против великодушно одарить тебя, давай, позови меня, великая ведьма, послушаем!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Как это можно назвать грабежом? Я просто осуществляю благородные права леди."
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "Ведьма сладостей справедливости пришла, все потерянные конфеты должны вернуться на свои места!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Проклятый, скупой, я буду помнить тебя, ведьма……"
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Почему эта маленькая мышь может без страха искать конфеты, а я — нет? Вы это намеренно делаете против благородной леди! Непочтительно!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Не дадите? Тогда эта дама точно предпримет меры!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Позволь мне угостить тебя конфетами!"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "Сравнивая с теми официантами в ресторанах, ты все же самый понимающий, знаешь, как подготовить мне порцию конфет, продолжай в том же духе, мой личный Сквайр."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_117821_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Ля-ля-ля!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "Слишком уж!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "Зачем ты меня остановил? Как верный Сквайр госпожи, ты не должен был делиться со мной всем, что ты украл... Почему бы и нет?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Стой! Ограбление! Я настоятельно советую тебе быть покладистым и сдаться, иначе, хе-хе…"
  },
  Voice_117825_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_117826_AwakerVoiceContent = {
    Text = "Мягкие, твердые, хрустящие, рассыпчатые, молочные, фруктовые, ореховые, шоколадные… Ах, как же в этом мире может быть столько видов конфет, которых я не пробовал? Решено, предлагаю Митхагу отмечать праздник всех святых раз в неделю!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "Великая ведьма непременно победит! Бог конфет защищает меня, а я защищаю все конфеты! Ахахаха!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Сопротивление бесполезно."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Все сладости в конечном итоге будут принадлежать мне!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Этот ребёнок слушается так странно, что даже пугает, сто лишь ты попросишь у неё конфеты, она сразу же даст, даже одну себе не оставив, чувствуешь, что как-то неловко… хм, я имею в виду, раз она такая умная, милосердная ведьма, конечно, оставит ей немного в качестве вознаграждения."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Разговоры · О Лили"
  },
  Voice_117831_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лили\"разблокируется"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Ты разозлил ведьму!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Я разозлилась!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Все сладости в конечном итоге будут принадлежать мне!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "Что ты говоришь, эти зефирные конфеты можно жарить? Эй, разве они будут вкусными, горячими и липкими? Дай мне попробовать? Хорошо, тогда я попробую кусочек, если осмелишься меня обмануть... Ммм?! Эта хрустящая, мягкая текстура так вкусна!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_117835_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Безумие, искажение, это всё Колесо Судьбы!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Безумие, искажение, это всё Колесо Судьбы!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Поскольку ты сталкивался с настоящим ужасом, ты не боишься настоящего меня? Хм, это действительно хитрый Лечение, но он только усиливает моё любопытство к тебе..."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_123312_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Каков мир в твоих глазах? Где находятся эти ужасные границы? Нет, я не хочу слышать о них, я хочу вместе с тобой испытать, ощутить это безумие, смерть, ужас. Я решила! Я не покину тебя, пока не удовлетворю своё любопытство."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_123313_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Неуправляемый сумасшедший? Ты прав. Здесь не мой мир, нет тех скучных законов и правил... Здесь я могу делать все, что захочу, так что, Страж, будь осторожен, не дай себя укусить безумным, вышедшим из-под контроля."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_123314_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Для моего душевного и физического здоровья, хочешь провести глубокую беседу? Ладно, давай начнем быстрее, чем раньше начнем, тем быстрее закончим это скучное дело."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_123315_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Я просто притворяюсь нормальным, отвечая на твои вопросы? Ах, ты всё-таки меня раскрыл — так что, ты готов увидеть моё настоящее лицо?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_123316_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Срублю тебе голову."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "Всем, независимо от пола и возраста, нравится смотреть! Сияющий☆Мальстрём——!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Не я должен был упасть..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "Удар шторма!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Ты хочешь спасти этот искажённый, ужасный мир? Какой безумный и интересный способ умереть — дайте мне посмотреть, как далеко ты сможешь зайти."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Малыши, хотите попробовать мой топор? Не спешите, он уже идет..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Страж, мне кажется, я вижу Погоня за светом, неужели это... Не знаю, как там наши коллеги из расследовательской группы? Только не оставляйте мне кучу работы, я не хочу задерживаться."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_123776_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Я смогу вернуться домой через этот ритуал? Ты уверен? Сколько раз я уже пытался... Ладно, в любом случае, попробовать не повредит."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_123777_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Ха-ха, действительно, по сравнению с скучной повседневной жизнью, такая жизнь с адреналином больше подходит мне!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ха!"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "Не я должен был упасть..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Сияющее☆Суперновая——Излучение!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Всем, независимо от пола и возраста, нравится смотреть! Сияющий☆Мальстрём——!!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "Теперь ощущение... как будто вошёл в туман. Говоря о тумане, я снова вспоминаю тех маленьких ребят в тумане. Как жаль, что в плохом настроении не могу снова выплеснуть на них свои эмоции."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_123783_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Ненавижу? Я бы так не сказал, я просто искренне надеюсь, что все скучные встречи, социальные мероприятия и универсальные ценности исчезнут."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Вот так... Я чувствую, что становлюсь всё ближе к «настоящему себе»."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ах, неудача, которую я ожидал. Жизнь такова: взлеты и падения, со временем привыкнешь... Но все же спасибо за твою попытку."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_123786_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Как и туманная катастрофа, я ничего не знаю о растворении. Именно это делает их такими увлекательными, не так ли?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Мушетт, расследовательская группа... о нет, теперь я уже не форвард расследовательской группы. Итак, позвольте мне представиться заново — меня зовут Мушетт, просто милая девочка~"
  },
  Voice_123788_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_123789_AwakerVoiceContent = {
    Text = "Уходи!"
  },
  Voice_123789_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Здесь слишком близко к человеческим поселениям, повсюду скучные взрослые... Не думали ли вы перенести школу в безлюдные горные леса?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Я уже начинаю влюбляться в это чувство блуждания в другом мире, мощный Пробуждённый, ужасное Растоврение и неизвестные божества! Ах, всё это — наслаждение, вдали от обыденного общества!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Ещё есть? Я как раз наслаждаюсь игрой — давай, кто даст мне ещё раз рубануть топором."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Одна неудача ничего не значит... как бы не так. Вы все хорошо помойте шеи и ждите меня!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Есть задание? В следующий раз не нужно здороваться, мы уже настолько близки, что не нуждаемся в «социальных ритуалах встречи»."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Жертвовать собой ради других – это действительно глупая и раздражающая мысль. Никто не может требовать этого от других, даже боги."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Сальвадор"
  },
  Voice_123797_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Сальвадор\" разблокируется"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Неплохо——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Наконец-то не нужно больше притворяться... А теперь, давайте хорошенько повеселимся."
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "Церемония ещё не закончилась? Так хочется скорее вернуться и поесть рыбу, тушёную с Ривенрогом, выпить горячий фундуковый кавовый чай, конечно, здесь также неплохой цейлонский чай и андалусийская Чуррос."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_123800_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Постоянно повышая мои способности, ты не боишься, что однажды я выйду из-под контроля? Хахаха, шучу."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "На самом деле, временно остаться в этом мире тоже неплохо. Я запомню всё, что здесь происходит, запишу и потом поделюсь с теми, кто остался там. Хм, назовём это «Приключениями Моши в другом мире», звучит здорово, не Правда ли?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_123802_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Я признаю, что она очень милая... Да, верно, смотреть, как она гоняется и дерется с дикими кошками, бродящими по кампусу, действительно мило."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Болтовня: о Мерфи"
  },
  Voice_123803_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Хотя эта Огромная Огромная сила не может вернуть меня в мой мир, стать сильнее всегда хорошо."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Горничная, я тоже пробовал, найди время, чтобы показать ей мой способ сражаться с помощью пылесоса!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Гарене"
  },
  Voice_123805_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Гарен\" будет разблокировано"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Ха-ха, действительно, по сравнению с скучной повседневной жизнью, такая жизнь с адреналином больше подходит мне!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Смертельный Удар."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Стойте в очереди по одному."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "Аннигиляция!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Не думай и не беспокойся, слепо слушай и молчи, мирская суета — это бремя!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Не думай и не беспокойся, слепо слушай и молчи, мирская суета — это бремя!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Вы спрашиваете, почему у них пусто в голове? Хм, возможно, они такие родились."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Успокойся и не злись, всё будет пустым."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "Такое усердие действительно заставляет меня не удержаться от желания пофлиртовать с вами."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Ой!.."},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Вы ожидаете, что я стану более красивой или более устрашающей?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Тот принцесса, родившаяся из радости, её Наряд вышито золотыми нитями, кожа как слоновая кость, аромат агарового дерева витает вокруг неё, а её глаза, сверкающие, заставляют людей терять рассудок."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_126953_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Очень скоро Она устала от такого веселья, её последователи Просто постоянно повторяли одно и то же, поглощённые страстью, родившейся из любви, или любовью, родившейся из страсти. Их страдания и предательства доводили их до отчаяния. Их глупость вызывала у Нее скуку, их слёзы тоже вызывали у Нее скуку."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_126954_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Ваши мелкие взгляды действительно вызывают у меня отвращение."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "Та самая Дама в алом несколько раз присылала мне приглашения на салон. \n Вкус иностранной выпечки довольно неплохой, но... \n Ей следовало бы раньше сообщить мне, что в её доме сладости и слуги — это не одно и то же."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Чат: О Солер"
  },
  Voice_126956_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Солер\" будет разблокировано"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Разве это не любовь? Почему же вы боитесь, когда окружены? Разве это не отвращение? Почему же вы плачете, когда невозможно вернуться? \n Ах, теперь вы боитесь тени меня, аромат белой магнолии стал тем сладким и отвратительным, что вы не можете понять?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_126958_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Ага!"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Эй? Вы спрашиваете меня, почему они делают такие узоры под мышками? Разве вам это не кажется очень забавным?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Чат: О толстом народе"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Ой!.."},
  Voice_126961_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "По сравнению с приношениями последователей, это больше соответствует моим желаниям."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Сначала манеры, затем фигура, пока у Них тоже не появились... или, скорее, не остались в памяти только одни красивые, завораживающие глаза — такие же, как у меня."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_126964_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Мне сегодня действительно страшно скучно, у вас нет желаний, которые нужно осуществить? \nКак жаль, что ради каких-то скучных целей так много людей готовы взять в руки косу и принести мне жертву. \nНо если это вы..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_126965_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Почему Юнжун-чжун следуют за мной и зачем были созданы? Интересный вопрос. А у вас бывал кто-то, кого вы желали, но не могли обрести? Сожаление о том, что сил не хватило?\n\nХм, похоже, что нет. Как жаль.\n\nВыражение отчаянной борьбы в безвыходном положении на вашем лице было бы очень～очень занимательным."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_126966_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Если вы снова будете так дерзки, то я не уверена, что смогу встретить вас с таким же обликом."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Её история, я почти забыла её, но это история о радости, история о жестокости, история, которая сначала о предательстве и возмездии, а потом о жертвоприношении и слепом следовании."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_126968_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Угодите мне, самоповреждайтесь в боли и страхе~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...это действительно пробудило во мне некоторый интерес."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Каждый сможет увидеть лицо своего любимого человека под моим веером. Я одалживаю эту силу слабым, становясь Клинком, чтобы развлекаться. \n Но, возможно, я просто говорю, возможно. \n Если вы захотите быть очарованным этим, я испытаю истинное, безмерное блаженство."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_126971_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Не волнуйтесь, вы отличаетесь от них, этих обывателей. \n Тсс, не смотрите за меня, не обращайте внимания на невидимые прикосновения — смотрите мне в глаза."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_126972_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*легкий смех Вы осмеливаетесь взглянуть на моё истинное лицо?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "Шумно."
  },
  Voice_126975_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "Что? Снова смотрите на мой веер, захвачены? \n Хе-хе, независимо от того, кого вы хотите увидеть под веером, я исполню ваше желание... Подойдите ближе — \n Эй, не надо? Говоря такие холодные слова, ваше выражение лица так мило..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_126976_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Вы не в сновидении, что вы хотите найти?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Успокойся и не злись, всё будет пустым."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Нельзя быть непочтительным."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_126980_AwakerVoiceContent = {Text = "Ага!"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "У меня тоже была такая красивая, покорная девочка. \n Привлекательный бутон цветка, конечно, нужно добавить немного шипов, чтобы её нельзя было поставить в вазу."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Чат: О Лили"
  },
  Voice_126981_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лили\"разблокируется"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "Академия решительно отклонила мою заявку на работу в психологическом кабинете, странно, что же не так?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Всё в конечном итоге вернётся к Пустоте, почему бы не развлечься со мной немного?\nНе волнуйтесь, если однажды вы не сможете сопротивляться, я не позволю Ему забрать вас первым."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "Скучно."
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "Вы действительно удивительный человек, в мире, который неизбежно погибнет, вы так увлечены множеством посторонних дел. \n Это даже вызывает у меня интерес."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_126985_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Не подходи близко!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Я — Владычица земли Безгрезья, Сюй. Если в вашем сердце есть человек, которого вы хотите увидеть, но не можете, я готова убрать веер, чтобы вы могли его увидеть."
  },
  Voice_126988_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_127088_AwakerVoiceContent = {
    Text = "Все детеныши живых существ — настоящая головная боль. \n Маленькие, мягкие, шумные, они невольно приводят всё вокруг в беспорядок. Мне нравится веселье, но вот такое веселье мне не по душе, прошу вас, держите их подальше."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Моя маленькая жасминка, мой хороший малыш, Терпеливо сносить погружаться в эту игру с куклами~\n Ах, некоторые радостные бредни, вам не стоит беспокоиться."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "В легенде о Царстве Паньлун павлин — это прекрасное и кичливое чудовище.\nПрекрасное и злое, его имя вызывает трепет, а если бы оно было уродливым и добрым, то это было бы довольно скучно."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Съешь, съешь, всё съешь"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "Гуру гуру~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Уголёк, я, поесть, вместе? Вместе!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_129653_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Моск! Очень сильно!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Бездна! Спираль! Разрушение! Все——станьте вихрем!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Ой!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Не трогай меня, не надо! Не трогай меня, сломается!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_129657_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Ракушка, сверкающая! Сверкающая, красивая, для тебя!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_129658_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Холодно, страшно, Моск, спрячься!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Чат: О дора"
  },
  Voice_129659_UnlockDesc = {
    Text = "После получения пробуждающего тела \"дора\" будет разблокировано"
  },
  Voice_129660_AwakerVoiceContent = {Text = "Аа-ха!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Охота, проклятое! Сломайся! Моск, бей их, сломайся!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Так весело! В следующий раз! Ещё хочу!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_129662_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Погладь, хорошо! Моск, ты, погладь!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Нет, не надо! Уголёк, Моск, защищай!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Повторная попытка? Повторная попытка!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Хехе, Моск, давай играть!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "Большие волны идут!"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_129668_AwakerVoiceContent = {
    Text = "Брось!"
  },
  Voice_129668_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Ой!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Ух ты!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "Ритуал?! Возьми меня с собой!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_129671_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Мальстрём! Огромная Огромная сила! Палка!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_129672_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Бах!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Ура!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "Ху-ла-Ху-ла~"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_129676_AwakerVoiceContent = {
    Text = "Драка!"
  },
  Voice_129676_AwakerVoiceTitle = {
    Text = "Чат: о Голиафе"
  },
  Voice_129676_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Голиаф\" разблокируется"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Нашёл много, блестящих!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_129677_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Бездна! Спираль! Разрушение! Все——станьте вихрем!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_129679_AwakerVoiceContent = {
    Text = "Вау-уу!"
  },
  Voice_129679_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Ух ты!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Моск! Очень сильно!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Съешь, съешь, всё съешь"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "Наутилус, Наутила, Уголёк! Сверкающий!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Моск, заряжай!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Навык: II·зарядка один"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Моск, убираться!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Навык: II·Заряжай! II"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Объятия! Моск! Нравится!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_129686_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Уголёк, Близкий Близкий друг! Моск, навсегда!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Побыстрее, побыстрее!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_129688_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Моск! Уголёк! Вместе, всегда? Навсегда!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_129689_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Ух, ух! Поднимите большие волны!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_129690_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Друг! Так много! Нравится!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Моск! Как здорово!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Наутила, хочу увидеть. Эй, Наутила, Моск, Моск!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Чат: О Нодире"
  },
  Voice_129693_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Нодира\" будет разблокировано"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Становиться сильнее!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Я! Моск! Привет!"
  },
  Voice_129695_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_130511_AwakerVoiceContent = {Text = "Фу——"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Навык: Часть 2·Загрузка III"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "Ошибка будет исправлена."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "Трагедия, что вы узрели, — лишь мимолётный взгляд на одну из бесчисленных возможностей. Приподняв завесу судьбы, я увидела ту тёмную сцену. Свет погас, зрители разошлись, всё сущее вернулось в бездну хаоса. И всё же… это не финал. Моя воля ещё жива — её довольно, чтобы вынести этот тщетный труд и дождаться, когда вспыхнет новый луч света."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Судьбы всех людей направляются нитями… Но ваша Колесо Судьбы — это сценарий, который мне не дано прочесть. Мне не терпится увидеть, какую блистательную импровизацию вы подарите этому миру."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Марионетка в главной роли, выходи на свою сцену."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Хм?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Всё минувшее — лишь пролог. Новая глава для нас с вами ждёт, чтобы вы её написали, Страж."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_133725_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Если вам по душе комедии, «Сон в летнюю ночь» — прекрасный выбор. Мне особенно по нраву лукавые речи Пака: в смехе эльфов всегда таятся тайны, что Колесо Судьбы обронила невзначай."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_133726_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Да будет так."
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "Прялка начинает вращаться."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "О жалкий узник судьбы, прими свой предначертанный приговор."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Даже та, кто прозревает все сущее, остаётся лишь неуклюжей актрисой в собственном сценарии. Она властвует над паутиной судеб, но сама в итоге опутана пряжей. В этих предначертанных обстоятельствах мы идём разными путями, но ни одна из нас так и не отказалась от тщетных поисков. Глупость ли это, безумие ли — я такова, и она тоже."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Беседа: о Тави"
  },
  Voice_133730_UnlockDesc = {
    Text = "Получить пробуждающее тело \"Тави\"открывает доступ"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Неожиданный поворот?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "Благодарю вас за то, что были рядом, пока поднимался и опускался Занавес опускается. В будущем я непременно оправдаю ваши ожидания и подарю вам ещё более захватывающие театральные вечера."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_133732_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Столь одарённая певица с голосом, дарованным небесами, — чистым и пылающим, словно сам глас судьбы… Если бы удалось пригласить её в мой театр, уверена, даже самые взыскательные зрители были бы поражены."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Беседа: о Тинкте"
  },
  Voice_133733_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тинкерт\"разблокируется"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Ваша и моя — те две нити судьбы, что невозможно разглядеть, — давно переплелись неразрывно, сплетаясь в клетку и в путь. Я не могу различить границ клетки, не могу увидеть Конец пути. И именно это — самая завораживающая часть нашей истории."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_133734_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Нити судьбы уже ниспали."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Она часто приходит в мой театр… Но я знаю — она приходит не ради спектакля, а чтобы на фоне этой сцены подчеркнуть собственный стиль. Однако столь безупречное актёрское мастерство жаль тратить лишь на роль зрительницы. Ему суждено сиять в лучах софитов, а не скрываться в тени зрительного зала."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Чат: О Солер"
  },
  Voice_133736_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Солер\" будет разблокировано"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Однажды я слышала его игру — та чудесная мелодия заставила душу трепетать… Быть может, стоит пригласить его сочинить симфонию судьбы для моей новой постановки?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Разные разговоры: о Гамельне"
  },
  Voice_133737_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Хамлин\" будет разблокировано"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Ещё одна завершённая история опускает свой Занавес опускается."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Бесконечная сеть судьбы — я узрела её целиком."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Если вы позволите… я хотела бы соткать спектакль для двоих — только для вас и для меня. Без зрителей, без репетиций… Я лишь предвкушаю тот миг, когда вы встанете в луче света, и та нить, что я не в силах разглядеть, явит свой поразительный трепет."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_133740_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Несчастная танцовщица… Я видела её танец. Это красота на грани гибели — каждый поворот зажигает зелёное пламя, пытающееся сжечь нити судьбы. Но увы, в конце концов эти нити рассекут её, создав самый трагически прекрасный узор. Если представится случай, я хотела бы написать для неё балет — только для неё одной."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Беседа: о Лиз"
  },
  Voice_133741_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лиз\" будет разблокировано"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Здесь я пряду, здесь взвешиваю, здесь выношу приговор."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Утихни…"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Ещё одна нить стала отчётливой."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Занавес для вас распахнут, сценарий судьбы ждёт своего часа. Скажите, по какой предначертанной колее вы предпочтёте ступить? К трагическому финалу или к радостному прологу?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_133745_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Я и впрямь упиваюсь этим ежедневным прядением… В мерном и тихом натяжении нитей я провижу начала и концы бесчисленных историй, наблюдаю, как опускается Занавес опускается над каждой судьбой, словно уже вознеслась над самим роком. Однако от сети судьбы не укрыться, и вечно оставаться лишь наблюдателем — в конце концов одиноко. И тогда я вступила в театр, чтобы в игре на сцене самой вкусить те радости и печали, что спряла собственными руками, но никогда не переживала."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Нгх…"},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Хм…"},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Здесь я пряду, здесь взвешиваю, здесь выношу приговор."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "Шёпот судьбы — всё ближе."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "В театре поставили новую романтическую комедию. На предначертанном судьбой месте я оставила для вас свободное кресло. В каждую долгую ночь, когда переплетаются нити судеб, я буду ждать звёздного света нашей встречи."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_133751_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Так настойчиво касаетесь нитей судьбы… Вы тоже желаете заглянуть в свою собственную главу?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Будущее уже здесь."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Если вы готовы вступить в чертоги трагедии, позвольте представить вам «Антигону». В противостоянии божественного закона и мирского она ступает по нитям, сплетённым судьбой, пока не входит в глубокую Чёрная Чёрная тень каменной гробницы. Именно потому, что эти оковы невозможно Разрыв, воля, рвущаяся из её хрупкого тела, пылает подобно одинокому пламени в бесконечной ночи."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_133754_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Из бесчисленных исходов не вырваться из сетей причин и следствий…"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "На прядильной нити я вижу переливы радужных красок — они сплетают бесконечные сети, расстилают безбрежные миры, раскрывают бесчисленные возможности и в конце концов ткут самый великолепный и пёстрый узор на свете. Будь то боги или смертные, герои или злодеи — все они направляемы тончайшей нитью и под взором судьбы безоглядно устремляются к своему предначертанному финалу."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Я полагала, что в этом мире уже ничей выбор не способен меня удивить… Ваш вкус в драматургии произвёл на меня впечатление."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_133757_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Нити судьбы всегда сплетаются во тьме… Вы потревожили эту нить, а вместе с ней — и меня."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_133758_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Я никогда не желала видеть одни и те же шаблонные постановки. Смысл похода в театр в том, чтобы пережить неповторимое действо, которое невозможно Воссоздать. Если каждый спектакль — лишь механическое повторение, то сцена превращается в изящную клетку, а просмотр — в утомительное паломничество к заранее известному финалу. Такое представление, сколь бы роскошным оно ни было, лишено души. А как вы считаете?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Нити судьбы текли в моих ладонях размеренно и упорядоченно… пока ваше появление не породило в их траекториях непредвиденную рябь."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_133760_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "О жалкий узник судьбы, прими свой предначертанный приговор."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Среди бесконечных нитей я пряду единственную траекторию."
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "На сцене судьбы все живые существа ожидают своего выхода, каждый в своей причинно-следственной связи, и бесчисленные радости и горести тихо складываются в историю меж вращающихся шестерён… Занавес поднят, Страж Тайн, — наша с тобой история начинается прямо сейчас."
  },
  Voice_133763_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_133764_AwakerVoiceContent = {
    Text = "Раздор грядёт. Кого вы сыграете — героя, разрывающего сеть, или покорного судьбе статиста?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Тщетное сопротивление."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Спасибо. Я буду бережно хранить этот Подарок."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Я столько изучила о строении Пробуждённых, что уже могу считаться экспертом. Но вот эта штука — «духовность» внутри Серебряного Ядра — всё ещё не совсем понятна…"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_139866_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Вот оно… Начало нового мира…"
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "Я могу делать такие вещи. Перестраивать тела других существ, настраивать их…"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_139868_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Что и где нужно настраивать — зависит от вида существа, так что без усердной учёбы никак не обойтись."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_139869_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Тебе не страшно, как я выгляжу? Эх, как-то скучно…"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Я не позволю никому помешать нам."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Я готова!"
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Живые существа и Правда полны разнообразия! Хочу узнать ещё больше!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Хочешь поиграть вместе с Саей?"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_139876_AwakerVoiceContent = {Text = "А!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "Вот оно… Начало нового мира…"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Наелась, спасибо за угощение!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Страж, ты когда-нибудь любил кого-то, скучал по кому-то?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_139880_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ой!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "Это здесь?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Устал(а)? Удалось что-нибудь хорошее найти?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "После множества проверок я в целом разобралась. «Духовность», которой обладает каждый Пробуждённый, совершенно уникальна. А духовность в моём Серебряном Ядре, похоже, — это «любовь»."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_139884_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Ну как, испугался?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Это для тебя — мой последний Подарок."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "«На одной из этих звёзд цветёт мой цветок…» — так он говорил.\nТы тоже говорил что-то похожее, Правда?"
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_139887_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Эта штука под названием «Серебряное Ядро», похоже, связана с какой-то очень далёкой волей. Как удивительно…"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_139888_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Это для тебя — мой последний Подарок."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Ой!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Маленький принц сказал, что именно его забота сделала розу особенной… Ты тоже так думаешь?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_139892_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Вчера я увидела на книжной полке Лили книгу под названием «Маленький принц». Я её одолжила. Хочешь почитать вместе со мной?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_139893_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Угу, я также изучила Построение Серебряного Ядра, и постепенно начинаю понимать общие очертания Пробуждённых."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_139895_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Ой!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_139897_AwakerVoiceContent = {
    Text = "Хей-сю!"
  },
  Voice_139897_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Прошу вас меня направлять!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Здравствуйте!…Так правильно говорить?\nЯ Сая. Хм… приятно познакомиться—"
  },
  Voice_139900_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_139901_AwakerVoiceContent = {
    Text = "Есть такой цветок — одуванчик, он отпускает свои семена по ветру. Пушистые семена уносятся ветром далеко-далеко от родного дома, и, может быть, упадут в пустыне, где нет ни единой травинки. Интересно, о чём думает такое маленькое семечко в такие моменты…"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_139901_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Сколько бы раз ни делать — всё равно интересно!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_139903_AwakerVoiceContent = {
    Text = "Хэй——"
  },
  Voice_139903_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "Опасно——"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Обожаю вкусную еду! И ещё люблю людей, которые добры к Сае. Когда ко мне относятся ласково, мне Правда очень радостно—"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Это тот, кто меня пробудил? Какой-то ослепительный… Хм~ А ты помог ей найти сестру?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Беседа: о Тинкте"
  },
  Voice_140534_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тинкерт\"разблокируется"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Каждый раз, когда Сая хочет побыть с Хранителем тайн наедине, вокруг собирается куча странных людей. Мне больше нравится, когда мы в Тайном мире—"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Вот оно что. Поняла!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Страж, связь, пробуждённое тело — это ты объяснил мне наши отношения, да? Я чувствую, как наши души связаны… серебряной нитью? Или чем-то таким, хм— В общем, всё это так сложно понять…"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Переносить семена с помощью плоти и крови? Хм~ Вот оно как. Мне немного любопытны её овечки."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Таис"
  },
  Voice_140538_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тайис\" разблокируется"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Некая угроза этому миру, тьма, которая ведёт к исчезновению всего сущего, верно? Я знаю. Профессор Доэл мне много рассказывала."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Не люблю грубых людей. От них становится неприятно…"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Её раса, похоже, тоже получает возможность размножаться на новых планетах, отнимая ресурсы у других видов. Хм~ Вот оно как…"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Болтовня: о Винкор"
  },
  Voice_140541_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Хороший ребёнок."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Эй!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Специальный навык·3"
  },
  Voice_141965_AwakerVoiceContent = {Text = "Ага!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Удар·Пять"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Как жаль. Когда передумаешь — ты знаешь, где меня найти."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_143501_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "Черт возьми..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Кожа, мышцы, нервы, кости — всё это будет перестроено заново, вновь здорово и цело, вновь полно жизни."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_143503_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Перед Океаном нет неуязвимых врагов!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Пиршество, Преследование, покровительство?\nМолись мне, и древнейшие воды поведают тебе моё имя.\nЯ — владыка бездны, Понтос."
  },
  Voice_143505_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_143506_AwakerVoiceContent = {
    Text = "Хм-хм, скучаешь по временам в Эпоянсе?…\nОн здесь, в этом теле, и всегда рад твоему возвращению."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Хотя я этого не делал, но если однажды в твоих ушах зазвучит морская вода и трепет крыльев — не беспокойся, это нормально."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Отдай свои чувства и вечно кайся в бездне!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Мне нравятся энергичные молодые люди. Жаль, что Мисаг слишком строго контролирует веселье — там даже нет ни одного приличного охотничьего угодья.\nК тому же, внутри есть эта мерзкая тварь, которая осмеливается открыто разгуливать и даже носит профессорский титул."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Нгх!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "Я столько всего сделал, а ты даже не хочешь снова назвать меня дядей. Это просто невыносимо."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Не торопитесь — Мрак из самых глубин Океана непременно поглотит вас."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Преклони колени и стань пищей для Эпоянс."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Специальный навык·3"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Что касается существа, избравшего меня… можно сказать, оно было одновременно добросердечным и жестоким.\nКуда уронить — целиком зависело от настроения. Тебя непременно спасут из беды, но будет ли то место, куда ты попадёшь, другой бедой — это уже не то, о чём стоит думать в рамках этого «путешествия».\nКак занятно, как непредсказуемо. Я подумываю продолжить эту традицию."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_143515_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Между мной и Эпоянсом существует особая связь. Вернее сказать, я и есть Эпоянс — Эпоянс держится на мне и существует через моё тело."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Чат: об Эпоянсе"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Подними голову и обнажи своё горло."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Стереть воспоминания, стереть существование. Что-то знакомое… Ты понимаешь, что я имею в виду. Источники разные, но похоже, Они всегда зарождаются там, где нет света."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Вы не должны были быть столь глупы, чтобы посягнуть на моё величие."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Слишком слабый."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "В Эпоянс веселье никогда не прекращается, и враги Эпоянс тоже никогда не обретут покоя."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_143521_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ах, я разделяю твой трепет, но в нём нет никакой необходимости, мой юный друг.\nПрими свой страх перед посредственностью и угасанием, посмотри на меня — и ты поймёшь, что у тебя всегда есть другой выбор."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_143522_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Да, я знаю, что та катастрофа произошла не по его прямому умыслу — лишь случайность в ходе его забав. Но это, очевидно, только усиливает моё желание убить его.\nЭтому чёрному туману лучше не оставаться в одиночестве и не попадаться мне в руки."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Эти склизкие Рыбочеловеки — не мои друзья, а мои враги. Удивительно? Океан никогда им не принадлежал."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_143524_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Навеки застынь здесь!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "Готовы, жертвы?!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "Духовность порождает новые тела, тела наполняются незначительными знаниями, а затем эти прекрасные и живые существа навеки собираются в одном месте.\nПомнишь, что я говорил? Самые глубины Океана вмещают всё… и удерживают всё."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_143527_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Кошмар, останови Их."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Надеюсь, эти малыши не разорят тебя вконец. Знаешь, прокормить целое семейство — дело непростое."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Очень давным-давно, ещё до того как суша поднялась из Океана, на этой планете пробудились некие особые духовные существа. Могущественные, величественные, недоступные для подсматривания.\nИх нельзя было определить ни как враждебных, ни как дружелюбных. Люди, как и бесчисленные создания до них, были для Них несущественны — их могли стереть, словно пыль, или защитить вместе с их землями."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_143530_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Лишь старость — это приключение, с которым тебе предстоит столкнуться в одиночку, твой лучший друг и самый несносный враг. Огни Эпоянса изгонят её без остатка… Просто несколько незначительных воспоминаний — тебе не нужно быть ими скованным."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_143531_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Оставьте иллюзии о Побеге."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Ты обратишься в серую пыль."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_143534_AwakerVoiceContent = {Text = "Хм!"},
  Voice_143534_AwakerVoiceTitle = {
    Text = "ударить"
  },
  Voice_143535_AwakerVoiceContent = {
    Text = "Весьма умно, дитя. Последователи чужеземных монстров всегда так глупы, что бросают трупы в море — но это ведь не считается подарком, не правда ли?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "За тобой уже следят."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Даже не желая признавать это, в редкие-редкие моменты я думаю, что старость — не единственное, что приносит время, а лишь один из символов.\nПоэтому я позволяю ей существовать во мне. Разумеется — только внешне."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "Молитва действенна. Представь: даже если червяки выстроятся перед тобой в буквы, ты всё равно задумаешься о том, чтобы ответить на их просьбу."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_143539_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Ха-ха-ха-ха, ну же, не делай такую Эмоцию, мой маленький друг.\nЭто всего лишь традиция, которой обязаны следовать так называемые «старые боги». Что касается тебя — никакой цены и никаких условий. Я буду на твоей стороне всегда."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_143540_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Хм, маленький монстр, якшающийся с чужеродными монстрами.\nНаходятся же идиоты, ставящие меня с ним на один пьедестал — это просто оскорбление!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Чат: о Тулу"
  },
  Voice_143554_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Враг моего врага — мой друг. Если представится случай, я не прочь провернуть выгодную сделку и отнять любимую игрушку у заклятого врага."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Чат: о Райкере"
  },
  Voice_143555_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лекк\" будет разблокировано"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "О? Хочешь схватиться со мной прямо здесь? Я не против."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Ещё, дай мне ещё больше силы!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Мне не нравятся нечистые люди, ведь нечистота обычно означает слабость. Но ты — исключение. Я когда-то думала, что человек, несущий на себе слишком много, не сможет идти вперёд. Однако Путь, который ты избрал, удивляет даже меня… Быть может, именно тот, кто идёт иной дорогой, и является наиболее достойным объектом для воспитания и вызова. Ты согласен, «Противник»?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Странствующий кит звёздных небес, Поглощение всего сущего!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Считай за честь стать моим Противником!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Пусть звёздное море станет Свидетелем Разрушения!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Недостаточно, далеко недостаточно…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Хм."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Хм."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Меня не волнует исчезновение всего и вся, но я не позволю ему стать помехой на моём Пути к Силе."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Из-за неизбежной Аннигиляции начинать Сомневаться в смысле всего существующего… Мне неинтересно участвовать в подобных детских пустых спорах. Разрушение — не важно, помнить о нём — незачем. Сама Сила и есть смысл."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Чат: о Долл: Преисподняя"
  },
  Voice_146168_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Расплавление·Дора\" разблокируется"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "В твоих глазах я вижу волю, чуждую этому месту. Она не чиста, но достаточно крепка. Что ж, докажи мне, какой силой и жаждой ты стоишь передо мной."
  },
  Voice_146169_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_146170_AwakerVoiceContent = {Text = "Ха!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Считай за честь стать моим Противником!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Дыхание Хаоса — как давно я его не чувствовал… С того самого момента, как я родился из этого Ускользания, то, к чему я стремлюсь, никогда не менялось."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_146172_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Хочешь бросить мне вызов? Я ценю твою смелость и готова даровать тебе честь быть побеждённым. Это моё уважение к «Хранителю Мисага»."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_146173_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "В этой фальшивой утопии теснятся слабаки, трусы и самообманщики-глупцы. Но неважно — здесь можно найти самых захватывающих врагов, и этого достаточно."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Обладать огромной Силой и при этом из-за Страха, вины и усталости заточить свой талант в долгом Сне — какое расточительство."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Чат: о Тулу"
  },
  Voice_146175_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Жалкое зрелище."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Запечатывание немного ослабло… Сила из глубин звёздного моря поднимается вверх. Я уже давно не ощущал этого чувства…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_146177_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Странствующий кит звёздных небес, Поглощение всего сущего!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Отменно."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "Я скиталась среди звёздных морей бесчисленные годы, собственными руками отправляя в бездну тех, кто мнил себя сильным. В тебе есть нечто особенное, но если хочешь идти рядом со мной — сначала научись поднимать голову в моём присутствии. Трусливые попутчики мне не нужны."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_146180_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Смелые, трусливые, стойкие, Хрупкие… Хм, нет, меня не волнует, каков Противник как человек. Любой достаточно сильный Противник способен доставить мне удовольствие."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Слабость. В этом мире бесчисленное множество отвратительных вещей, но слабость — самый постыдный первородный грех. Каждый приходит в этот мир с мечом в руке, и никто не вправе разжать пальцы до финала, ступая на предначертанное поле битвы с мыслями о поражении. Это оскорбление и для Противника, и для самого себя."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Осквернённые Звёздные останки, Очнувшись —"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "Хм… Достойный Противник. В следующий раз я уже не буду сдерживаться."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Мои кости дрожат от радости… Я видела твои усилия. Это доказательство того, что ты достоин стоять рядом со мной, Хранитель."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_146185_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Хм… Ты всё прекрасно понимаешь, Хранитель. Оковы силы созданы для того, чтобы их разбивать!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_146186_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Хм?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Хм?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Вот оно, впереди… Конец той Силы, которую я искала всю жизнь… Это ты шёл за мной всю дорогу и привёл меня сюда. Я с нетерпением жду того дня, когда мы вместе станем Свидетелями финала!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_146189_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Пожалуй, прежде я была слишком опрометчива в своих словах… Скорость твоего Роста и скрытая в тебе Сила несколько превзошли мои ожидания. Я видела слишком много жизней, поглощённых Аннигиляцией, но ты… действительно необычен. Мне очень хочется знать — откуда берётся тайна той Силы, что живёт в тебе?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_146190_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Врата преисподней, распахнитесь передо мной!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "Ах, я вижу… Конца Силы никогда не существовало… Истинное испытание лишь теперь открылось передо мной! Это ты привёл меня сюда и позволил мне увидеть всё ясно. Скоро я приведу к тебе ещё более совершенного воина. Надеюсь, что тогда я увижу и более совершенного тебя, мой «Противник»."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_146193_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Дешёвые трюки."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "Сила кипит в костях!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Поглощение без остатка!"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "Милосердие, слабость, растерянность… Твои глаза полны примесей. Человек, недостаточно чистый, никогда не поймёт, что такое Сила."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_146197_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Настоящая Сила никогда не имела отношения ни к мести, ни к защите. Сила — это Просто Сила, и другое моё «я» так и не поняло этого «по-настоящему». Вот в чём корень её слабости."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Чат: о Лотан"
  },
  Voice_146198_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Ротань\" разблокируется"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Слушай внимательно, я скажу это лишь однажды:\nЯ, Лотан, признаю тебя Противником, достойным Бдения.\nПока ты не достигнешь вершины, я буду самым надёжным клинком на твоём Пути. Моё обещание и Верность не связаны с эмоциями. Ты — самый приятный мне Противник, и я ни за что не позволю тебе пасть в дороге."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_146199_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Давай, убей меня. Или… будь убит мной."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Врата преисподней, распахнитесь передо мной!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Туда, куда обращено костяное лезвие, — всё рассыпается в прах!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Сила… не знает предела!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_147493_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(одно хриплое и спокойное пение)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Зрители, нужно больше зрителей.."
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Песок… белая пустыня… здесь очень опасно, быстро уходи со мной."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_147496_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Я ещё помню карту нового дома, она была яркой и очень красивой. Это то место, куда мы должны отправиться. Мы сможем петь, мы сможем обрести счастье."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_147498_AwakerVoiceContent = {Text = "А"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_147499_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Й...?"},
  Voice_147500_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "Это... голос звёздного свода.."
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Ты опять пришёл. Как в прошлый раз, сядь рядом со мной и давай вместе ждать. Чего ждать...? Ждать — значит просто ждать."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Идеальная Репетиция, думаю, я готов выйти на сцену."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_147503_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "Падай!"
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "В память о пустоте и смерти."
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "Я не сумасшедший, и никогда не чувствовал печали. Пожалуйста, не слушайте абсурдные слухи."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Странно, они, кажется, очень боятся моего пения.."
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_147508_AwakerVoiceContent = {
    Text = "Тише…"
  },
  Voice_147508_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Вот действительно красивый костюм для выступления, блестящий, блестящий.."
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_147509_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Оставшиеся до наших дней цвета звёзд."
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_147512_AwakerVoiceContent = {
    Text = "Пойте."
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "Правильная работа над дикцией...? Но я очень доволен своим звуком сейчас."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_147513_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Звук как будто изменился.."
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_147515_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Как вам моё пение? Хорошо звучит?"
  },
  Voice_147516_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_147517_AwakerVoiceContent = {
    Text = "Спи спокойно.."
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_147519_AwakerVoiceContent = {
    Text = "Хорошо."
  },
  Voice_147519_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_147520_AwakerVoiceContent = {Text = "А"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Спасибо... Я должна сказать спасибо?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_147522_AwakerVoiceContent = {Text = "Эх..."},
  Voice_147522_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "Засияй ярким светом."
  },
  Voice_147523_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "Долгожданное ощущение... Наконец снова вернулся на сцену. Благодарю вас, Страж."
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_147524_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Прошу прощения за Беспокойство... Вы не могли бы снять меня с дерева? Я не помню, почему забрался наверх, может быть, из-за облаков над головой, которые вызывают чувство ностальгии.."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Мой народ никогда не покидал меня, они просто ушли очень далеко, очень далеко ."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Болтовня · О роде"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "Слышали?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_147528_AwakerVoiceContent = {Text = "О."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Ты всегда крутишься рядом со мной... Я понял, ты, наверное, мой фанат, да?"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_147529_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Лалала~ Что, здесь есть бедствие, способное уничтожить мир? Ах... Тогда я должна тщательно причесаться и найти сестру.."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Шшш... не говори, пришёл плохой человек. Он хочет забрать меня и сестру, и не пускает нас на корабль.."
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О безопасности"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_147532_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Когда я проснулся, планета была в процессе уничтожения. Я увидел, как ночное небо отслаивается полосами, мир стал парусиной, наполненной сильным ветром, сначала деформировался, потом разорвался и разлетелся на куски."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_147533_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Это мой плакат с автографом, господин Пикман нарисовал его для меня. Я дарю его вам."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Фейнт"
  },
  Voice_147534_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Фейнт\" будет разблокировано"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Хм-хм? Любопытно? Сокровищницу крёстной матери нельзя просто так показывать посторонним. Если хочешь узнать, что там припрятано, — почему бы прямо сейчас не вступить в Культ фей? Хи-хи?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Ты не веришь выводам Карабу? Уу, значит, провести всех и правда сложно… На самом деле я — незаконнорождённая дочь @1 герцога Боэмунда VI, скрывающаяся под чужим именем среди людей. Я назвалась феей лишь для того, чтобы спастись от преследования врагов… Я уже открыла тебе самый важный секрет — неужели ты мне не поверишь?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_149668_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "Ой, больно~"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "Слишком много конфет? Нет-нет-нет, это же секрет улыбки крёстной матери — неужели можно остановиться из-за такой мелочи, как кариес? ~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Подойди, встань рядом со мной. Что? Разделить жертвенные дары со всеми?.. Ладно, если таков обычай Мисага… то я… я не имею ровно никаких возражений, давайте же, повеселимся все вместе!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_149671_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Ах, какой же благочестивый ягнёночек."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Ещё чуть-чуть, и фея одарит тебя своим благословением~"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Вы ещё слишком зелёные~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "На этот раз обряд поклонения будет куда торжественнее обычного, и жертвоприношений тоже понадобится больше… Ах, ну конечно же, никаких человеческих чучел! Я добрая фея и никогда не причиню вреда другим~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_149676_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Хранитель, вы уже готовы услышать искренние слова Карабу?\nОткуда пришла Карабу — совершенно неважно. Важно то, что вы — самый драгоценный дар, ниспосланный мне небесами, и Карабу уже решила навсегда, навсегда остаться рядом с вами, своим благодетелем.\nВы думаете, что это тоже часть хитрости, чтобы вы прекратили расследование? Хи-хи, как вы думаете?\nВ общем, в награду за то, что я сказала искренние слова, — можно дать Карабу одну яблочную мармеладку?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_149677_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Хи-хи~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Ничего страшного, в следующий раз сосредоточься на защите этой феи — и всё получится~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Не вздумай меня обманывать!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Ого, сколько же даров!.. Кхм, хм-хм, неплохо, заслуживает похвалы! Ну же, фея дарует тебе поцелуй феи! О чём ты думаешь — конечно же, в лоб!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_149683_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Благодарю всех верующих за подношения! Понимающая крёстная мать воздвигнет в храме золотую статую в вашу честь. Ах, чтобы эта статуя могла передать вашу величественную и прекрасную осанку, придётся ещё хорошенько постараться~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_149684_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Ты?.. Ты — непросветлённый член нашей церкви. Карабу терпеливо будет ждать дня, когда ты познаешь истинную суть мира. Когда это случится, не забудь принести главе церкви в дар своё тело, преданность и имущество, хи-хи."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Всё из списка… уже собрано? Финансовые возможности Мисага поистине безграничны… Знай я об этом раньше, я бы… хм? Что это я бормочу? Просто благодарю Лорда Декстера за щедрость, хи-хи~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_149686_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Что я ненавижу больше всего? Конечно же, колдунов без чувства договора. Открою тебе секрет: на самом деле все колдуны — великие обманщики, и все их пророчества и проклятия существуют лишь для того, чтобы оставить тебя без гроша! А способ защититься… просто позволь своим деньгам обрести благословение феи!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Приятно познакомиться, я — бледная фея из далёких краёв. Хочешь узнать подробнее? Милость феи бывает разной силы в зависимости от уровня членского взноса, хи-хи~"
  },
  Voice_149688_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_149689_AwakerVoiceContent = {
    Text = "В прежних обрядах поклонения, помимо семи поклонений и трёх клятв, верующие специально возводили для меня новый храм и подносили богатые дары. Вот список!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_149689_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Давай, похорони всё, от чего хочешь избавиться, в глубоком снегу…"
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "Я слышала, ты расспрашиваешь о моём происхождении, хи-хи, это тайна крёстной матери. Но если ты непременно хочешь разузнать — в Культе фей хранится биография, написанная мной лично. Достаточно внести сто тысяч Серебро, и сможешь её прочитать. Попробуешь?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_149691_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Замечательно, здесь много очень милых детей и возмутительно щедрые жизненные субсидии. С их помощью рано или поздно я накоплю достаточно денег на дорогу на восток…"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Не забудь поклониться крёстной матери, хи-хи."
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "Прошу прощения, владения феи — место священное, оборотни-незнакомцы здесь не принимаются… Что значит «в воздухе пахнет ложью»? Наверное, у него просто нос барахлит?"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Чат: о Райкере"
  },
  Voice_149694_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лекк\" будет разблокировано"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Ой, кто-то говорит, что я ненастоящая фея… Разоблачили, хи-хи. Я знаю, что тебе всё равно, правда?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Разговор · о слухах"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Ммм, как вкусно~"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Успокойся~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Заблудшие ягнята, эта фея явилась смыть ваши грехи, хи~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Всё ещё не сдаёшься? Ладно, пусть Карабу сама тебе расскажет. На самом деле Карабу — дочь богини Умапати, покровительницы высокой заснеженной горы на востоке… Хм, ты говоришь, что у той богини только два сына и нет дочерей? Ну, записи о богах всегда бывают неполными."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_149699_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Та-дам~ Сияние феи уже озаряет тебя, вперёд!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Ладно-ладно, хватит расследовать, хорошо? В качестве компенсации за то, что ты послушно прекратишь это оскорбительное занятие, я тайком поделюсь с тобой половиной самых драгоценных конфет. Знаешь ли, на полях сражений Восточного похода сладкие конфеты — большая редкость."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_149701_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "Благословение Карабу способно исцелить все болезни в мире, и конечно же, эту чёрную чуму тоже… Конечно, правда! Нужно лишь быть достаточно набожным и достаточно доверять Карабу, хи-хи."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_149703_AwakerVoiceContent = {
    Text = "Ненавижу!"
  },
  Voice_149703_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Сияние феи~"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Семь поклонений, три клятвы — обменяй их на прощение феи!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Почувствуй это!"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "Ой, как это Ожье вас пропустил? Разве не договаривались задержать всех? Вы его сюзерен…? Ненадёжный мальчишка — просто беда, я ведь потратила немало сил на подготовку к этому собранию. Может быть… разделим полученные подношения поровну, и вы закроете на это глаза?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Разговор: об Ожье"
  },
  Voice_150104_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Оргр\" будет разблокировано"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Давай закончим, не надо задерживаться на улице."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Он присоединился к ордену во время моего сна, у нас не было практически никаких точек соприкосновения.\nОднако, говорят, что он пришел сам. Желая отказаться от человеческой формы и стать полным «Плаватель морей»... хм, еще один Глупцы, ослепленный силой."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Разговоры · О Кекесе"
  },
  Voice_36679_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Голиаф никогда не был особенно преданным щенком, непонятно, почему Мириам так им дорожит... Если бы не цепь, он был бы первым, кто сбежал."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Голиаф"
  },
  Voice_36680_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Плаватель морей не родился с такой внешностью. Чтобы скрыться в толпе, их жизнь до середины ничем не отличалась от человеческой...\nТебе стоит быть внимательнее: возможно, владелец твоей любимой кондитерской — один из них."
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Разговоры · О Плавателе морей"
  },
  Voice_36681_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Хилестеровы расстроенные лодочные песни, фирменное блюдо капитана — копченое Инкарнация с тушеной свежей рыбой, одеяло, которое морской ветер сделал соленым и жестким... Хотя было опасно и напряженно, я никогда не забуду эти месяцы, проведенные с ними в изгнании на море."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Поболтать · О «Призрачном корабле»"
  },
  Voice_36682_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Хотя все в школе выглядят очень занятыми, но...\nно здесь есть спокойствие, которого я никогда раньше не испытывал.\nЧтобы собраться вместе ради одной цели и работать над ней... хм, вполне неплохо."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Разговоры · Об университете Мисаг · II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Кровать слишком жёсткая, погода слишком холодная, чай после обеда всегда получается как травяная вода... У девушки есть тысяча причин не любить это место.\nОднако, только благодаря «Потому что ты здесь», я могу остаться"
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Пустые разговоры·О Хранителе тайн: III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Спасибо, спасибо... Эй? Почему я должна тебя благодарить? Это... это же очевидно! Конечно, за всё, что ты для меня сделал на море... \nПодожди, почему ты смеёшься? Ты просто хотел увидеть, как я, девушка, попаду в неловкое положение, да?!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Хранителе Тайн · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Я думал, между нами с ней была родственная связь...\nНо после того, что случилось, я понял, возможно, те моменты теплоты были лишь моим самообманом с самого начала.\nКак ты хочешь поступить с ней - это ваше дело, только больше не позволяй ей приближаться ко мне."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Посторонние разговоры · О Мириам — 2"
  },
  Voice_36686_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Странно... Это действительно странно.\nСердце уже не бьётся, но тело ещё тёплое... Эй, подойди и потрогай мою руку, скажи, что это не Иллюзия."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О «пробуждающее тело»"
  },
  Voice_36687_UnlockDesc = {
    Text = "Разблокируется после прохождения главы 6 «расследовательской операции»"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Может быть, я не родился в Королевстве Рэо, но святилище стало для меня местом, где я обрёл вторую жизнь. Если так, то разве неестественно считать его своей родиной?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Пустая болтовня, о родине"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "После многих лет невидимой чумы, Боже-Отец наконец услышал мои молитвы и даровал мне это «благословение», способное противостоять страданиям. Оно действительно может дарить жизнь, но нужно плату. \nКак исполнитель, я естественно должен нести эту ношу за тех, кто получает благословение."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Пустые разговоры · О «благословении»"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Для меня состояние пробуждающего тела является даром Отца душам в его объятиях. Это вторая жизнь, возможность загладить прошлые ошибки. \n Я буду продолжать дело Отца, выполнять обязанности заместителя и устранять больше страданий."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О «пробуждающее тело»"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Позволь мне ещё раз выразить тебе благодарность, Страж. Ты уважил моё мнение и сохранил секрет от комитета по рассмотрению. Если бы они вмешались, то, скорее всего, не разрешили бы мне дальше работать на благо святилища."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Беседы · О Хранителе тайн · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Разблокируется после прохождения спецзаписи «Цвет крови»"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Тот ребёнок искренен, твёрдый, добр и обладает редкой светлой душой. В последний раз я встречал такого человека ещё в первый период своей жизни."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Оргр"
  },
  Voice_45157_UnlockDesc = {
    Text = "Разблокируется после прохождения спецзаписи «Цвет крови»"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Потеря зрения не означает, что я стал слепым. Отец-бог, Нисхождение Мрак погрузил меня, дал мне возможность видеть душа Погоня за светом."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О визуальном восприятии"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "Тогда я, хотя и получил «благословение», был всего лишь обычным человеком. Страдающих было слишком много, нуждающихся в «благословении» людей тоже было много. Я пытался спасти всё, но потерпел неудачу.\nЭто моё максимальное сожаление и вечное чувство вины."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О первой жизни"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Многие в Святом Престоле полагают, что «белое пламя», упомянутое в «Священном Писании», означает лунный Погоня за светом: бледный посланник явится из лунного сияния и выведет нас из страданий.\nНо я знаю — истинное пламя — это душа, пылающая в сердцах каждого из нас."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Болтовня · О «Бледном огне»"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "На самом деле, скрывать мою личность — это было решение архиепископа. Он не стал объяснять причины, лишь предостерёг: даже в самых чистых местах могут таиться тени, и творя добро, следует быть осторожным.\nРазумеется, тебе я доверяю полностью."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Пустые разговоры · О скрытии своей личности"
  },
  Voice_45161_UnlockDesc = {
    Text = "Разблокируется после прохождения спецзаписи «Цвет крови»"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Моё пение, стало ли оно вашей поддержкой?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Чёрт, он же тоже ребёнок, почему вы все так уважаете его! Относитесь к девушке с таким же уважением, понятно!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Болтовня · О Тулу"
  },
  Voice_4909_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Эй, ты знаешь, чем обычно занимаются другие пробуждающие тела? Не пойми меня неправильно, я не хочу заводить друзей, просто хочу... да, я просто хочу провести осмотр!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Поболтать·О повседневной жизни"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Проклятие, проклятие, проклятие! В следующий раз обязательно брошу их трупы к паукам на съедение!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Эхо."},
  Voice_4912_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Ритм."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Смелая попытка."
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Не нужно так торопиться... Есть что-то, что я могу для вас сделать?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Смелее!"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(с интересом спросить)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "Природа даровала мне высшую честь. Ты считаешь, что это совсем не похоже на меня?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Что делать?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Я неплохо справился, Правда? Так что, вознаграждение. — Что, бесплатного обеда в этом мире не бывает!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "Уходи!"
  },
  Voice_4921_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "Осторожно!"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Какая прекрасная победа...... Я запечатлею этот момент навечно."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Чувствую Генезис нечистот... Ещё один шаг к истинной сущности... Ааа, позвольте мне Разрыв этот мир!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_4924_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Мы...... Готовы. Пожалуйста, дайте команду, Страж."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_4925_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Господин, вы действительно добрый человек. К сожалению, у меня нет ничего, чем я мог бы отплатить вам, я всего лишь бесполезный человек……"
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_4926_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......Еще один шаг, и я смогу полностью разделиться от «них»?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_4927_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Эй, я ещё жив... Вы действительно не собираетесь красть мои органы и использовать меня для экспериментов?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_4928_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Родная раса Венкора обладает способностью проникать в мозг существ, и чужая воля, слившаяся со мной, сильно опасается её. Однако, сейчас она всего лишь несчастная душа, заключённая в своей физической оболочке."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Разговоры · О Венкоре"
  },
  Voice_4929_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Всё это Ай Джис очень любит. Когда все окружают стол и молятся перед едой; когда Страж отправляется в командировку, и все люди ждут вашего триумфального возвращения... В воздухе всегда витает запах счастья... Разве я действительно достойна наслаждаться всем этим прекрасным?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Тони."},
  Voice_4931_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "Расцветай."
  },
  Voice_4932_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "«Доверие», «Подчинение», «Рабы», «Любовь», «Уважение»... Модуль языка перестраивается и обучается, прошу Хранителя тайн дать мне больше наставлений."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_4933_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Эрика в настоящее время находится в состоянии ожидания, организм завершит охлаждение через один час пятнадцать минут, <Del:хочешь запустить — обмен на своё сердце> Запускать срочно?...Проверка прав доступа...Проверка максимальных прав доступа Хранителя тайн завершена. Привет, Страж."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_4934_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "Средний индекс опасности задачи расследования составляет 7, средний расход медицинских средств — 8 флаконов алхимии, среднее время на устранение тел — десять часов.\nВывод: работа Хранителя тайн крайне опасна, соблюдайте осторожность в ходе действий."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_4935_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Запрос архива преподавателя: Эрика Райфель, лектор по профессии «Серебро механики и автоматизации», умершая — Это не то, что вы хотели Требование? Хорошо, выполняю повторный поиск ключевого слова «Эрика»."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_4936_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Если необходимо найти документ, пожалуйста, укажите его полное имя, функция нечеткого поиска временно недоступна."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_4937_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_4939_AwakerVoiceContent = {Text = "А"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_4941_AwakerVoiceContent = {Text = "А"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Заряжено, готовимся к взрыву."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Заряжено, готовимся к взрыву."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "Такие мелочи, впредь, пожалуйста, не беспокойте её высочество во время отдыха."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Я буду защищать тебя, как защищаю Тинкерт."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Я не являюсь важной персоной, всего лишь крошечная капля среди множества последователей... Лишь бы я мог служить тому достойному господину и обратить на себя его внимание, я готов отдать все свои силы и дух.."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Разговор · О прошлом"
  },
  Voice_4946_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "Смотри на меня!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "Смотри на меня!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Ладно, лишь бы эти фанатичные молитвы не беспокоили меня, я могу мириться с их присутствием в одной комнате."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Разговоры · О Плавателе морей"
  },
  Voice_4949_UnlockDesc = {
    Text = "Получите одно из пробуждающих тел «Мириам», «Голиаф», «Кекес», «Шань» или «Фалост» для разблокировки"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Я ненавижу это чёрное чувство, словно внутри всё опустошено, неудовлетворённость вызывает зуд по всему телу.."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Не надо не надо не надо не надо не надо не надо упоминать.."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ха!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_4954_AwakerVoiceContent = {Text = "Ага!"},
  Voice_4954_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "Те историки, которые утверждают, что божественная страна уже пала, высокомерно заявляют, что это раздражает... Но не важно, слова не станут преградой для возрождения славы божественной страны."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "На самом деле... Позволь тебе тихо сказать, я недоволен нынешним мотоциклом — это вовсе не значит, что он мне не нравится! Просто у меня постоянно такое чувство, что чего-то не хватает.."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ха!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_4958_AwakerVoiceContent = {
    Text = "Измельчить!"
  },
  Voice_4958_AwakerVoiceTitle = {
    Text = "Навык · 2 · Безумие"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Извините... Я не хочу этого.."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Навык: II·депрессия"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(с любопытством прошептал)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2 год, господин Уолтер Филлипс, Кералкш и Тави основали Мисаг Академию. После длительного развития, в конце концов, был основан Университет Мисаг, <Del:эта проклятая тюрьма>."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Справедливость, Верность, упорство, самодисциплина. Эти качества давно оставили свой след в моем сердце."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Я хорошо выполню порученное дело."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Какие же безответственные родители могли назвать свою дочь Щитом Суккуба? Ты говоришь, что у ребёнка нет родителей? Хм... наш диалог не стоит ей знать."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Разговоры · Об Ай Джис"
  },
  Voice_4964_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Ай Джис\" будет разблокировано"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Если тебе скучно, то почему бы не зайти в лабиринт и не «Посидеть со мной». В конце концов, твоя безнадежная жизнь и бесконечный лабиринт практически ничем не отличаются!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Разговоры · О лабиринте"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Когда Дора была рядом, эффективность следователей в среднем увеличилась на 78,312%, соответственно, больше людей погружались в эмоциональный спад. Как она сказала: \"Если бы некоторые люди могли держать рот на замке, мир бы функционировал более гладко.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О дора"
  },
  Voice_4966_UnlockDesc = {
    Text = "После получения пробуждающего тела \"дора\" будет разблокировано"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "Спускайтесь!"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_4968_AwakerVoiceContent = {Text = "Как?"},
  Voice_4968_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Как можно не любить приключения? Погружаться в таинственные области, где никто не бывал, исследовать неизвестно, плести свою собственную историю... Какое Тревога!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Пустая болтовня — О приключениях"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Здравствуйте, я Нифия из Февраля. Вы принесли мне это тело, в котором я могу свободно дышать... Чем я могу отблагодарить вас?"
  },
  Voice_4970_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_4971_AwakerVoiceContent = {
    Text = "Только что я снова услышал, как те, кто называют себя моими хозяевами, стонали —— это просто прекрасно."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_4971_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Можно не есть овощи? Хотя Тинкерт говорил, что нельзя быть привередливым, но мне не нравятся их цвета.."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Бог-Творец сказал: страдание не моё создание. Возьми его на себя и нейтрализуй, мой избранник, сотвори царство без страданий на земле. Для этого я готов отдать всё, включая жизнь."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_4973_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Перед проклятием разрушения, которое уничтожает всё, все остальные страдания меркнут. Даже если я не могу принять проклятие вместо других, я должен постараться облегчить их боль."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_4974_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Смогу ли я сейчас облегчить их страдания и утешить их души?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_4975_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Таким образом, я смогу принять на себя страдания всех существ и вещей и проложить путь к земле, где нет страданий."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_4976_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Это тепло в глубине души... Благодарю за твой дар, Бледный Огонь. С этой силой, возможно, я наконец смогу выполнить долг Избранного и спасти больше людей."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_4977_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Могу ли я действительно съесть так много?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_4978_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Хм-хм... Это не смерть, это твоё будущее, моё будущее, будущее этого мира."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Тинкерт... Услышав её печальную песню, невозможно удержаться от танца.."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Тинкерт"
  },
  Voice_4980_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тинкерт\"разблокируется"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Может ли обычная практика пробудить ценность крови? Это действительно выходит за рамки моих ожиданий."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "Оружие стало удобнее в использовании."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Не думай, что я буду тебе благодарен, это запрещено моим народом."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ахэй!"},
  Voice_4984_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "Тот Мужчина... Эй, подожди меня! Наша игра ещё не до конца, верно?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О других людях"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Мне очень нравится записывающее устройство академии, было бы здорово, если бы можно было переделать его в переносной вариант, который бы в реальном времени напоминал мне о том, что я забыл.."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Вездесущие муравьи... нет, даже не муравьи, а лишь крохи, предоставляя поклонение для Его рождения."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Припасы здесь."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Припасы здесь."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Мм...... сильнее, сильнее. да, вот так......"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Ещё не полностью пробудившись, победа далась легко."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Ой, шапка съехала... Хм, так и должно быть? Неплохо!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_4992_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "«Имея такую способность, я действительно ещё человек?» С тех пор как я начал принимать боевую подготовку, я каждый день задаю себе этот вопрос. Я люблю этот мир, даже если он такой мрачный, грязный и скучный, но ваше существование делает его сияющим, как бриллиант в пыли. \n Я долго боялся, что с ростом моей силы моя человеческая позиция изменится... Сейчас я рад, что у меня есть ты рядом, наше взаимопонимание крепко связывает меня с человеческим миром. В будущем тоже прошу тебя заботиться обо мне, Страж."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_4993_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Аа... Конечно, твои опасения естественны, это я не подумал. Как твой напарник, я должен был объяснить всё с самого начала. Как видишь, во мне действительно есть что-то необычное, и это, вероятно, связано с моим происхождением. Сказать, что не любопытно, было бы неправдой. Но иметь убежище вроде этого колледжа — моя удача, поэтому я выбираю не снимать покровы с судьбы."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_4994_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "Ты уже встречался с той женщиной, верно? С тем пробуждающим телом, что носит белую вуаль. Она одна из основателей этого университета...\nНо, честно говоря, она мне не нравится. Это её презирающее всё отношение, будто весь мир ей безразличен, просто бесит... А, ты говоришь, что я похожа на неё? Давай проверим твоё зрение в больнице кампуса?"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_4995_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Ты удивляешься моим отношениям с профессором? Это не секрет, могу сказать тебе. Профессор Декстер — мой приёмный отец, а что касается приёмной матери... Я вырос в школе, где все учителя заботились обо мне. Но я был ближе к дора."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_4996_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Будь то процедуры в Отделе делопроизводства для пробуждающего тела или даты поставок индийской кухни в столовой, я могу ответить на все вопросы, связанные с делами академии. Не переживайте, мне совершенно не трудно помочь. Разве я кажусь таким холодным и неприступным?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_4997_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Зеркало, Зеркало, кто самый лучший маг в мире? Я? Правильно!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_4998_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Неплохо."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Хорошо сделано～"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Успешно...? Я смог вам помочь?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "Бесполезно!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(Выдержка)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Смотри сюда!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Давайте сделаем это место шумным морем для всех!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Нужно ли тебе Охранник? Если твоя цель - правосудие, я помогу тебе."
  },
  Voice_5007_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5008_AwakerVoiceContent = {
    Text = "Не может сгореть."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Не может сгореть."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Хочешь обнять?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Посмотри на эти оковы на мне——они не украшение, а напоминание. Они заставляют меня не забывать вкус предательства и травлю."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Если хочешь узнать о прошлом академии, я рекомендую тебе отправиться в архив и изучить материалы.\nНу пожалуйста, это история длиной в 300 лет, включая предыдущие инкарнации академии! Ты же не ждёшь, что я буду пересказывать её по годам?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Это провокация против меня? Всегда готов!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Глубокое море дарует вам вечный сон."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "Глубокое море дарует вам вечный сон."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Погружайся, гори! Танец смерти!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "Вот вам, Танец смерти зелёного пламени!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "Та девушка, похожая на маяк... Во время плавания через вечную ночь, если бы я мог увидеть её ослепительный Погоня за светом, возможно, я бы не потерялся.."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Разговоры · О Фалосте"
  },
  Voice_5018_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Фалост\" будет разблокировано"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Лучше покажи, что стоишь того, чтобы я покинул лабораторию, новый Страж."
  },
  Voice_5019_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5020_AwakerVoiceContent = {
    Text = "Я Носитель, а ты Сквайр. Что бы я ни захотел, должно быть под рукой. В чем дело, ты, Сквайр, хочешь награду? Ладно, держи!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Позор, используй этот прием, чтобы очиститься!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5023_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Жертва становится даром."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Жертва становится даром."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Будет пострадать!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Не подходи!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Мне нравится золотой лунный Погоня за светом в полнолуние. Таинственно, нежно, при дуновении ветра на морской поверхности вспыхивает золотое сияние, словно волшебный и романтичный сон."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Если бы наша родина не подверглась растворению, я и Тинкерт не разлучились бы... Я ненавижу Раствориться, даже больше, чем овощи."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Впереди сокровище ещё порт, для меня это не имеет значения. Моя миссия - обеспечить ваше безопасное возвращение."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5031_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Следуй за траекторией райской птицы, Конец находится впереди, в лазурной дали."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5032_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Я часто бросаю взгляд вдаль на морской горизонт, представляя себе виды за его пределами — это далёкая земля, к которой я всё ближе и ближе, но которую никогда не смогу достичь. Если когда-нибудь наступит такой день, пожалуйста, пойдёмте со мной посмотреть."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5033_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Благодаря Вашей милости, теперь, даже перед лицом бешенства моря, я с храбростью принесу Вам благословение без сожаления."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5034_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Кажется, слышу песни гребцов, знакомый запах родины."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5035_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Вы пришли, чтобы спасти меня, верно? Из мира гниения, из заражения ненавистью обоих глаз, из вечного зелёного огня.."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Невежа!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Я воспринимаю это как ваш символ верности."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5038_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Воспользуйтесь уроком!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Попробуйте силу мыши!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "Попробуйте силу мыши!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Кубик брошен. Итак, Быстро и решительно!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Я включу ваше имя в благодарственную речь, это вы позволили этим ногам, запятнанным тьмой, снова ступить в прекрасный мир балета. С этого момента, пожалуйста, посмотрите, как я танцую, Страж."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5047_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Как бы ни боролись, всё равно невозможно противиться судьбе. Но тот миг света застынет в вечности."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5048_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Ты говоришь, что делать с этими побеждёнными?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Даже если в моей душе больше нет желаний, я продолжу играть роль лебедя."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5050_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Закройте глаза, скажите мне, что вы можете увидеть? Безупречный лунный Погоня за светом, спокойная поверхность озера.."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5051_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "О бедствие, приносящее Упокоение и несчастье, почему оно именно нас с сестрой закручивание?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Прими мою любовь."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Прими мою любовь."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Почувствовал себя гораздо лучше, благодарю вас."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Если можно, я хотел бы подарить вам светло-фиолетовую кувшинку в качестве ответного подарка."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "А я тоже смогу стать сильнее?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Пора начинать...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Эта раненая нога? Не думал, что ты будешь обращать на это внимание. Это осталось с поля боя ещё при жизни.\nНе стоит беспокоиться. После того как я стал пробуждающим телом, это больше не будет мешать мне в бою.\nБоль? Нет, я не задумывался над этим."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5061_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Сильвия спросила о моем психическом состоянии, это ты позвал её? Я признаю, что фантомные боли иногда возникают. Но не стоит обращать на мои чувства внимания. Я твой нож, я твое лезвие, пока я могу сражаться за справедливость, мелкие боли не окажут никакого влияния."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5062_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Чайная вечеринка, чайная вечеринка, давайте устроим чайную вечеринку! Я взяла много чая и сладостей у Сильвии! Хм, я обменяла их на танец Фортволкен!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Моё имя? Вы так интересуетесь моими личными делами? Просто хотели поболтать... Ладно.\nВ армии мы не делаем различий между товарищами по оружию по признаку пола, включая силу и скорость, а также причёски и обращения. Со временем привыкаешь к этому."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5064_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Интересно... Ты не боишься, что после получения силы я разорву тебя на Фрагмент и скормлю рыбам?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Чтобы стать достойным моим Хранителем тайн, ты тоже очень стараешься!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Пришло время попробовать взять за горло нескольких слабаков."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Танец чист. Слова могут вызвать недопонимание, но движения в танце не вызывают недопонимания."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О танцах"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Я ненавижу море, это естественно. Океан поглотил всё, что я любил.."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Забыть или потерять, на этот раз мы обязательно вернёмся!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Забыть или потерять, на этот раз мы обязательно вернёмся!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "Пожалуйста, не надо больше подходить ко мне, это очень опасно."
  },
  Voice_5072_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5073_AwakerVoiceContent = {
    Text = "Можешь потрогать... эти шрамы остались от боёв на арене, это награды настоящего мужчины!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(стон от боли)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "Ой-ой-ой!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(приглушенный стон боли)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(тоскливый стон)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "В теле что-то кипит... Это и есть ощущение активации духа?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5078_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Это какая-то новая технология? Мои протезы кажутся гораздо легче."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5079_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "Я почувствовал солёный запах морского ветра, до моей страны уже недалеко."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5080_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Смогут ли умершие соотечественники найти путь домой, следуя за этим светом?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5081_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Я уже искал тысячи и десятки тысяч лет, не считая этого мгновения длиной в сто лет. До тех пор, пока я не достигну твоего берега, я продолжу помогать тебе."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5082_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Я буду Мерцание только ради родины, ты.."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5083_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Я почувствовал лёгкий ветерок, который несёт с собой мелкий песок, легко касаясь моих ступней."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5084_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Я могу предложить вам только до этого момента свою силу, не стоит быть слишком безгранично алчным, хорошо?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5085_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Раз уж дело дошло до этого, что вы хотите, чтобы я ответил? Только бой?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5086_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Голова любви, голова ненависти, голова презрения, голова желания... Ой, вы снова здесь?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5087_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Раз это сделка, я не могу просто принять ваш дар. Вам нужно что-то выбрать в этой лавке?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5088_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Я научу вас радости, удовольствию, восторгу при достижении вершины... Взамен вы также честно раскроете своё желание, хорошо?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Хранителе тайн 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Я есть материнское дерево, материнское дерево — это я. Сок дерева бурлит в моей крови, его воля блуждает в моем сознании.."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Пустые разговоры · О Материнское древо урожая"
  },
  Voice_50899_UnlockDesc = {
    Text = "После прохождения «Исследование»главы 7 разблокируется"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Плати за своё предательство!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Когда я только что искал укрытие в Гробнице Ключа, мне показалось, что я увидел вашу могилу... Моя мумия тоже будет погребена здесь? Не будет? Какая жалость."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Болтовня · О кладбище ключей"
  },
  Voice_50900_UnlockDesc = {
    Text = "После прохождения «Исследование»главы 7 разблокируется"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Младший брат волка... между ним и тем N существуют какие-то странные и запутанные отношения.."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Лекк"
  },
  Voice_50901_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лекк\" будет разблокировано"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Подойди ко мне, обними меня, попробуй меня... не забывай меня."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Болтовня · О Хранителе тайн 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "После прохождения «Исследование»главы 7 разблокируется"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Это был чересчур старательный и осторожный ребёнок, я конечно не стану упрекать её~ Без неё, своевольные виды давно бы уничтожились в потоках перемен, верно?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Эльва"
  },
  Voice_50903_UnlockDesc = {
    Text = "Получите пробуждающее тело \"Эльва\", чтобы разблокировать"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Родившись в песках, снова возвращаешься в пески. За это короткое путешествие ты должен что-то оставить, что-то посеять, верно."
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О пустыне"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Желание возникает из любви, любовь — это первое семя, из которого вырастает величественное дерево."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Пустая болтовня О желании"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Ой, милая маленькая мышка промчалась... Я слышала, что мыши — животные, которые любят воровать еду, но жаль, эта ещё слишком мала и находится в колыбели.."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_50906_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Они продолжили мою плоть и кровь, превратившись в бурные реки, орошающие Ремуахе... Теперь только вы можете обеспечить Размножение и сохранение моего наследия.."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Аране"
  },
  Voice_50907_UnlockDesc = {
    Text = "После прохождения «Исследование»главы 7 разблокируется"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Пауки... пауки. Мм~ я люблю пауков. Они начинают двигаться сразу после рождения, их способность к размножению и выживанию действительно впечатляет.."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Агриппа"
  },
  Voice_50908_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Агриппа\" будет разблокировано"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Все существа, в чьих жилах течет кровь дерева, являются моими детьми, и вы, проглотивший семя дерева, тоже, Правда?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Пустые разговоры — О потомстве"
  },
  Voice_50909_UnlockDesc = {
    Text = "После прохождения «Исследование»главы 7 разблокируется"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Мои товары? Можно сказать, что у меня есть всё для удовлетворения всех твоих желаний... просто нужно заплатить соответствующую цену."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5090_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Ой, приходится признать, что я проиграл ей один раз... Хорошо, что вы, выбранный ею, также выпьете сок дерева и перенесёте мою кровь и семена в новый мир, верно?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Разговоры · О Тави"
  },
  Voice_50910_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Рамона\" функция будет разблокирована"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Будучи одной из трех основных сущностей, этот монстр является непредсказуемым созданием. Не верьте легко его сладким речам, иначе я буду очень страдать.."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Сознательное существо имеет желание, даже механические организмы не являются исключением, верно?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Разговоры · Об Эрике"
  },
  Voice_50912_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Эрика\" будет разблокировано"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Плати за своё предательство!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "Добро пожаловать в невероятную страну!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(низкий Уровень)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Я хорошо знаком с болью резьбы и жгучей болью Метаморфоза. Однако всё это перед лицом вечной красоты кажется ничтожным, словно пыль."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5094_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Те слова, которые не решился сказать, я передам тебе через своё творчество."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5096_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Спящий владыка бредит сна у моего уха, руины глубокого моря постоянно перестраиваются перед моими глазами... Бесчисленные сцены из снов, наконец, становятся реальностью?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5098_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Спасибо за подготовленную для меня мастерскую. Здесь всё озарено солнечным светом. Кажется, что каждое произведение, каждый резец, светятся золотистым светом. О, весна золотая."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5099_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Хотя характеры у нас разные, я очень люблю эту девочку. В ней есть смелость, способная преодолеть все трудности и ограничения. Если бы я была такой же храброй и стойкой, возможно, не сделала бы выбора в пользу исчезновения в море.."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_5100_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "Дама в алом не похожа ни на одного из моих прежних господ... Нет, я не ненавижу её, просто немного сложно с ней справляться.."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Пустая болтовня — О Солер"
  },
  Voice_5101_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Солер\" будет разблокировано"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Обними сумасшествие!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Тянуть последние дни"
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "Истребить до последнего!"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "Вы не обязаны так поступать.."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Сердце — это бездонная пропасть, которую никогда нельзя заполнить."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Не больно и не щекотно, но... всё равно очень благодарен."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "А... ты заговариваешь со мной? Извини, я только что вспоминал вид, который видел с верхушки мачты... Можешь повторить свой вопрос?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Разговор · О прошлом"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Это хозяйка, и это Матушка."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Возможность для атаки!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Возможность для атаки!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "Приготовиться ——"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ха!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Ещё одна точка~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Горячая любовь!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "Феномен растворения... Я не могу рассказать тебе слишком много. Но эта вещь появилась намного раньше, чем вы полагаете."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "М-м-м ——"
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5119_AwakerVoiceContent = {Text = "Угу."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "В путь."
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Хе, наша марионеточная принцесса снова плачет. Может, бутылочка не подходит, ещё колыбельная неприятная?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_5121_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Ууу... я не хочу сталкиваться с этими вещами.."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Сейчас моя очередь отплатить вам взаимностью."
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "Чувство усиления силы, как обжигающее пламя."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "А... извините, пожалуйста, не надо двигаться!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "Тепло, которое можно почувствовать.."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Розы в саду расцветают."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Молодец, есть ли ещё силы продолжить путь?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Рыцарь — это нечто нематериальное, Верность, храбрость и добродетель придают ему форму. То же самое и с моим оружием, защита придает ему форму копья и щита."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О рыцаре"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Дженкинс, Диана, Мак, Т'йог, Браун... Вау! Извините, я просто бормочу себе под нос! Вы спрашиваете, почему я называю эти имена? Потому что Ай Джис не хочет забывать всех.."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О друзьях"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Не подходи ко мне!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Ненавижу!"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5133_AwakerVoiceContent = {Text = "А~эй!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5134_AwakerVoiceContent = {Text = "А~эй!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Благодарю за ваш призыв. Если потребуется голос, пожалуйста, заранее сообщите мне об этом."
  },
  Voice_5135_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5137_AwakerVoiceContent = {
    Text = "Это... чёрная слизь, бурлящая в сосудах, Огромная Огромная сила аннигиляции всех стонов! «Я» родился из этого, рождённый для разрушения! Хаха!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Вызвать меня, чтобы сделать ставку?.. Что, расследование? Не надо, слишком расточительно для удачи.."
  },
  Voice_5138_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5139_AwakerVoiceContent = {
    Text = "Теоретические занятия довольно скучные, на уроках я всегда сижу в самом конце класса и тайно читаю записи расследования. Это только между нами, ни в коем случае не рассказывай Доре."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Вкуси горького плода!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Вкуси горького плода!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Я никогда не винил Юлиетт, она всего лишь жертва черного страдания, но... кажется, она не хочет слушать меня. Можешь передать ей это, посланник?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Болтовня · О Юлиетт"
  },
  Voice_5142_UnlockDesc = {
    Text = "Не реализован голос"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Помедленнее."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Угу."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Эй! Перестань трогать, всё стало грязным и беспорядочным!.. Ладно, девушка широких взглядов."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Не нужно!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Чёрт!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "С того дня, как ты пробудил меня из тьмы, я подтвердил, что ты способен спасти всё сущее от отчаяния, именуемого растворением, и направить в безупречную землю. Я с нетерпением жду прихода этого дня."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Хранителе тайн · I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Чую... запах крови."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Где цель? В качестве благодарности за то, что вы меня пробудили, я уничтожу противника."
  },
  Voice_5150_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5151_AwakerVoiceContent = {
    Text = "Моя шляпа уже не может дождаться!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Эта оболочка не должна испытывать трепет ни перед кем, кроме Него... Но твоя температура.."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Как, хочешь сразиться?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Осквернитель.."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Это не может быть прощено."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Эрика в настоящее время функционирует нормально, соединение с электрическими устройствами в университете Мисаг хорошее. Нужно ли мне включить Погоня за светом в общежитии?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Разговоры · Об Эрике"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Следующий, время обеда, хех.."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Не надо позволять женщине в фиолетовой широкополой шляпе приближаться к сцене! Нет причин, просто не подпускай её, если не хочешь, чтобы из цилиндра потекла липкая серая масса!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Разговоры · О Давдейле"
  },
  Voice_5159_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Давдейл\" будет разблокировано"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Ты всегда такой был? Доверяешь всем людям, отдаёшь свою спину? Слишком наивно."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Ненависть может быть смягчена, но её невозможно полностью устранить."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Пробуждающее тело? Хм... Да, верно, Часть 7 часов — самое лучшее время для пробуждения! Завтра в Часть 7 утра пойдём на пляж собирать ракушки!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Беседа · О пробуждающем теле"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Дарую тебе бессмертие!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5164_AwakerVoiceContent = {Text = "Хаа!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Хаа!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Извините, если присутствие Ай Джис здесь вызывает у вас Беспокойство, я немедленно покину это место!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5166_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Вы предоставили мне приют, я очень благодарен. Но простите, я уже недостоин снова стоять на сцене."
  },
  Voice_5167_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5168_AwakerVoiceContent = {
    Text = "Спасибо, что позволили мне остаться здесь. Если я смогу отплатить вам, Ай Джис готова сделать всё, что угодно. Нужно ли налить вам чаю?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5168_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Потому что очень тепло, не хочется покинуть. Когда я один, действительно очень темно, холодно и страшно.."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5169_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Ай Джис... действительно могу вернуться в толпу? Я еще не готов, но вы уже приняли меня... Раз так, то прошу и впредь заботиться обо мне... Страж."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5170_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Вспомнил, вспомнил...! Грязная кровь людей удержала меня... Я, я не смог пройти метаморфозу! Как это возможно, как же я... Где мои жабры? Почему они не двигаются?! Почему!"
  },
  Voice_5171_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5172_AwakerVoiceContent = {
    Text = "Мне нравится есть жареного осьминога, варёного осьминога, жареного осьминога... Некоторые считают, что я намеренно богохульствую. Простите, но осьминог действительно слишком вкусный, хахахаха!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Червь. звезды. я... Юу Хаши! убивать... дай мне убить!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5173_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Темно-красное тело, пульсирующие щупальца, ритмично открывающийся и закрывающийся рот... Отлично, отлично! Я уже не могу дождаться, чтобы Разрыв кому-то глотку!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5174_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Хахахаха, именно такое ощущение! Дай мне ещё... двойной, нет, в десять раз дозу!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5175_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Всегда буду терпеть."
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "Это удивительное чувство...... довольно хорошо. Лучше, чем белладонна левантских волшебников."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5177_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Товарищ? Фу... мне не нужны никакие товарищи, я не позволю такому же балласту обременять себя дважды."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5178_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Буду сотрудничать с тобой, только потому, что ты продемонстрировал силу, достойную меня. Не надо забыл, этот контракт прекратится, когда твоя Огромная Огромная сила ослабнет, и тогда я без колебаний отрублю тебе голову."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5179_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Я вижу в твоих глазах... мерцающий Погоня за светом, это пламя амбиций и желаний. Смертный, познай самого себя! Мы подобны!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5180_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Знаешь об альбатросах? Они никогда не обращают внимания на людей, а неустанно машут крыльями, принимая вызов бури. Но стоит им оказаться на земле, среди насмешек и брани, их огромные свисающие крылья становятся жалкой помехой.\nВ этой истории нет глубокого смысла — просто рядом с тобой я чувствую себя непринуждённо и болтаю о чём попало."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5181_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Возможно, времена действительно изменились. В наши дни даже слабые могут преодолеть рифы, возвыситься над волнами и стать повелителями небес.\nСмертный, я жду дня, когда ты перепишешь историю. И тогда я с гордостью стану твоим могучим клинком!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5182_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Коэффициент конверсии слишком низкий, завтра приходите ко мне в офис, чтобы повторно изучить материал."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Ты уже встречался с другой дора? Так называемая «Правда мира» превратила столь спокойную и рациональную дора в совершенно другого человека... Неужели и мы в конце концов станем такими же?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Лёгкая беседа·О @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела @2"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Носитель... мне нужно команду, пожалуйста, дайте мне команду."
  },
  Voice_5185_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5186_AwakerVoiceContent = {
    Text = "Производительность робота была повышена."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5189_AwakerVoiceContent = {Text = "Хм-хм!"},
  Voice_5189_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Больше друзей!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Больше друзей!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Извините, я не могу покинуть Колыбель...Так я буду мешать обзору других, поэтому я останусь в самом конце класса."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Что?! Ковры из Константинополя, черный чай с острова Цейлон, Чуррос из Андалусии... ничего не купили?! Ууу... Та женщина всегда легко доставала эти вещи, я думал, они очень распространены.."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Далеко ещё до моего первоначального облика."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5194_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Такая спешка для такого талантливого человека, как вы, выглядит несколько грубой."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Независимо от того, насколько его усиливать, внешность этого зверя не изменится. Всё-таки, это лишь материализация моей силы."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5196_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Чувствуется, как будто вернулся в море хаоса, и это неплохо."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5197_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Учитывая твои старания, я с удовольствием приму тебя как своего спутника."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5198_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Разрушь стены лабиринта и сломай барьеры силы."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5199_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Нельзя рвать еду на части и ломать стулья в столовой... Хорошо, Лили обещает больше так не делать."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5200_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Могу ли я называть вас матерью?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5201_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Есть ли какие-нибудь приказы, Носитель?\n«Не надо гулять с ними на улице, все будут пугаться»?\nЛили поняла, Лили сейчас их спрячет."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5202_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Стать пробуждающим телом, оказывается, всё дело в этом."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5203_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Матушка, могу ли я спать рядом с тобой? Когда я один, мне снятся страшные сны. У Лили отпали руки и ноги, это действительно так больно.."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5204_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "О! Благодарю за внимание хозяина, но Гарен всего лишь смиренная Служанка..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5205_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Хм-хм~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Мне нужно собрать некоторые материалы для резьбы, желательно достаточно свежие."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Будьте тихи."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Несокрушимый Глупцы совершает тщетные дела."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5209_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Дело дошло до этого, я более или менее понимаю твои намерения. Ничего, продолжить."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5210_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Я вижу твою Решимость. Прежде чем снова погрузиться в сон, я стану твоим свидетелем, свидетельствуя о твоём восстании против судьбы. Но сейчас мне нужно одна точка времени для отдыха."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5211_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Следовать судьбе, разве это плохо? Почему сопротивляться воле судьбы."
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5212_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Чтобы осуществить желание, ты действительно готов пожертвовать так много.."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5213_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Хаа? Не надоело еще? Перестаньте меня беспокоить из-за этого парня!.. Ладно, делайте как хотите, пусть это будет способом убить время."
  },
  Voice_5214_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5215_AwakerVoiceContent = {
    Text = "Растворение... Эти грязные черные жидкости часто вторгаются в сновидения Юй, вызывая сильное раздражение."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Власть - это обоюдоострый меч, как я могу не понимать этого... Просто осознал слишком поздно, слишком поздно. Как только я ослаблю контроль, они набросятся на меня и разорвут на фрагменты... Если бы с самого начала я был так же здравомыслящим, как вы, мой Конец не был бы таким трагическим. Эй? Вы говорите, что в будущем я смогу проводить салоны в комнате отдыха?! Это действительно... Кроме личного служения вам, как еще я могу отблагодарить вас.."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5216_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Вы действительно упрямый и неподатливый Гость. Что мне нужно сделать, чтобы вы согласились уступить свои привилегии? Власть только влечет за собой проблемы, и такая простая истина вам наверняка понятна, не так ли?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5217_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Хотите послушать историю перед началом салона? Историю о том, как деревенская девочка сняла корону власти... С чего начать? С того, как её родители выдали замуж за очень старого человека, или ещё вы бы предпочли услышать о её расцвете в саду аристократов?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5218_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "В прошлом Гость обращались ко мне под именем «Дама в алом». Конечно, вы можете звать меня «Солер», ведь вы мой самый особенный Гость.."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5219_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Как хозяйка салона, моя обязанность – сделать так, чтобы каждый Гость был доволен."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5220_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5221_AwakerVoiceContent = {Text = "А"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Господин? Может быть, моя стойка неправильная?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "Плохая удача!"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5225_AwakerVoiceContent = {Text = "А"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Я помню это ощущение, тот славный момент скоро Пришёл.."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5226_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Хотя жаберные следы так и не появились, я больше не тревожусь из-за этого. Эти мембранные крылья превратятся в щит защиты тебя, Страж."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5227_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Ты... действительно более терпелив, чем другие люди... Ты потратил столько ресурсов на меня, ты действительно... не ненавидишь меня?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5228_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "А? Ритуал закончился, почему у меня ещё не выросли жабры? Метаморфоза снова неудача?! Чёрт! Чёрт! Чёрт!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5229_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Тот звук снова призывает меня... Этот божественный голос из глубокого моря!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5230_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Угадай——ошибся——"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Скульптор Шань с Западного острова преподносит вам резец. У вас могут быть недостатки, но всё равно вы достойны быть высеченными."
  },
  Voice_5232_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5238_AwakerVoiceContent = {
    Text = "Непослушные дети, собирайтесь!~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Истинное искусство не требует объяснений."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "Истинное искусство не требует объяснений."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "Орета, можешь помочь?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "Звучи, рог!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "Не щадя сил!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "Ощущение солнечных лучей... Оказывается, оно настолько мягкое, что хочется заплакать."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5244_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "В знак благодарности... я воздвигну для вас тайный алтарь в глубине моей боли."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5245_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Мясо и кровь брата слились с моим телом, став ещё более гармоничными и прочными..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5246_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Я более стойкий, чем вы можете себе представить. Так что, когда используете меня, можете приложить немного больше силы, одну точку, не стоит церемониться."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5247_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Мне кажется, или жажда крови немного уменьшилась?"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5248_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Еще до официального поступления я с нетерпением ждал твоего появления. Сейчас, как мне кажется, мы неплохо сработались, Правда? Партнер."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Совсем не впечатляет."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Ааа!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5252_AwakerVoiceContent = {
    Text = "Ха-ха-ха-ха!"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "Ударить·мания"
  },
  Voice_5253_AwakerVoiceContent = {Text = "М-м.."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Ударить·депрессия"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Наноси мне Урон, сколько хочешь!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Ай Джис очень боится. Нет, она боится снова принести вам Страх и грусть."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Книги сказок этого времени гораздо интереснее тех, что я читал в свое время! Ах, ах! Мой господин, не поймите неправильно! Я уже перерос возраст для историй перед сном!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Наноси мне Урон, сколько хочешь!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Фух... Ай Джис никому не доставила хлопот, надеюсь?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Ты всегда питал эту наивную доверчивость, оставаясь рядом со мной... Хорошо, возможно, тебя можно использовать с пользой. Но запомни: я не могу терпеть никакого предательства, особенно от тебя."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5259_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Я только жалею, что тогда не пригвоздил их кости к столбам и не повесил на стены города! Все, кто совершил предательство де, таптанье де, оскорбил меня, я никого не оставлю в живых!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5260_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Да, я тоже когда-то лебезил перед ними, это неоспоримо. Они воспользовались моей наивностью, но и я заставил их заплатить за это."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5261_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Ты думаешь, что несколько цветистых фраз и несколько дней ложного благоприятствования смогут заставить меня добровольно снова надеть оковы и стать твоей игрушкой?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5262_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Все, кто пытался контролировать меня, использовать меня, в конце концов были отправлены мной в мир мертвых——я не против отправить и тебя."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5263_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "А... извините, пожалуйста, не надо двигаться!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Не трогай меня!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Неуважительно!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Покорись... Добро пожаловать в страну наслаждений и грёз."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "Это столица, где бесчисленные мертвецы бродят, потеряв свою родину."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Ай Джис будет Давай!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Ну... Я не могу контролировать поглощение жизненной энергии, поэтому, пожалуйста, будьте осторожны и не кладите руку в Колыбель. В противном случае это может привести к болезни."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Надеюсь, во время нашего диалога её работа не должна давать сбоев. Моя милая и раздражающая помощница, уже не осталось лишних лабораторий для её взрывов."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Разговоры · Об Эрике"
  },
  Voice_5271_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Эрика\" будет разблокировано"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Руки, надоедливые руки! Они постоянно цепляются за мои волосы. Не могу контролировать даже свои собственные руки, я совершенно никчемный человек... может быть..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О себе"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Спасибо за ваше руководство, я наконец понял выбор Фейнта. Я принимал всё как должное и не догадывался, что это причиняет ей такое большое психологическое бремя. С этого дня я буду стараться жить для себя.."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5274_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "В долгие времена, у меня и Фейнта были только мы Близкий Близкий друг у друга... Однако сейчас у меня появились новые важные люди... Страж, позвольте мне взять свои прежние слова назад. Вы не такие, как они. Вам важен не только мой голос и наряд, вы смотрите на меня. Поэтому я тоже буду смотреть на вас."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5275_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Звёзды в сновидении спячки, идите куда следует, указывая путь к божественной стране!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Почему я везде и всегда ношу этот костюм? Чтобы в любое время исполнить для вас песню."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5277_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "То, что я сам хочу сделать?.. Извините, мне непонятно, о чём вы говорите... На самом деле, Фейнт тоже много раз спрашивала меня об этом, но я просто хочу, чтобы она скорее выздоровела.."
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5278_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Во время пребывания на Пустынной звезде, те великие люди дали нам с сестрой ресурсы для выживания. В конце концов, это они дали мне возможность убежать с Пустынной звезды, хотя смогла улететь только я одна. Они все мои благодетели, как и Вы, Страж, который дал мне убежище."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5279_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Вы добрые люди, предоставившие мне жилье, Ай Джис будет слушаться вас. Если бы Ай Джис могла быть немного более полезной.."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Не забудь подготовить место. Ты же не заказал что-то меньше, чем у Элвортса, Правда?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5281_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Отлично, Гарен сейчас полон энтузиазма и может убирать двадцать комнат в день."
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5282_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Это музыка, столь же древняя, как озеро, принадлежащая «Нам». Носитель, давайте танцевать вместе! Пока голос Гарена еще не был украден «Им»..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5283_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Носитель! Звук Гарен... исчезает... спаси..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5284_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "Глаза Гарен улучшились... Носитель, ты опять забыл причесаться!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5285_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Даже если станет сильнее, Гарен одна точка не хочет мстить. Гарен хочет только петь! Танцевать! Устраивать вечеринки!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5286_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Чтобы продолжать существовать после полного уничтожения, я разделил свою силу духа и кровь между множеством людей. Моя текущая Огромная Огромная сила намного слабее, чем тогда, когда я впервые Принял эту волю.."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Разговор · О прошлом"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Не рассчитывай найти меня в здании обучения. Здесь полно запаха затхлости и старых учёных, я не могу здесь оставаться."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Не надо убегай."
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "Моя родная страна верит в «богов», и соответственно, король, которому я служу, является «человеком, связанным с богами»."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Беседы · О вечной стране"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "У вас здесь столько талантов, что заслуживает великолепного салона... Не беспокойтесь, в указанное время Приглашение наверняка будет доставлено вам моим слугой."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5292_AwakerVoiceContent = {
    Text = "Приходи!"
  },
  Voice_5292_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Если бы у нас было больше союзников.."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Я не такая, как она. Она приносит только враждебную дрожь и Страх, а я дарю нежность, сладкую и горячую боль, и любовь, понимаешь?"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Ванда"
  },
  Voice_5294_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Ванда\" будет разблокировано"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Не думай, что всё так просто пройдёт! Я верну себе каждую обиду, которую получил на этот раз!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Твои руки так же тёплые, как и твоя душа, бледное пламя, я... благодарю тебя за твоё прикосновение."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Что плохого в том, чтобы играть в бридж в классе? Есть стол, есть люди, я принёс карты, это значит, что «Начало»!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "Не надо.."
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Взор в абисс!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "Взор в абисс!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5302_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Божественное сияние!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5307_AwakerVoiceContent = {
    Text = "Привет!"
  },
  Voice_5307_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Слабые души, собравшись вместе, кроме шума, что ещё могут сделать, вздыхают.."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "Война всегда приносит страдания, и переносить муки — это долг воина. Даже лишившись рук, ног, всего, я продолжу сражаться за тебя и за правду мира."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Вот это твоё подношение Ему?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Ты думаешь, что так можно изменить будущее?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Его зачатие... в моём чреве.."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Хех, считай, что ты вовремя сообразил."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Вносить дань господину — это естественно."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Ты стараешься мне угодить, и это так мило."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Коричневый торт, карамельный пудинг, торт \"Саха\", шоколадный мусс, печенье... должно быть на каждом столе!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5318_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Посмотри, пожалуйста, всё ли в порядке с моим платьем? Не должно быть складок, не должно быть ослаблений... Что случилось? Тебе что-то не нравится?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5319_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Добро пожаловать на финальный ритуал активации духа! Всё это было тщательно спланировано мной, мое дорогое \"я\". Конечно, Страж также внёс свой вклад.."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5320_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Стол и стулья должны быть украшены кружевами, которые соответствуют моему стилю, а горшки для растений обязательно с красными эпипремнумами... Быстро подготовьтесь!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5321_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Иди пригласи гостей! Как можно не справиться с таким простым делом?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5322_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Нет пути к отступлению!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Нет пути к отступлению!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Я постараюсь изо всех сил! Чтобы не подвести своего господина."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5325_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Мне нравится эта женщина, у нас есть то, то самое... да, общий язык!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Ванда"
  },
  Voice_5326_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Ванда\" будет разблокировано"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Невоспитанный человек!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Невоспитанный человек!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Превратиться в обломки."
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5330_AwakerVoiceContent = {
    Text = "Разрушись."
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Пробейте Барьер реальности!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "У тебя есть планы переправиться через море в ближайшее время? Можешь ли ты согласиться на мою неподходящую просьбу и взять меня с собой? Мне только бы оказаться в открытом море.."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5332_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Если вы всё ещё доверяете мне, позвольте мне стать указателем на вашем пути. Однако даже такая простая работа иногда была мне не по силам.."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5333_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Не хочешь отправиться в открытое море? Дай мне посмотреть на современную карту... 47 градусов 9 минут южной широты, 126 градусов 43 минуты западной долготы, вот здесь."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5334_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Прошлые мои действия вызвали множество катастроф, даже чуть не уничтожили некоторые цивилизации... Я... Если это было не намеренно, неужели уже слишком поздно?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5335_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Я тот, кто охраняет Вход в Вечное Царство, указывая путь тем, кто возвращается домой. Как же это забавно, что тот, кто несет такую обязанность, мог забыть, где находится его родина...\nТы... станешь моим маяком?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5336_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Звёздное скопление!"
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "А"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Густой туман, ах!"
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Хм."},
  Voice_5340_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "Большинство сопровождающих не отличаются Близкий Близкий друг от друга, но эта женщина — исключение. Если возможно, пожалуйста, назначьте мне другой маршрут."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Болтовня · О Мириам"
  },
  Voice_5341_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Мириам\" будет разблокировано"
  },
  Voice_5342_AwakerVoiceContent = {Text = "А"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Безразлично."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Отпусти руку."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Прежде чем я вернусь во дворец под морем, с трудом могу предоставить тебе, хрупкому человеку, немного силы глубокого моря, и только."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5346_AwakerVoiceContent = {
    Text = "Давай!"
  },
  Voice_5346_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "Нравится? Мне нравится боль, нравится покрасневшая и горячая кожа, нравятся стоны, смешанные с удовольствием и страданием. Боль — самое первобытное и настоящее желание, не Правда ли?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Присоединяйся к Орета!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Присоединяйся к Орета!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Та большая сестра всегда злобно на меня смотрит. Но я не знаю почему, чувствую какое-то родство. Может быть, потому что она похожа на Матушка."
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Разговор · О Шило"
  },
  Voice_5350_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Шило\" разблокируется"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Мозги стали более гибкими, чувствую себя неплохо."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5351_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Вместо посещения занятий я предпочитаю работу в лаборатории — разве ты думаешь, что эти инструменты помощи просто достают Из моря?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5352_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Конечно, чем больше винтов ещё гвоздей, тем лучше."
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Тело уже с трудом выдерживает эту силу, но сейчас не время менять куклу. Чего ждёшь? Помоги мне подержать эту ногу, мне нужно проверить."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5354_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Бремя, ведущее к свету, может сломить даже самых чистых святых. Если ты устал, мое Белое пламя, обязательно расскажи мне. Я непременно сделаю все возможное, чтобы облегчить твою боль и разделить бремя бесчисленных благ."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О усталости"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Ваше признание — это причина моего существования как рыцаря."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5356_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Окутанный светящимся сиянием божества, это и есть Власть бога-короля моего господина? Настолько мощная, настолько священная."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5357_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Дверь божества уже совсем рядом."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5358_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Всё ярче, всё яснее.."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5359_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Могу ли я, будучи в пробуждающем теле, снова стать целым... Я уже слышу, как божественная страна играет для меня святую музыку.."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5360_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Он примет меня в святилище, даст мне покой на ложе.."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5361_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Пожалуйста, не волнуйтесь, все мы очень полезны. Я могу шить и убираться, другой из нас специализируется на бое, а остальные тоже найдут применение..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Я ненавижу яркие, мягкие вещи. Нежность как отражение в зеркале, перед которым не могут скрыться все уродство, Алчность и хрупкость."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Хочешь потрогать Браун? Я не могу решить за тебя, тебе нужно лично спросить её."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Хочешь завоевать мою благосклонность? Тогда встань на колени, подставь свою шею и молчи, пока я не выпью тебя досуха."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Пей!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "Вчера ночью я видел сон, с чего началось моё путешествие среди звёзд."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5367_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Может ли Ай Джис помочь?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5368_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Почувствовала, да~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Тих!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Навык: третий"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "Осторожно!"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "Отступи."
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Никто не пострадает... в... мире.."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5374_AwakerVoiceContent = {
    Text = "(кокетство)"
  },
  Voice_5374_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "Позвольте мне установить алтарь бога. Это изваяние, созданное силой благочестивых последователей, не принесет вам никакого проклятия."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Всего немного.."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Мой гаечный ключ ещё не на месте!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Химия, физика, прикладная наука о сердечнике из серебра... В это время уже не нужно изучать Часть 7 рыцарских искусств? Понятно. Тогда, прошу, мой господин, назначьте для меня соответствующие занятия!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Орета путешествовала! Не плыла по волнам моря, а путешествовала в повозке!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5379_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Лампурмана, коронная медуза, цветочная медуза, все они живут стаями. Конечно, Орета тоже! Орета тоже хочет быть с остальными!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5380_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Ранее произошедшее? Не слишком хорошо помню... Но Орета помнит, что работала в океанариуме! Заработок за день составлял 2 чепушек!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5381_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Шшш, скажу тебе на ухо, Орета на самом деле Алан, Транс... э-э, в общем, Орета - морской человек! Если Орета будет послушной, больше есть овощей и заводить друзей, Артес и компания обязательно примут её!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5382_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "Дом Ореты, её друзья из аквариума, любимые медузы Ореты, все пропали…… Ты тоже исчезнешь? Разве нельзя всегда играть с Оретой?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5383_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Выиграл? Отлично.."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Чтобы мир."
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Чтобы справедливость."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Я знаю, что ты внутри меня!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "Человечество, ложные боги, пробуждающие тела и даже Раствориться... Все в этом мире станет основой для моего перелить вечной родины."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Проснись, проснись, я знаю, что ты во мне!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Юу Хаши... Он немного похож на моего брата, всегда заставляет меня вспоминать те мрачные, безразличные и бессонные дни."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Юу Хаши"
  },
  Voice_5392_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Юу Хаши\"будет разблокировано"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Наши отношения, как у Холмса и Ватсона, не Правда ли? Вы обращаете внимание на популярные журналы последнего времени?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Ползти перед красотой."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Ползти перед красотой."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Отвращение, прилагательное, означает чувство неприязни к чему-либо. ненавидеть, глагол, означает чувство неприязни и избегания чего-либо. неприязнь, существительное, чувство неприязни, <Del:Досаждение к подавлению заставляет меня разрушать, заставляет меня разрушать, заставляет меня> — Простите, я не понимаю, что такое «Досаждение»."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "В конечном итоге всё-таки.."
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Стало ещё более иным."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Запомни моё имя, Голиаф. Это имя обречено стереть ничтожную историю человечества."
  },
  Voice_5399_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5400_AwakerVoiceContent = {
    Text = "Пожалуйста, не надо беспокоиться."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Надеюсь, ты оправдаешь свой потенциал и ожидания людей, новый Страж."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Перегрузка."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "Гиперскоростная работа."
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "А, фотография, которую ты нашёл в кошельке? Ах, это я раньше. Сейчас мой облик был создан моим партнёром по азартным играм и моим противником."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5404_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Хорошо — хочешь сыграть на ставку? Если выиграешь, я расскажу тебе секрет? \nНо будь осторожен, не попадись Эльва~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5405_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Ты так заботишься о своей шкуре? Не надо ли потрогать? Не беспокойся, я очень щедрая!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5406_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Конечно, есть и плюсы, я ведь встретил своего Ватсона, Правда? По сравнению с этим, жизнь, смерть и внешность ничего не значат, не так ли?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5407_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Ты спрашиваешь, пожалею ли я? Совсем нет. Если бы жизнь всегда была гладкой, разве это не было бы слишком скучно?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5408_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "В моё время школа была местом для подготовки воинов, похоже, что и сейчас так же."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Мейсон... нет, так даже лучше, по крайней мере, мы снова вместе, «24»."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Поболтать · О «24»"
  },
  Voice_5410_UnlockDesc = {
    Text = "После получения пробуждающего тела «24» будет разблокировано"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Я неплохо справился, Правда? Так что, вознаграждение. — Что, бесплатного обеда в этом мире не бывает!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Я из Западного острова. Там все хотят стать актёрами, никто не хочет быть только зрителем. На самом деле, мы все лишь жалкие сноски этого города."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Разговор · О прошлом"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Вы когда-нибудь видели древние каменные надписи? Они сливаются с горой, опираясь на природу, избегая разрушительного воздействия времени, какое прекрасное создание... К сожалению, этого ещё недостаточно.."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Голубь так и не вернулся.."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "Отступить!"
  },
  Voice_5415_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5416_AwakerVoiceContent = {Text = "Хм!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Выполнить команду!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Идиот"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "...ах? Ты зовёшь меня? Я ремонтировал мотоцикл и не слышал... Кстати, добрый человек, ты не видел мой гаечный ключ?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5419_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Моя память всегда довольно туманна, могу сосредоточиться только на текущих делах. Но я постараюсь запечатлеть твоё имя в моей памяти... Как тебя зовут?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5420_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Ты кажешься мне знакомым, но я не могу вспомнить твоё имя... Ты мой помощник? Не мог бы ты принести мне Часть 7 гаек?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5421_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Я вырезал твоё имя на «фантоме». Когда-нибудь, когда мы отправимся в приключение вместе, я не забуду, как тебя звать."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5422_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Очень знакомо, очень знакомо, между нами точно что-то произошло, Правда? Дай мне немного времени на воспоминание... Ах, это ты, Страж!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5423_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Вы совсем не искренний ребёнок. К счастью, у меня достаточно времени и терпения, чтобы ждать вас.."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "«Всё хорошо, что хорошо кончается», не так ли?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Получил неплохую голову... Хотя она и не может сравниться с моим избранным, но путешествие в поисках новых экспонатов всегда вызывает Тревога. Пригласите меня в следующий раз тоже."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Мм.."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Профессия горничной поможет хозяину избавиться от всего, включая злодеев, и даже с легкой улыбкой~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Теперь мы, наверное, считаемся сообщниками. Если однажды ты окажешься на улице, я не позволю тебе жить впроголодь."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Размножение, рост, мой маленький саженец."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Размножение, рост, мой маленький саженец."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "Чувствую, что удача в бросках костей поднялась на одну точку!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Ух ты! Удача на моей стороне!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "Удачливый~"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Не приближайтесь ко мне."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Не приближайтесь ко мне."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Я должен обвинить вас, Страж. Вы слишком добры ко мне, это вызывает у меня Беспокойство — с моей точки зрения, лишь Физическая боль является настоящей и вечной."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Хорошо, ухаживаешь неплохо."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Этого явно недостаточно."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Говори, какую награду ты хочешь?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Эй! Эти грязные и неопрятные пятна... Моим ногам некуда деться. Так что, стань моей мягкой опорой, смертный!"
  },
  Voice_5441_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5442_AwakerVoiceContent = {
    Text = "Наконец... нашёл!"
  },
