  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Исключительная Огромная Огромная сила подвластна лишь тем, кто обладает телом глубокого моря. Ты ведь мне завидуешь, не так ли? Хаха, Ювенильный слабым человеком — это не твоя вина. Что поделать, такова Колесо Судьбы."
