  Voice_5463_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Хм."},
  Voice_5464_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "Всё не так уж плохо."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5466_AwakerVoiceContent = {Text = "А"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5467_AwakerVoiceContent = {Text = "А"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Если бы я мог узнать раньше, что те люди в то время из-за этого проклятия, которое тает всё, мучительно страдали, я... нет, знать сейчас тоже не поздно. Я обязательно устраню это проклятие и покончу со всеми страданиями, даже если для этого мне придётся снова отдать жизнь."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Не унывай. Море примет все люди."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "С таким слабым телосложением стать моим спутником ещё слишком трудно. Пойдём, отведу тебя в спортивный клуб академии, чтобы увидеть что-то новое и усилить тренировки!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Тот жалкий человек, который дал мне силу, сильно страдает от растворения... Что это за взгляд? Перестань! Я не скажу тебе, где она!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Если тебе достаточно повезёт, ты тоже можешь быть непобедимым."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Не слишком ли это грубовато?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Ой, большинство людей здесь ещё дети. Тот джентльмен уже седой и белобородый, у того неприветливого парня нет руки, они не годятся... Действительно, сложно."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Не слишком ли это грубовато?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Тщательно прорисованные руны, статуи богов, созданные с благочестием, многократно очищенные запретные зелья... ни один из них не может отсутствовать."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5476_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Трон должен быть сложен из древнего зелёного камня, добытого в глубоком море, на алтаре следует покрыть кровью жертвенных животных... Почему ты еще не начал готовиться?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5477_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Приходи всё, они должны трепетать и падать на колени, чтобы встретить Его пришествие."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5478_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Я перейду в руины глубокого моря, чтобы омыться морской водой, в которой Он появился.."
  },
  Voice_5479_AwakerVoiceTitle = {
