  Voice_5479_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Добро пожаловать на церемонию Его рождения, вместе будем свидетелями Его дня рождения... Что? Ты говоришь, что Его гибель также предопределена судьбой?.. Нет, это совершенно невозможно... Я уже заплатил такую высокую цену.."
