  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Добрый день, господин. Если вы собираетесь на расследование, пожалуйста, позвольте мне быть вашим охранником."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5493_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Что делать? Если скучно, напиши отчёт о действиях."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Наконец-то Начало? Мои маленькие питомцы очень долго голодали.."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Огромная Огромная сила крови хлынула."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...подождите, я видел такое раньше. В воде, которую мне давали, была эта черная слизь. Возможно, это как-то связано с тем, что я получил силу зелёного пламени? Что ж, можно считать это благом из беды."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Рамона Декстер, зови меня просто Рамона. С нетерпением жду нашего сотрудничества, Страж."
  },
  Voice_5498_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5499_AwakerVoiceContent = {Text = "Да."},
  Voice_5499_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "Команда Получено."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Хм, невежливые люди, я с удовольствием поиграю с вами."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Ненавистные вещи? Только что выкуренная трубка, упущенный экипаж, дождь, который начинается, когда надеваешь новые кожаные туфли. В общем, вся плохая удача очень неприятна."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Гаечный ключ, регулируемый гаечный ключ, торцевой ключ, плоская отвёртка, крестовая отвёртка, винт с потайной головкой, винт с цилиндрической головкой... Все, что может починить сломанное, мне нравится."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Эй~ ты обнаружил меня~ \n Ничего страшного, ментальная энергия пробуждающего тела настолько обильна, что нужно Кража ещё как минимум 365 раз, прежде чем они превратятся в марионеток без сознания~ Не могу сделать? Ну ладно, в следующий раз я буду осторожнее! Ммм, только украду одну точку «страха», когда тело распиливают, это ведь не страшно, Правда?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5504_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Эй, ты уже знаешь секрет магии Касии, да? Хм, чтобы предотвратить утечку секрета, независимо от того, куда мы отправимся на гастроли, тебе придётся следовать за мной~ хаха, так ты заметил, что я собираю твои эмоции? Видимо, от тебя не может скрыться ни один секрет!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5505_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Ты, стань ассистентом Касии в магии! Не бойся~ просто залезь в мой магический ящик на минутку.\n\n Ты уже спрятался? Я хочу вставить меч! Кстати, там нет никаких механизмов~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5506_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Давай, надень эту шляпу! Затем, скажи, какой Подарок ты больше всего хочешь. Хорошо, ясно! Сейчас, потрогай внутри шляпы —"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5507_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Немного беспокоюсь. Эти дети каждый раз приходят смотреть представление, мой запас скоро иссякнет... Хм, фокусник не может показывать один и тот же фокус перед одной и той же аудиторией. Создавать новые фокусы? Извините, у меня нет такого таланта, я могу только имитировать."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5508_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Эта академия в ужасном состоянии, только Комната отдыха господина директора выглядит более или менее презентабельно. Как вы считаете?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5509_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Те высокомерные и подлые типы все до одного станут душами, павшими от моей руки."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "Мстительный клинок становится всё острее, словно Кровожадный пациент."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Мой салон не так невинен, как бал. Готово?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5512_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Мой салон — это почва, это сад, пьянящая красота и Независимый будут здесь цвести.."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5513_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Шелковая мягкая кушетка, черный чай, макарон... еще нужно свежие розы, украшенные утренней росой, для моего гостиного зала."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5514_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Нельзя ли как-то договориться, чтобы и внешние Гость могли войти в академию?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5515_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Ошибка выполнения, ошибка, ошибка, ошибка.."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ой! Сколько сейчас времени! Прости, Носитель... Гарен не должна отвлекаться на работе! Но я так устала..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Могу ли я только ждать смерти? Кто-то может мне помочь? Могу ли я противостоять их контролю? Я задавал себе эти вопросы каждый день, но Лечение всегда был в моей голове, просто я не решался его принять... Если бы ты не появился, я не уверен, хватило ли бы у меня смелости продолжать сопротивляться.\nБлагодарю вас — не подумай, это совсем не признание!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5518_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Я живу в их ложных сновидениях, лишённый возможности быть обычным человеком из-за абсурдного пророчества, даже выбора у меня не было... Чтобы сбежать от такой жизни, я готов на всё."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5519_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "«Низко наклонившиеся спящие лилии вздыхают вокруг,\nв дремлющих ольхах она изредка просыпается;\nптица в гнезде шуршит и дрожь,\nтаинственная песнь снижается с золотых звёзд.»\nАх, вы это слышали? Извините, это одна из моих любимых строк... Хотите прочитать вместе со мной?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О чтении"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Не входи в комнату дамы без разрешения и не критикуй её манеры. Уходи немедленно, я хочу отдохнуть."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5521_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Не надо строить из себя кого-то важного, осознай своё место и внимательно посмотри, кто здесь Реальность Носитель."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5522_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Эй, нужно показать товар?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Хорошая работа. Пришло время выпить бочку рома, чтобы отпраздновать победу!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Исчезни."
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "Доверьте это мне!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "Ощущение, когда ты под моей ногой, должно быть просто великолепным, Правда?~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Терпи!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Так сильно переживаешь о том, как выглядишь под повязкой? В более подходящий момент я позволю тебе увидеть, не будь слишком нетерпеливым."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Так быстро Конец?... Мой интерес только что начал просыпаться."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Эй, не лапай меня, Реальность боец никогда не зависит от внешних вещей."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5531_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Ай Джис стала сильнее... Я использую эти глаза, чтобы враги не могли пошевелиться!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Университет Мисаг и армия ничем не отличаются. Каждый из нас стоит на передовой, чистит оружие до блеска и готовится к бою."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "Совершенно!"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "Совершенно!"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Я могу быть закован в кандалы, могу быть на коленях перед тобой, держа за волосы, быть твоим рабом. Это не проблема — только дай мне убивать, скульпторов, фонарщиков, проходящих астматиков... кого угодно, я обещаю помочь тебе Разрыв им глотки и выпить их кровь."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5536_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Из раны, поражённой растворением, течёт не только чёрная слизь, но и непрерывный поток вдохновения. Честно говоря, я не против получить ещё одну точку."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Страх? Хаха, это правильно! Пусть всё идёт к чёрту, я просто хочу почувствовать ваш Страх."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5538_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Интересно, вкус твоей крови... очень сладкий, как мёд."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5539_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Тогда десятки тысяч человек одновременно радостно выкрикивали моё имя, Океан с названием «Юу Хаши» затопил всё вокруг, празднуя то, что я только что свернул шею лысому трусу. Это было восхитительно, и как мой спутник, ты наверняка сможешь понять это чувство."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5540_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Подожди, подожди!"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5542_AwakerVoiceContent = {
    Text = "Не надо!"
  },
  Voice_5542_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Поиск в широком архиве «Раствориться»... Не нужно? Ты хочешь знать мое отношение к растворению? Я понял, пробуждение системы для поиска «оружие против растворения»... Результат: «0»."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Поддельная вещь, хрупкая как пыль, легкий ветерок может развеять ее.."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_5546_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Слегка шумно, это студент?\nОни похожи на альбатросов, ты знаешь этих птиц? Безграничная энергия, путь кажется бесконечным.."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ха"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Фырк"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "В академии только Рамона интересная, у неё есть талант к фехтованию, остальные же — просто люди, придерживающиеся правил... Ты ведь не такой? Тебе действительно нравится писать отчёты о действиях?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Не стоит упоминания."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "Матери бывают разные. Есть как хорошие матери, так и плохие.\nГоспожа — хорошая Матушка."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5552_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Это я не смог вас защитить.."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Забронирована ли площадка? Нам нужен сад больше 150 квадратных метров!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5554_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Кровь умирающего человека — это скользкая жидкость. Достаточно легкого надреза на шее, и кровь начинает стекать между зубами, превращаясь в теплые тонкие струйки, медленно заполняя мой желудок... Хе-хе, какое удовольствие."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Пустые разговоры — О крови"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Я"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5557_AwakerVoiceContent = {
    Text = "Привет!"
  },
  Voice_5557_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Ой"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Спасибо за ваше милосердие, предоставив мне приют. Надеюсь, я не привлеку к вам трагическую судьбу.."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Я прибыл с далёкой планеты. Там бушуют ветры и метели, царит леденящий холод. Но это не важно, ведь в моём поместье более тысячи слуг, их присутствие согревает меня."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Разговор · О прошлом"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "До вашего возвращения я не могу упасть здесь."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "До вашего возвращения я не могу упасть здесь."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "Ой, как же может быть такой высокомерный Гость, который хочет «Самое лучшее оружие в мире»? Я сказал ему, что нужно обменять на голову, пропитанную ненавистью, и он ушёл с досадой.."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Голиаф"
  },
  Voice_5563_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Голиаф\" разблокируется"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Твоё самоуверенное выражение лица, как будто ты готов в любой момент пожертвовать собой ради «спасения мира», заставляет людей чувствовать зуд в суставах."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5564_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Прежде чем вы наложили запрет на исследования, мне не хватило всего одну точку, чтобы аннигиляция покрыла это так называемое убежище растворения... Очень жаль."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5565_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Да, у меня было бесчисленное множество запасных тел и бесчисленное множество возможностей сбежать от растворения. Но когда передо мной открылся путь к истине, ни один истинный учёный не смог бы отказаться. Я последовал внутреннему стремлению, и за это я не жалею."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5566_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "Настоящее мира, Начало мира, Конец мира — всё это лишено смысла. Если ты тоже хочешь пойти по пути к истине, я не против быть твоим Путеводителем... как мы делали это раньше."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5567_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Возможно, вы сможете остановить меня, но Конец неизбежен... Я оставлю эту школу и тебя до самого конца. Мы будем стоять на вершине башни, купаясь в сумерках времени, наблюдая за падением цивилизации... Как вам такое? Разве это не достойная дань нашим отношениям?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5568_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "Ладно."
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "Исчезни."
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "Пусть мои молитвы станут утренним колоколом, пробуждающим родину.."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Я и не думала, что кто-то кроме Тинкерта захочет принять меня. Я очень рада, что встретила тебя, Страж. Я буду изо всех сил учиться контролировать свою силу, чтобы, обнимая тебя, не высасывать твою жизнь... Это ведь объятие, да? Так люди выражают благодарность?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5572_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Я останусь здесь, не нужно платить за это? Я могу помочь тебе повысить твоё положение здесь. Просто угроза высосать их жизнь, очень просто, как когда-то я помогал Тинкерту... Ах! Это, это дело ты никому не рассказывай!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5573_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Извините, я отличаюсь от других подобных мне, я - брак.."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5574_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Хорошая Служанка может придать салону особый шарм, но сине-зелёная Служанка... надо ещё подумать.."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Гарене"
  },
  Voice_5575_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Гарен\" будет разблокировано"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Тинкерт – это моя сестра-близнец, в отличие от меня, она всегда сияет...\nЕсли бы не я, у неё было бы более светлое будущее, её голос разносился бы по всей галактике.."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5576_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "В колыбели тесно, нет возможности расслабиться... Но Тинкерт сказала, что ради безопасности всех людей мне нельзя покидать Колыбель... Раз она так желает, я обязательно послушаюсь."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5577_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Я часто чувствую себя между жизнью и смертью. Везде, где я существую, печаль распространяется как волна, а трагедии идут одна за другой. И всё же, ты готов позволить мне писать для тебя стихи? М-м... может быть, ты достоин самого сладкого.."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5578_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "«Роза еще не расцвела, а рассвет уже близок.»"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5579_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Чего вы желаете? Красоты витиеватых слов, славы, известной повсюду, или искренности, скрывающейся за строками и обагренной кровью?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5580_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Невидимыми чернилами, изображая деформированные бутоны... эти призрачные розовые ветви способны пробудить поэтическое вдохновение.."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5581_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Внемли, о Господин мой."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Гнозис: пробуждение·Второе"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Пожертвование жизни! Воссоздание божественной страны ——"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Просветление духа·три"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Если вы настаиваете, я снова выйду на солнце... Солнце, такое же, как в тот день, когда я покинула Западный Остров одиночества.."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5582_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Хе-хе, ты хочешь увидеть Вселенную в состоянии уничтожения? Эй, сейчас уже поздно жалеть!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5583_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Пей, благоуханная смерть."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "Пей, благоуханная смерть."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "Вот и всё!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Не.."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Вот величие Юй."
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "Воздух в университете в 4 часа утра очень приятный, я рад, что вы согласились позаниматься со мной. Не могу не сказать, что скульптура — это тяжелая физическая работа."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О утреннем времени"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Эта Огромная Огромная сила используется довольно неплохо."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5590_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Я ненавижу людей, которые не платят за покупки. Если магазин работает достаточно долго, такие проблемы неизбежны, да? Ничего не поделаешь, придется мне лично взяться за возврат долгов~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Медленно мучить."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Медленно мучить."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5594_AwakerVoiceContent = {
    Text = "Загрузить!"
  },
  Voice_5594_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5595_AwakerVoiceContent = {
    Text = "Запуск."
  },
  Voice_5595_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Давайте сделаем это место шумным морем для всех!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "Как, ты думаешь, я тебе должен сказать спасибо?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Как дань это совершенно непригодно... Но, учитывая вашу искренность, я с неохотой принимаю это."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Ты думаешь, что я буду слушаться тебя после этого?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Хаа!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5601_AwakerVoiceContent = {
    Text = "Вверх!"
  },
  Voice_5601_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Неблагодарный монстр, Ассасин, наемник — есть ли в тебе ценность, которую ты ценишь? Странный."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5602_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Независимо от того, сколько мягких подушек ни скопилось, лазуритовый трон не сравнится с пуховой кроватью. В этом отношении у вас здесь есть некоторые достоинства."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Маленькое наказание."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Я ненавижу одиночество, ненавижу беспокоиться о чувствах кого-то в бесконечной тёмной тьме... Поэтому, пожалуйста, не надо бросать меня, хорошо?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Если бы я был на твоём месте, я бы запер все пробуждающие тела в клетках! Безумные псы, вырвавшись на свободу, первым делом кусают своих хозяев."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5606_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Я опоздал на эту встречу на один час—— всё из-за тех добродетелей, кто сверг рабство, сейчас никто не причёсывает мне волосы!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5607_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Трудно представить, что моя родина вот так аннигиляция... Это же великий Рим! Ты не мог не слышать о нём!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5608_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Приходи, начни с победы!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Это — благословение моего владыки."
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "Спрячь своё жалостливое выражение, мне это не нравится, и я не нуждаюсь в чьей-то жалости. Если ты будешь продолжать смотреть на меня так, я не смогу удержаться от того, чтобы сильно измучить тебя... Тебе же не хочется, чтобы ситуация вышла из-под контроля, так что будь послушным, веди себя хорошо и стань моим гладиатором.."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5611_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Не *глуши* больше. Я прокололся, расслабился, и Гладиатор сбежал, из-за чего вся семья погибла! Как нынешняя Римская империя, сожжена дотла, не осталось даже пепла!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5612_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Сравниваясь с талантливыми людьми, Нифия всего лишь самый обыкновенный человек, который не совершил никаких подвигов и не создал никакой ценности.\nТо, что вызвало мое пробуждение... возможно, это были какие-то маленькие, скромные желания.."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Сегодня я снова нарушил Школьные правила, опоздал на урок на Часть 5 минут... Поэтому, я умоляю принять самое строгое наказание, а если его будет выполнять Страж, это было бы идеально."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Инструменты тоже нужно обслуживать, подходящий набор инструментов — это сердце механика."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5615_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(презрение и Выдержка)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Если это повторится в следующий раз, я подам заявление о твоем условном пребывании в университете."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Кроме боя, у меня, конечно, есть и другая работа. Даже в Архее я не был бездельником... Эй, ты ведь не считаешь меня человеком, который только и умеет, что драться, Правда!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О работе"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Когда люди приближаются ко мне, они всегда вспоминают самые грустные моменты своей жизни и не могут сдержать слез. Могу ли я, такой, как я, расти?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5619_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5621_AwakerVoiceContent = {Text = "Так?"},
  Voice_5621_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Здесь гораздо лучше, чем в грязной и вонючей новой тюрьме Ньюгейт! Лежать на диване приятно, отдыхать в углу тоже комфортно, не так ли?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "Браун...!"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "Улиточная ракушка, куда она пропала.."
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "Хитрый!"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Куда делась ракушка!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "Течущая Галактика.."
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "Орета не любит, когда её партнёры уходят внезапно... но, но если они вернутся, Орета простит их!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Женщина, которая способна путешествовать по морям в одиночку, может быть либо богиней, либо безумной. Когда-то я считал Мириам богиней, это была просто огромная ошибка."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Болтовня · О Мириам"
  },
  Voice_5629_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Мириам\" будет разблокировано"
  },
  Voice_5630_AwakerVoiceContent = {Text = "Ага!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Я тайком посмотрел магию девушки Касии. Её выступление принесло зрителям много радости, но я всегда приношу только грусть... Скажите, слёзы и улыбки — это одинаково ценные вещи? Может быть.."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Болтовня · О Касии"
  },
  Voice_56313_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Касия\" будет разблокировано"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Поэзия, пламя и печаль — это похожие вещи, они незаметно поглощают тебя... Когда очнёшься, уже оказываешься погружённым в Мир поэзий.."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Пусть Псалтирь из прошлого пробуждение сад, скрытый в глубине сердца."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Поэзия и цветы, вероятно, являются одним и тем же? Одинаково краткие, вневременные, в этом бескрайнем мире они занимают лишь малую часть пространства, но вместят в себя самые глубокие и незабываемые моменты... Я думаю, все люди когда-то замолкали перед стихотворением, так же как останавливались, любуясь расцветающим цветком."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Пустые разговоры — О стихах"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Я уже почти забыл... Какие цветы расцветают в этом сезоне на Западном острове?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Разговоры · О Западном острове"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Вы заставили чернила моего пера вновь собраться в спокойный Ручей, и я продолжу писать стихи для Вашей истории."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Хранителе тайн 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "Цветение цветов настолько прекрасно, насколько грустно их Увядание. Но, независимо от того, сколько раз я испытывал грусть, я всегда не могу удержаться, чтобы не задержаться у этих цветов и не оплакать их. Если из-за страха перед болью я стану игнорировать их, разве эти цветы не будут опечалены.."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Пустая болтовня — О страданиях"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Чтобы изучить внутреннее Построение этого тела, пока Эрика «спит», Венкор просит меня ночью отправиться в её кабинет для сна.\nНужно ли сообщить, что во время сна Эрика сохраняет часть своего сознания?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Разговоры · О Венкоре"
  },
  Voice_5631_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Та Дама в алом действительно прекрасна. Её Огромная Огромная сила и уверенность, её элегантная улыбка перед судьбой, её жизнь, столь же яркая и решительная, как красная роза, вызывают во мне невероятное восхищение.."
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Пустая болтовня — О Солер"
  },
  Voice_56320_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Солер\" будет разблокировано"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Я вчера написал новое стихотворение, еще никому не показывал. Написано плохо, но ... Страж, не могли бы вы взглянуть на него?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Хранителе тайн 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Студенческое поэтическое общество хочет, чтобы я стал их наставником... Я не могу согласиться с ними. Я не хочу огорчать студентов, но смогу лишь принести им разочарование и уныние."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "В этом мире нет ненавистных вещей, золото годы достойны воспевания, а старость и Увядание заслуживают сочувствия; молодость в прекрасных одеждах вызывает зависть, а изношенные лохмотья старости пробуждают воспоминания."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Каждый раз, когда я вижу девушку Нифию, я вспоминаю картину с изображением спящей лилии. В её облике ощущается Тишь, горечь и аромат, как у спящей лилии... Не знаю, каким она видит мир."
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Нифия"
  },
  Voice_56324_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Нифия\" разблокировать"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "С самого начала я чувствовал, что рядом со мной присутствуют «призраки», словно какое-то необъяснимое наваждение или одержимость, которая постепенно лишает меня интереса к миру. Но если это призраки, то как объяснить исчезновение молока и чистой воды в никуда.."
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О призраках"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Моё тело не подверглось заражению растворением, те чёрные жидкости были всего лишь густой тушью. Но если подумать, даже без растворения существование вещей может превратиться в ничто, не так ли?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "В надгробии Ключевого Хранилища я увидел имя Хранителя тайн… Воспоминания о прошлой жизни были мучительными, но я никогда не думал забывать их. Для Хранителя тайн эти утраченные воспоминания, наверное, тоже были бесценны?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Болтовня · О памяти"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Если поэзия существует для восхваления красоты, то её существование похоже на саму поэзию. Когда она начала петь, я внезапно понял, о чём говорили предшественники, описывая её голос как голос соловья.."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Тинкерт"
  },
  Voice_56328_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тинкерт\"разблокируется"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "Та прекрасная танцовщица... изумрудно-зелёное пламя на её теле вызывает невозможно устоять от желания прикоснуться, даже если это приведёт к полному сожжению.."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Лиз"
  },
  Voice_56329_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лиз\" будет разблокировано"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Использовать этот метод вместо вдыхания первоматерии?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Вкусно, очень вкусно."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Гость, какое вознаграждение вы хотите?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Давай закончим, не надо задерживаться на улице."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Неизбежное Жертвенный ритуал."
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(стон терпения)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Ток введен. Ток выпущен."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Не недооценивай первого божественного вора на улицах!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Предлагаю воспеть открытие!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Здесь возникает тысячеликий фантом!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Ещё ближе.."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5638_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Погружайся, гори! Танец смерти!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Это столица, где бесчисленные мертвецы бродят, потеряв свою родину."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Позволь мне дать тебе... мою последнюю энергию для перемещения!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Не недооценивай первого божественного вора на улицах!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "Враг ли это? Дайте мне команду атаковать.\nЧёрная слизь — враг... Лили тоже враг?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Автоматическая кукла Эрика, номер корпуса EA307881, номер двигателя MF311028. Всегда рада помочь!"
  },
  Voice_5640_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5641_AwakerVoiceContent = {
    Text = "Бейся изо всех сил до полного разгрома врагов!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Привет, я... ты можешь сказать мне, как меня зовут?"
  },
  Voice_5642_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5643_AwakerVoiceContent = {
    Text = "После того как я поступил в школу, я наконец понял природу болезни, поразившей меня, - Раствориться. В детстве родители всегда предостерегали меня от контакта с океаном. Теперь я осознаю, что эта инфекция, вероятно, действительно связана с моими частыми посещениями моря.."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Хорошо, я не заставлю тебя «разочароваться»."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Это горячее дыхание ——"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Иди."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "Повернись."
  },
  Voice_5647_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5648_AwakerVoiceContent = {Text = "Эй!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "Этот день наконец настал.."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ха!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Я ещё не насладился... Как насчёт того, чтобы ты поднялся, и я убил тебя ещё раз?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Страж, мне нужно поговорить с вами. До нашей окончательной победы некоторые люди не должны так расточительно жить. Имейте в виду, я не сражаюсь за аристократическую жизнь таких людей."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Пустая болтовня — О Солер"
  },
  Voice_5654_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Солер\" будет разблокировано"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Если меня заберут в плен, какая жестокая Колесо Судьбы ожидает меня?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Прими это!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Хм!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Фу—— Какая Сонливость. Перед тем как отдохнуть, у вас есть что-нибудь для расслабления, например, чай или закуски?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Матушка, ты хочешь потрогать их? Они очень мягкие, говорят."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5659_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Хм... хм..., ля-ля-ля~ убирать убирать, я люблю убирать, настроение отличное~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О работе"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(нестерпимый стон от боли)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Хм...неплохо."
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(нестерпимый стон от боли)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(нестерпимый стон от боли)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Гнев горит!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Я вижу, что многие сошли с ума из-за растворения. Честно говоря, я уже достаточно сумасшедший, так что Раствориться вряд ли сможет на меня повлиять."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Хе~хахаха!"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "Хороший инструмент — половина успеха!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Чувствую себя, как будто снова ожил."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Неплохо"
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Можете нанести более сильный Удар мечом."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Нужно поддерживать посещаемость, поддерживать прогресс исследований и выполнять задачи по обучению. Похоже, что эксперимент по обратному сжатию времени нужно внести в расписание."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5672_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Ещё на один шаг ближе к официальному приключению."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Не надо подпускать к воде, иначе пламя твоей любви может погаснуть,о?"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Бой до конца!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "Ты действительно очень храбрый. Посмотри на эти щупальца, ты не боишься быть поглощённым сумасшествием?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5676_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5677_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5678_AwakerVoiceContent = {
    Text = "Больно.."
  },
  Voice_5678_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Пожалуйста, остановитесь!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Хотите потрогать? Мое сердце бьётся благодаря вашему присутствию."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5680_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Они чирикают и очень счастливы. Спасибо, Носитель."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5681_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Что-то просыпается в груди... тепло, Лили, слёзы Лили вот-вот...\nМать, давай праздновать вместе."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5682_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Когда я с матерью, я чувствую счастье."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5683_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Уже не могу больше есть... я сыт/сыта.\nПосле церемонии Лили станет сильнее?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5684_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Мне нравится море, не будет ли это иронией? Ведь всё, что у меня было, уже погрузилось в глубокое море.."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Будь осторожен!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Неприятные вещи...? Нет. Можно ли ненавидеть пылинку или листок дерева?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Я несколько раз отказывался от приглашения девушки-горничной на банкет, она казалась немного подавленной... но по сравнению с развлечениями, безопасность хозяина важнее!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Гарене"
  },
  Voice_5688_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Гарен\" будет разблокировано"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Господин — это причина существования рыцаря, поэтому пожалуйста, используйте меня по своему усмотрению!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...этот случай, возможно, нужно использовать динамометрический ключ... Извините, Вы меня только что звали?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "Смелее!"
  },
  Voice_5692_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(элегантное легкое хмыканье)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(стон терпения)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Давай уже остановимся."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Помягче."
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Всё же сложно сосредоточить разум.."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "По ночам она часто находится рядом со мной — неужели мой череп слишком бросается в глаза?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Разговоры · О Венкоре"
  },
  Voice_5698_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Я всегда ждал Нисхождение уничтожения, но никогда не думал, что существует выбор «сопротивление»... Вы готовы взять меня, чья душа так мелка, и перенести через аннигиляцию? В мире, где выживание на грани смерти, всё равно даровать мне искупление.."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5699_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Раз уж я пробуждена как Ваш Апостол, то кроме Вашего мира и радости мне ничего не нужно, это моя воля... ох... ах... действительно, существовать, существовать, существовать, существовать... жить.."
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5700_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Не хотите ли вы погрузиться в моё Вдаль от берегов? Вы же меня пробудили, не для того ли, чтобы насладиться теплом моих объятий?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5701_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Не хотите запутываться с женщиной непонятного происхождения? Хорошо, хорошо. Последний правитель Ниневии, человек из Шнай с намерением достичь небес, девушка, лишённая воли под священным деревом Евфрат... С чего вы хотите начать?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5702_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Почему вы всегда прячетесь от меня? Это потому что вы стеснительны? Как мило, ваше нежелание прямо смотреть на желание.."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5703_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Ужасно, это место ужасно! Как можно заставить благородную девушку, такую как я, пить послеобеденный чай за одним столом с другими людьми!... Вкус домашних печений вполне неплохой. После ужина принеси одну точку в мою спальню."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5705_AwakerVoiceContent = {
    Text = "Хей-сю!"
  },
  Voice_5705_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "Прими это!"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "Растворение… В академии родины есть соответствующие записи, однако Гарен ненавидит читать и всё забыл!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Хотите, чтобы я снова отправился в путь? Если вам не будет неприятно из-за моей прежней оплошности, я попробую это сделать."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5708_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Ненавистные вещи? Их слишком много — начальники, заставляющие рабочих трудиться до поздней ночи, высокомерные монахини, урчащий от голода живот, черный хлеб с осколками стекла.."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Это всё из-за Ай Джис, всё, это вся моя вина.."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Конец!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Благодаря заботе девушки Ханны, я смог присутствовать на репетиции хора. Пение в хоре и Песня лодочника очень отличаются. За время благословения корабля я никогда не слышал такой уникальной мелодии.."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Этот ход как?!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Этот ход как?!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Как страшно~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ууу..."},
  Voice_5716_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Привет, мой новый Носитель! Сегодня в меню есть улиточная запеканка, жабий рагу и зелёное пламенное Прекрасное Прекрасное вино, Носитель может выбрать что угодно~"
  },
  Voice_5717_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5718_AwakerVoiceContent = {
    Text = "Так это и есть форма источника... Не совсем, немного не так, как я себе представлял. Но было бы здорово, если бы я тоже мог принять такой облик."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Разговор · О кровной связи с глубоким морем"
  },
  Voice_5718_UnlockDesc = {
    Text = "Получите пробуждающее тело одного из следующих: «Тулу», «Морфи», «Мириам», «Голиаф» — после этого разблокируется доступ"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Жди момента."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "Прими это!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Агнцы, милосердие Бога спасёт вас."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Агнцы, милосердие Бога спасёт вас."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5723_AwakerVoiceContent = {Text = "Умри!"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ха!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Хм!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ха!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "Она тоже жалкий человек, её Колесо Судьбы будет растоптана. Потому что, когда Он действительно придёт в мир, это будет момент, когда я дарую ей смерть."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Болтовня · О Мириам"
  },
  Voice_5727_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Мириам\" будет разблокировано"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Окунись в кровь!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "Мщение... !"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "Больно.."
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(сдерживаемый вопль боли)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(сдерживаемый вопль боли)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5733_AwakerVoiceContent = {
    Text = "Больно.."
  },
  Voice_5733_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Вы хотите утонуть вместе со мной?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5735_AwakerVoiceContent = {
    Text = "Уходи!"
  },
  Voice_5735_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "Ненавистные вещи... беспорядочно разложенные книги на столе, шкаф в беспорядке, покрытый пылью подоконник —— да, я делаю описание твоей комнаты. Я хочу видеть её к семи часам утра завтра такой, какой она была до твоего заселения."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(заинтересованно хмыкнув)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Интересно!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(смех с презрением)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Если нужно, я могу покинуть Колыбель.."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Хочешь?"
  },
  Voice_5741_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5742_AwakerVoiceContent = {
    Text = "Смотри~ Получай!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "Двойной, двойной, двойной!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Это напомнило мне о первых красных танцевальных туфлях, которые я получила в восемь лет. Мне они очень нравились, благодарю вас, Страж."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5744_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Друг... это Носитель? или Матушка?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Моё покровительство тоже иногда даёт осечку.."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(стон)"},
  Voice_5747_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5749_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Любимые вещи? На полях сражений Пелопоннеса мне тоже задавали этот вопрос... Слишком поздно, я давно отказался от подобных личных пристрастий."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Шшш... о том, что я стал сильнее, пожалуйста, не позволяйте «ним» Обнаружение."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "«Они» сказали... Огромное спасибо."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Э-э... это что?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Это только приблизит меня к абиссу."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5754_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Ты мой верный Сквайр. Я знаю, вы называете это другом, товарищем, соратником... Как хочешь, называй это так, как тебе удобно."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Я получил Лечение... даже если это Не тот Лечение, которого я ожидал, но я получил Лечение."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5756_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Это «Страх»? Или ещё «Грусть»? Твое уныние просто завораживает."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5757_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Запах смерти и аннигиляции ощущается так ясно."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5758_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Жизнь здесь? Очень хорошая. Если я дам девушке Дора немного знаний о механической науке и духовных исследованиях, она позволяет мне держать Погоня за светом включенным всё время."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Надеюсь, что Дженкинс и Браун счастливы в академии. Отецские манжетные кнопки по сравнению с её свободой не стоят и ломаного гроша. Я верю, у него есть целая коробка запасных."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_5760_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Не могу покинуть.."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Освободившись от низшей расы, я совершенно не боюсь этого влияния. Даже если тело, в котором я пребываю, будет разрушено, благородная кровь не исчезнет."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Ненавижу людей с фальшивыми улыбками! С них невозможно Кража никаких эмоций!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Хм? Почему все молчат? Гарен не любит тишину. Давайте я расскажу вам историю. Давным-давно была гора..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Лили схватит будущее... Токули—Ли!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "Лили схватит будущее... Токули—Ли!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "Если ты здесь, чтобы почувствовать Его присутствие, я временно прощаю твою дерзость."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Не хочу так делать.."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "Не надо подходить ближе!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Постепенно, постепенно удается следовать вашим указаниям!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Расстояние до того, чтобы стать полноценным рыцарем, стало немного ближе!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Благодарю за ваше доверие, очень благодарен."
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Бани — отличное место для проведения времени. Там не только вкусно, но и предоставляют услуги для расслабления мышц. Захотелось? Тогда давайте построим такую же в школе, сразу же!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "Нет, не уходи!"
  },
  Voice_5774_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5775_AwakerVoiceContent = {
    Text = "Готово."
  },
  Voice_5775_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5776_AwakerVoiceContent = {
