  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "Ложная миссия, определённое будущее... Я буду сопротивляться до конца!"
  },
  Voice_57824_AwakerVoiceTitle = {
