  },
  Voice_57828_AwakerVoiceContent = {
    Text = "Предательство, попробуй мою отчаянность и Негодование!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "Присоединяйся к моему ритуалу, стань моим семя!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "Я всегда стеснялся сказать Орете, что я не так молод, как она думает... Можете уговорить её больше не называть меня «сестра»?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Об Орета"
  },
  Voice_5782_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Орета\""
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "Давно утраченный город Луоинь, наконец, открылся во всей своей красе."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "Давно утраченный город Луоинь, наконец, открылся во всей своей красе."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "Настало время сдержать своё обещание."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "Настало время сдержать своё обещание."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "Всё происходит по Его воле."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Всё происходит по Его воле."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "То, что прибыло со звёзд, преподносит вам Приглашение."
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "Я всё ещё... цвет из звёзд!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "Я всё ещё... цвет из звёзд!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "То, что прибыло со звёзд, преподносит вам Приглашение."
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_5783_AwakerVoiceContent = {
    Text = "Отступить!"
  },
  Voice_5783_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_57840_AwakerVoiceContent = {
    Text = "Вперёд, все вместе!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "Бог лабиринта, затаившийся под землёй, объявляет вам!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "Бог лабиринта, затаившийся под землёй, объявляет вам!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "Птица, парящая в синем небе, услышь мою просьбу."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "Птица, парящая в синем небе, услышь мою просьбу."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "Не двигайся, не двигайся, не двигайся!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Дрожать под кровавой цепью... Упокоение под кровавой цепью!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "Дрожать под кровавой цепью... Упокоение под кровавой цепью!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "Вперёд, все вместе!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "Не двигайся, не двигайся, не двигайся!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Хе-хе."},
  Voice_5784_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_57850_AwakerVoiceContent = {
    Text = "Посмотрите, вот Огромная Огромная сила, на которую полагаются филистимляне!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Посмотрите, вот Огромная Огромная сила, на которую полагаются филистимляне!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Слишком слабый."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ха!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Ух... Похоже, у хозяина плохое настроение? Гарен придет и сделает рожицы, хи——ха! \n Как думаешь, сейчас стало немного лучше?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Через разум человека... раскрой суть мира!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Я встретил в коридоре некоторых людей, которые вызвали у меня плохие предчувствия. Возможно, из-за обстоятельств тебе придётся работать совместно с ними, но всегда оставайся бдительным. Жестокее войны может быть только человеческое сердце, и самое страшное предательство часто исходит изнутри."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Лёгкая беседа·О @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Разблокируется после получения тела пробуждения «Шило» или «Лили»"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Твоё домашнее задание уже готово, можешь сопроводить меня в город Лондиниум?.. Эй? Математическое задание ещё не сделано?! \n А, а... Прости, я и не думал, что кому-то может быть сложно с дифференциальным исчислением... Дай мне помочь тебе?"
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О обучении"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Я вам клянусь, тот продавец точно появлялся в салоне Фонтенбло... Понятно, значит, с того времени она выглядела именно так. Не знаю, сколько тайн она может раскрыть."
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Разговоры · О Давдейле"
  },
  Voice_5791_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Давдейл\" будет разблокировано"
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "Не разбей."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Орета любит играть со всеми! Хочешь присоединиться? Этого ребёнка зовут Желе, а ту — Хела, а тот, вон там, тоже Желе... Эй?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Позор, используй этот прием, чтобы очиститься!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "Магазинчик Давдейл открылся, дети, которые не подготовились, лучше не заходить сюда просто так, ладно?"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5796_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Пожалуйста, не надо трогать мою шею... Невидимость не значит, что этого нет."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Мне нравятся ребята с убеждениями, будь то животные, пробуждающее тело или люди. Если эти ребята обладают выдающимися боевыми навыками, это ещё лучше."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Иди."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "Не беспокойтесь!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Рамона ненавидит потерять... Прости, я имела в виду, мне не нравятся расставания, это так грустно."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Я не умею ладить с духовенством. Они скучно и старомодно, и отдали свои пояса своим почитаемым «Богам», что жаль, ведь господин Сальвадор пах так сладко.."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Болтовня · О Сальвадоре"
  },
  Voice_5802_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Сальвадор\" разблокируется"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "Бой до последнего дыхания ценнее всего, даже победы и поражения."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Кто не любит мягкую постель и исправную сантехнику... в комнате."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...не надо заставлять меня вспоминать...дни, проведенные в плену в Элвортсе.."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Сожги всё!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Сожги всё!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Я следуя запаху крови, нашёл это место. Скажите... здесь предоставляют свежие пакеты с кровью?"
  },
  Voice_5808_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5809_AwakerVoiceContent = {
    Text = "Мм... У Агриппы тоже много друзей, но все выглядят так, как будто боятся её. Неужели она отбирает у своих друзей еду?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Агриппа"
  },
  Voice_5809_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Агриппа\" будет разблокировано"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "В моей жизни есть только танцы, даже если меня заставят учить другие знания, мне будет очень трудно расти. Но все являются добрыми людьми, они не станут продавать меня чтобы тщеславия или денег, я могу это чувствовать."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Трусливый человек, обладая силой, похожей на мою, он так подавляет себя. В чём разница между этим и добровольным ношением ошейника!"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Разговоры · О Лили"
  },
  Voice_5811_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лили\"разблокируется"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Недостаточно... силы всё ещё не хватает.."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "Возвращайся..."
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Котелок, Цилиндр, шляпа-шотландка, берет... Не могу не сказать, что ваши усилия, джентльмены, чтобы скрыть лысину, выглядят довольно комично."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Пустые разговоры — О этикете"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Я очень восхищаюсь этим человеком, белоснежным и элегантным, словно лилия, богами мореплавания... Вы говорите, что даже она не смогла овладеть своей судьбой и в конце концов погрузилась на дно моря? Это действительно трудно вообразить.."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Разговоры · О Хилестере"
  },
  Voice_5816_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Хилестер\" будет разблокировано"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "В мире нет ничего, чего гигант не смог бы превзойти!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "В мире нет ничего, чего гигант не смог бы превзойти!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Черт, черт...! Огромная Огромная сила удерживает меня в плену тела.."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5819_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Как же хочется остаться там, где всегда светло... Да, полюс — единственное место на этой планете, где это возможно."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5820_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Я, я не могу взять на себя никакую важную задачу, могу только гнаться за светом. Поэтому, пожалуйста, не надо прекращать Мерцание.."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5821_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Если бы ещё можно было переместиться, я бы хотел стать звездой.."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5822_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Несмотря на все вычисления, формула для переноса сознания не имеет решения..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5823_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Добро пожаловать, давайте вместе повеселимся!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "Кушать подано!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Хуху — это Орета! Один, два, три... Вау! Добро пожаловать, добро пожаловать! Новый товарищ присоединился! Хм? Я стала новым товарищем для всех? Можно и так сказать!"
  },
  Voice_5826_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5827_AwakerVoiceContent = {
    Text = "Вы называете эту маленькую игрушку пистолетом? Скрываться в тени и нападать врасплох на противника — это действительно оружие трусов."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Бессмысленно, так делать вообще нет смысла."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Вы вообще ничего не понимаете."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Ты все еще рассчитываешь, что я стану твоей поддержкой как «Спаситель»?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Извини, ты не видел мой винт? Как странно... Когда этот ребенок с кошачьей хваткой рядом, я легче теряю вещи.."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_5831_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Я не забуду всё, что ты сделал для нашей встречи снова с моим господином.."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Песня высекания!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "Вы уже одобрили моё желание?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Надеюсь, твоё командование никого не разочарует."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Получившее Улучшение — это тело или ещё мой разум? Интересная тема."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5836_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "Отступи."
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "С дороги."
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "В моих венах бурлит воля к жизни, она кричит, подгоняя меня оставить след крови на всей планете… Ах, надеюсь, вы не сочли это слишком утомительным. Я — Тайис, вы призвали меня, значит, уже готовы слиться со мной?"
  },
  Voice_5839_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5840_AwakerVoiceContent = {
    Text = "Если бы Ай Джис могла взять на себя эту черную жидкость… В конце концов, Ай Джис никогда не существовала, так что для этого мира это должно быть к лучшему, Правда?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Хобби — гипотеза Римана — это девиз того павлина, а не мой. В сравнении с этим, я больше интересуюсь исследованием атомных эталонов."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Быть выставленным за Ворота, вкус изгнания в море... достаточно один раз испытать."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Смотри внимательно!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Смотри внимательно!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Пока ты сможешь оставаться верным этой справедливости, я продолжу исполнять долг клинка."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Знаете ли вы, что здесь ходят легенды о «Художнике»? В этих экспрессионистских граффити я почувствовал знакомый запах.."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Больно, но Тревога——"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "Видишь мой Негодование!"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "Запиши эту победу в стихах."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Растите ——"
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5852_AwakerVoiceContent = {
    Text = "Прими это!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Эй!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Может быть, когда я вырасту, я смогу контролировать себя и не высасывать жизнь у других... Мне хватит совсем чуть-чуть, чтобы выжить."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5854_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Кажется, я стал тяжелее, сможет ли Колыбель выдержать мой вес?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5855_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Огромная Огромная сила вот-вот переполнится, за спиной чешется, может быть, скоро вырасту?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_5856_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Хотя я всё ещё выгляжу как ребёнок, но сейчас у меня... уже есть Огромная Огромная сила, чтобы защитить тебя."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5857_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Я постараюсь вырасти."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_5858_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Неблагодарное существо, зачем ты так одержим пробуждением меня?"
  },
  Voice_5859_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5860_AwakerVoiceContent = {
    Text = "Я стану матерью бога!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "Это уже который раз меня призывают... Человек, ты лучше подготовил достаточно «еды», иначе я ничего не могу гарантировать."
  },
  Voice_5861_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5862_AwakerVoiceContent = {
    Text = "За дверью!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5863_AwakerVoiceContent = {
    Text = "Глупость."
  },
  Voice_5863_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Хаха"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Хм, неплохо. В следующей схватке я буду биться изо всех сил."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Невоспитанный человек!"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "Иногда, красота искусства — это красота аннигиляции. А ваша неудача... явно не входит в эту категорию"
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Вы мой самый важный слушатель, вне зависимости от времени, я всегда готова петь для вас и отдавать всё."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Любимые вещи? Водоросли, стаи рыб, колонны, лабиринты... Конечно, я видел! Все это есть в книге дяди Орна!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Это подготовка для расследования задачи? Я понял."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5870_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Моё имя — Хилестер. Пока тебе ещё нужно меня, я буду существовать здесь."
  },
  Voice_5871_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5872_AwakerVoiceContent = {
    Text = "Воспользуйтесь уроком!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Почтительнее, младший. В армии существует порядок старших и младших, приказы выполняются безоговорочно, такое поведение будет наказано."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Я готов предложить обслуживание для этих «маленьких игрушек», но осмелитесь ли вы им воспользоваться?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О изобретении"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Вы здесь Носитель, но также и Гость моего салона. Я приготовлю для вас самое лучшее угощение — вам больше нравятся ярко-красные нижние юбки или белые с розовыми цветами пижамы? Ещё что-нибудь желаете?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Извините, солнечный Погоня за светом здесь немного резкий... Крыса, пришедшая из темного подземелья, пока не может Адаптироваться ."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Может разъедать всё, стирать всё... Это действительно ужасающее оружие. Если бы я тогда знал об этом... Ха-ха."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Существует слух, что человеческое тело, корчась в пламя, похоже на танцующее."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О пламя"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Не выходи ночью, даже с источником света в 2000 люмен это не гарантирует полной безопасности... Как только ты войдешь во тьму, демоны, скрывающиеся за пределами взгляда, настигнут тебя и поглотят тебя снова и снова... до тех пор, пока ничего не останется."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О ночи"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "Плакай."
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "Получено."
  },
  Voice_5882_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "Это стремление к жизни, побуждающее лебедя бороться за возвращение в даль небес."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5883_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Начало меняться!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5885_AwakerVoiceContent = {
    Text = "Спасите!"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5888_AwakerVoiceContent = {Text = "А"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "А, Браун пробежал мимо! Я лучше уйду...\nЯ хотела подружиться с ней, но в итоге ещё стала её кошмаром... Она точно не хочет меня видеть.."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_5889_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Часовня? Очень благодарен, но на самом деле я не такой уж и старомодный. Пока в моем сердце живут учения Божьей любви и я исполняю Его волю, моя душа не будет отдаляться от Его славы."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Разговоры · О часовне"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Моё имя — Оргр. В соответствии с нашим контрактом, я принесу вам клятву рыцарской верности, обеспечу вашу защиту и устраню ваших врагов. Сегодняшняя клятва останется в моей памяти навсегда."
  },
  Voice_5891_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5892_AwakerVoiceContent = {
    Text = "Та иссохшая женщина с двумя зрачками, пахнет точно так же, как спартанская вошь."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Агриппа"
  },
  Voice_5892_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Агриппа\" будет разблокировано"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Любимая вещь? Конечно, это удача. Каждый день, выходя из дома, нужно пожелать себе везения."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "Пожалуйста, не надо говорить Ханне, что я прячусь здесь. Я еще не готова.."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Разговоры · О Ханне"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Так как?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Вы мой уважаемый Гость. Знайте, я могу позволить только вам одному отсрочку платежа. Всё-таки, много лет не видел таких безупречных голов.."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5899_AwakerVoiceContent = {Text = "Ой!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Любимые вещи... Король не должен иметь таких черт характера, но если это позволит избежать надоедливых докладов и молитв, свернувшись на мягкой постели, я с удовольствием отдохну."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Я восприму ваше неуважение как просьбу о вечном сне."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Ненавидишь? Я ненавижу судьбу, от которой невозможно убежать, и трагедии, которые суждено пережить."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Хм!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(сдержанное хмыканье)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Не подходи!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Ой, хотите узнать мой секрет? Всё это — её имя, тело, внешность и голос, принадлежит хозяйке одного черепа из Сан-Педро. Она договорилась со мной... После её смерти я стала ею. Что касается её местонахождения... Это моя самая прекрасная избранное, не так ли?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5906_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Вы очень приятный Гость, даже я очарован вашей уникальной головой... Если у вас есть желание её продать, обязательно посетите мой магазин. Ха-ха... Это была просто шутка."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5907_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Хотите узнать мою настоящую личность? Сейчас ещё слишком рано. Вам нужно просто поверить в следующее: все заблудившиеся дети найдут приют в моём магазине. Вас это тоже включает, Правда?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5908_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Никто не получит Урон."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "Ещё не Конец!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "Увидев вашу такую усердную фигуру, мне даже немного неловко так быстро брать плату. Поэтому, ваша голова пока останется на своём месте.\nНо не забывайте, она уже предназначена быть моей личной собственностью, да?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5911_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Раньше я не выглядел так, она дала мне новорождённого. Значит, вы тоже тот, кто дал мне вторую жизнь, я также бережно сохраню ваш череп."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5912_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Полностью избавиться от тьмы."
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "Оказывается, приключения такие опасные.."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Почему эта дурочка каждый раз убегает, как только меня видит? В следующий раз я хочу наступить на её шерсть и посмотреть, куда она денется."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Разговоры · Об Ай Джис"
  },
  Voice_5915_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Ай Джис\" будет разблокировано"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Нгх!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "Хм~хаха!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5918_AwakerVoiceContent = {
    Text = "Ха-ха-ха-ха!"
  },
  Voice_5918_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Тот малыш очень сообразительный, для выживания на улицах нужна такая мудрость. Если бы я всё ещё расследовал дела за пределами, то обязательно подружился бы с ней."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_5919_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Тот святой отец не может спасти всех людей. Возможно, он сможет помочь какому-то неудачнику, но не вытянет всех людей из трясины... Я с интересом жду его, жду краха его веры."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Болтовня · О Сальвадоре"
  },
  Voice_5920_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Сальвадор\" разблокируется"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Вы можете найти всё необходимое в канализации Лондиниум: лосось, мыло, наполовину выпитый виски...\nЧто? Вы спрашиваете, почему я так хорошо знаю? Однажды я прополз Часть 5 ли, таща тело старшего брата.."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О канализации"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Пади передо мной!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Встань на колени."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "После того, как я увидел Реальность мир за пределами боя, я на время усомнился в ценности так называемых «героев». Но к счастью, я встретил тебя, честного, храброго, непорочного. Я буду сражаться под твоим началом изо всех сил ради мира и стабильности мира. На этот раз я точно смогу завершить свое искупление."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5924_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Ах! Ой.."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Нечистота, разврат, хаос — вот наша Огромная Огромная сила."
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "Я ненавижу ваше лицемерие. Думаете, я сошел с ума, что я жалок, верно? По-моему, вы — это Икар, ослепленный солнцем. Вы и есть те жалкие создания."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Позвольте мне идти первым!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Дыхание этих парней незнакомо, они не принадлежат к жизни, естественно возникшей на этой планете."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О людях за пределами звёзд"
  },
  Voice_5929_UnlockDesc = {
    Text = "Получите пробуждающее тело «Венкор», «Тинкерт», «Фейнт» или «Ванда», чтобы разблокировать"
  },
  Voice_5931_AwakerVoiceContent = {Text = "(стон)"},
  Voice_5931_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "Аннигиляция!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Пожалуйста, не надо.."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "Становиться монстром мне всё равно, я всегда хотел только силы для мести."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5934_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Кроме как избавиться от противника, у тебя есть ещё какие-то желания? В обмен я исполню твоё желание... конечно, в диапазоне моих способностей."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_5935_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(стон)"},
  Voice_5936_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Партнёр?.. Я подумаю об этом. Пока я не разберусь, старайся выжить."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_5937_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "С момента первого точного документирования Феномен Растворения затронул жизнь более миллиона людей. Наши действия решают судьбу всего человечества."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "Максимальная мощность!"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Осторожно, морское буйство!"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Осторожно, морское буйство!"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5942_AwakerVoiceContent = {
    Text = "Привет!"
  },
  Voice_5942_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Я являюсь Его принцессой, также Его матерью. Что до тебя, перед Ним ты всего лишь ничтожный Муравей."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Всё идёт хорошо, поднимите торжественный парус."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Не приближайся ко мне, хочешь стать игрушкой принцессы или жертвенным предложением для божественного праздника?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5945_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Легко и просто, полная победа!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Легко и просто, полная победа!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Я разрешаю тебе Свидетельство тот сияющий момент, который нарушит все этические нормы."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5946_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Ускользание? В телекинезисе часто создаются такие пустоты! Пустоты, созданные Касией, ссылаются на другое измерение. А пустоты, созданные Растворением, тоже?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Страж, я использую Независимый Богини-Матери, чтобы оставить для тебя место у трона в глубоком море. Ты станешь свидетелем возрождения после уничтожения. Будь благодарен, ибо это обещание Богини-Матери!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5948_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Учитывая твоё почтение, я дам тебе Лечение. В начале, конечно, была Рождённый войной. Но теперь я понял, что вся моя роскошная жизнь исходит от Него. Смерть – это не Конец, Он возродит меня через мрачный цикл, чтобы наслаждаться вечной жизнью.."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5949_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Желание той женщины действительно вызывает смех. Ничто не может выжить после аннигиляции, даже «бог» тоже."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Разговор · О Тайис"
  },
  Voice_5950_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тайис\" разблокируется"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Я являюсь человеком, обладающим даром колдовства, а не всемогущим существом, и поэтому могу совершать ошибки. То, что эта женщина втянула всех людей в эту ситуацию, стало результатом моей небрежности... Поэтому мне нужна твоя поддержка. Чтобы в любой момент откликнуться на мой призыв, тебе позволено разместить ложе в моей опочивальне."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5951_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Ты несёшь на себе задачу противостояния бедствию, для твоего возраста это действительно тяжело... Если бы с самого начала знал, что не сможешь изменить будущее, стал бы ты так же преданно выполнять свою миссию? Не надо торопиться с ответом, подумай об этом, пока будешь отдыхать. Мне очень интересен Твой Лечение."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5952_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "С момента пробуждения меня уже прошло некоторое время, разве у тебя нет ничего, что ты хотел бы Требование у меня? Откровение богов, абсолютно точное Пророчество, даже сокровища затонувшего континента — разве тебе действительно всё это неинтересно?\nХм... странный человек."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5953_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Я никогда не требовал поклонения от кого-либо. Самонадеянные действия глупцов только усиливают мою усталость... Можете идти, время отдыха настало."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5954_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "В тебе мне не вижу никаких качеств, схожих с качествами моих подданных... Ладно, может быть, это к лучшему. Вспоминая ту женщину, мне чувствую усталость."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5955_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Бог относится ко всем одинаково."
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "Я знаю, ты специальный зритель, и я не могу просто так отправить тебя в другое измерение, иначе будут неприятности. Эй, а ты когда-нибудь так делал с кем-то другим? Ну что ты спрашиваешь, это же мой секретик!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Ой-ёй-ёй, тебе интересна эта внешность? Похоже, что в каждой потере есть и своя находка, наверное, это одна из моих удач, Лекк?"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Мисаг — место, где у меня осталось больше всего памяти, и также мой... самый тёплый дом."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Доверь это мне."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "Слишком наивно!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Священное пение глубокого моря!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "То, что мне было даровано ——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Навык: |·Спокойное море"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Если вы готовы признать меня всё той же «Рамоной», то продолжайте называть меня так."
  },
  Voice_5964_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5965_AwakerVoiceContent = {
    Text = "Как, ты тоже хочешь использовать мой Негодование?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_5965_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "Истина... здесь проясняется."
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "Полученную еду нужно сразу съесть, это закон улицы!"
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Чувствуется, как будто наелся!"
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Ээ... щекотно, Браун, почешите мне спину."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Новые механические компоненты окажут большую помощь в работе моего механизма — разве это нельзя считать симпатией? Извините, боюсь, я не понимаю ваш вопрос. Для механической куклы предпочтения не имеют никакого значения."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Прими Удар!"
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "Прими это!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Подумай хорошенько."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Спокойно подумай."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Девушка Венкор и я родом не с этой планеты... Кроме Тинкерта, на моей родине мало что держит меня. Не знаю, какие чувства девушка Венкор испытывает к своей родине?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Разговоры · О Венкоре"
  },
  Voice_5976_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Не подходи ко мне сзади, если не хочешь, чтобы я свернул тебе шею."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_5977_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Хаа— Как вы могли допустить, чтобы дикие кошки бегали по кампусу?! Что если эта невоспитанная тварь кого-нибудь поцарапает?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Мои глаза вызывают неприятные ощущения? Вот и отлично, именно эта свирепость помогла мне выжить в преисподней."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_5979_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Лестные слова можно опустить. Что ты хочешь получить от меня? Тратить энергию на поддержание моей разумности, наверняка ты что-то хочешь Требование."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_5980_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Моей целью мести всегда были спартанцы, но сейчас даже этот город-государство больше не существует... Что ж, стать твоим клинком тоже неплохо. Я с трудом признаю тебя своим компаньоном, но если ты осмелишься на предательство, я вырву твое сердце."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_5981_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Мои руки покрыты кровью. Мои слабые соплеменники не признают мою месть, они сплетничают за моей спиной о моей жестокости, о моём непонимании добра, о моей неблагодарности... Месть всегда была только для себя, она не имеет никакого отношения ни к кому другому."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_5982_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Нужно использовать больше стали."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Нужно использовать больше стали."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Умри."},
  Voice_5985_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Я... называй меня Венкор, все так меня и зовут. Да, называй меня так, как и они.."
  },
  Voice_5986_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5987_AwakerVoiceContent = {
    Text = "Это тело — щит моего господина!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Это тело — щит моего господина!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "«Щелкунчик» — это романтическая сказка-фантазия для девочек, но эти отвратительные типы видят в ней лишь разлетающиеся изящные конечности и пошлые плотские желания… Омерзительно."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Необходимо... уничтожить...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Пандия... Она называет это воспитанием? Хаха... Позвольте мне сначала немного посмеяться. Люди всё же слишком мягкосердечны, всё, что они делают, выглядит как детская игра."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Беседы · О Пандии"
  },
  Voice_5991_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Пандия\" разблокируется"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Не подходи!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Повторная попытка представиться? Что ж с тобой поделаешь. Я Дженкинс, это Браун. «Писк!» \n Не забудь! Если перепутаешь наши имена, я тебя фонарём хорошенько отхожу *шёпотом*! «Писк чирик?!»"
  },
  Voice_5993_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_5994_AwakerVoiceContent = {
    Text = "Прыгай, прыгай!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Прыгай, прыгай!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Предлагаю воспеть открытие!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Хм."},
  Voice_5997_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "Нужно одна точка камня, два резца и три пучка ирисов, тянущихся к солнцу. Я смогу создать для вас всё."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_5998_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "Только такой Уровень?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Угу."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Эта бесполезная Рождённый войной.."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6003_AwakerVoiceContent = {Text = "(стон)"},
  Voice_6003_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "После смерти Тиберия Граждане Рима наконец исполнили своё давнее желание — бросить его в Тибр к рыбам. Конечно, за это они заплатили одну точку: их бросили в арену, чтобы доставить мне удовольствие."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(стон)"},
  Voice_6005_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "Я могу чувствовать, что у этой маленькой девочки есть Огромная Огромная сила, похожая на мою. Она еще не полностью понимает мощь этой силы, ради тебя я буду адекватно тренировать её."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Разговоры · О Лили"
  },
  Voice_6006_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лили\"разблокируется"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Проклятие, вы ещё смотрите на меня свысока?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Доказательство существования."
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Доказательство существования."
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Я верю, что всё имеет свою причину, но... эти бессмысленные акты насилия, эти предрассудки, которые заставляют братьев и сестёр враждовать и ненавидеть Близкий Близкий друг друга, действительно вызывают у меня глубокую печаль. Если говорить о том, что мне противно, то, пожалуй, это именно это."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Не хочу использовать эту силу."
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "Не расслабляйся, держись!"
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Фырк"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Стоп!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Стоп!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Касия такая крутая! Она может пфф—— и вот у неё уже появляется маленький кролик!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Болтовня · О Касии"
  },
  Voice_6016_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Касия\" будет разблокировано"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Магия, готова!"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "Растворение... Приходится признать, что в этом мире действительно существуют вещи, которые нельзя контролировать с помощью власти."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6019_AwakerVoiceContent = {Text = "А——"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Танцуй в зелёном пламени."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Не горюй, шрамы — это награды воина."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Дрожи перед этими мышцами...... Они всегда готовы, чтобы срубить твою голову."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Время еды? Или ещё время акции?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6024_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Угу! В таком случае, партнёры Ореты не исчезнут."
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6025_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Учитель Сильвия сказала, что когда получаешь что-то, нужно сказать спасибо... спасибо, спасибо, спасибо!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6026_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "На этот раз привидением будет Орета! У тебя всего 5 секунд, чтобы спрятаться! 5, 4 —"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6027_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Все исчезли после начала игры в прятки, на этот раз Орета обязательно найдёт всех!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6028_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Поскольку на дне моря обнаружили кости Юй, считают, что Юй любил воду, и хотят построить фонтан снаружи спальни Юй? \n Ха... делайте как хотите, не беспокойте меня такими пустяками."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Капля в океане, смиренный Последователь вечности, Мириам... приветствую тебя."
  },
  Voice_6030_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6031_AwakerVoiceContent = {
    Text = "Теперь моя очередь."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Хе!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Впечатляюще... Ваша случайно оброненная фраза разрешила проблему, которая беспокоила меня месяцы."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6033_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Сравнительно с благородными девушками на винном собрании, характер Морфи кажется действительно очаровательным."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_6034_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Мастер психотерапии? Это дети преувеличивают. Я просто делаю всё возможное, чтобы выслушать их и облегчить тяжесть на их душе — как я всегда это делал."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Не смей больше меня недооценивать!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Не смей больше меня недооценивать!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Хочется пить? Чистая вода в тюрьме — это настоящая редкость."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6038_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Хороший ребёнок, послушный малыш~ не бросай на полпути, ладно?~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6039_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Ты уже попался в мою сладкую ловушку, Правда?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6040_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Усилий, ещё одна точка~ скоро достигнем вершины блаженства~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6041_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Я вступил в школу в четырнадцать лет, если бы тогда я смог успешно её закончить, вы сейчас должны были бы называть меня «директором»."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Твой слабый мозг, похоже, не способен запомнить ничего."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Ты спрашиваешь, какова моя мечта? Благословление путешествия, безопасность прихода и ухода, разве это не считается? \n Остальное... Я не думал об этом... Но я хорошенько подумаю и расскажу тебе."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6044_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "«То, чего я жажду, – это тайны мироздания, я хочу понять, какая Огромная Огромная сила управляет мной.» Хотя меня не устраивает Сюжет этого романа, и вымышленная наука в нём кажется наивной до смешного, но, прочитав его, ты должен был понять меня... Подожди, ты не читал эту книгу?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6045_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Миссия и Колесо Судьбы — это похожие вещи. Их нельзя легко оставить, да и необходимости в этом нет."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6046_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Я всегда выгляжу занятым? Да, помощники иногда могут взять на себя часть работы, но в некоторых исследованиях я незаменим. Хочешь помочь? Тогда заходи изредка и подтверди, жив ли я еще."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6047_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Ты думаешь, я злюсь? Ты знаешь, сколько мышц нужно задействовать для улыбки? Я рассказывал об этом знании на уроке, очевидно, оно просто ускользнуло от тебя. Ответ: как минимум семнадцать, и у меня нет причин злиться на тебя."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6048_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Мисс Рамона сказала, что мне не нужно подстраиваться под всех, вы понимаете, что это значит?.. Это означает, что больше не нужна моя покровительство?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6049_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "У меня тринадцать отчетов, требующих утверждения, шесть поврежденных коммуникаторов, ожидающих ремонта, и Часть 5 разных экспериментов по извлечению сердечника из серебра, за которыми нужно наблюдать... Поэтому, вместо того чтобы тратить ограниченное время на Беспокойство мне, лучше займитесь укреплением своих умственных способностей."
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6050_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Надеюсь, в следующий раз моя родная земля ответит на мой призыв."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Блокировка снята."
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "Я так рад... Вы так предвзято ко мне относитесь."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6054_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Другие могут злиться, чтобы вашей предвзятости, знаете ли."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6055_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Разве вы также томитесь по Я?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6056_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Наконец-то Конец, наконец-то больше не нужно видеть эти чёрные, липкие.."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "За то, что вы так много сделали для меня, ваша любовь уже слилась с моей, как вода и молоко.."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6058_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6059_AwakerVoiceContent = {
    Text = "Привет!"
  },
  Voice_6059_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Как опасно!"
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "После стольких усилий, тебе пора насладиться результатами, Правда? Подойди немного ближе, я не разочарую тебя~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6061_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Я, я поняла ваше намерение... хотя пока ещё действую неуклюже, но Ай Джис постараюсь изо всех сил биться ради вас!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6062_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Ваш взгляд обжигает меня... Не доставляет ли Ай Джис вам хлопот?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6063_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Ай Джис очень испугана... не знаю, оправдаю ли я ваши ожидания.."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6064_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Вы, вы так смотрите на меня, Ай Джис это совсем не привычно... Вы не боитесь проклятия?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6065_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "Пожалуйста, не смотрите мне в глаза... Ай Джис боится, что может причинить вам Урон... Ведь я как монстр.."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6066_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Запах зверя и всё такое, это просто удача. Ты не надо ошибаться, ладно?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6067_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Я ещё не могу остановиться.."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Огромная Огромная сила, неиссякаемая!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Огромная Огромная сила, неиссякаемая."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Вам нравится море? Мне независимо, но мне всегда нравилось море. Я всё ещё помню, что много лет назад, в тот день, море так нежно подарило долгожданную смерть несчастному мне."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Неизвестно почему, накатила волна небывалого наслаждения.."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Этот темный поток разорвет врагов на части."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Этот темный поток разорвет врагов на части."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Я всегда жду человека, который сможет научить меня настоящей любви, боли и желанию. Можете ли вы удовлетворить меня? Сможете ли вы спасти меня из тёмного заключения?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6076_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Хочешь знать правду? Я ненавижу тюрьму, ненавижу темноту, ненавижу до смерти. Я хочу быть в центре внимания, хочу быть зажжённым.."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6077_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Всё для того, чтобы обеспечить вечное благополучие в будущем."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Хочешь насладиться Я? Тогда стань моим рабом. Я сделаю так, что ты растопишься от жара~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6079_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Считайте это даром подданного."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Надоело, надоело. По сравнению с теми трепещущими большими преступниками, это просто детская игра. Вот ты и составь мне компанию~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6081_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Хочу больше раб, хочу слышать их стоны и мольбы—— \nПринеси мне больше раб~пожалуйста~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6082_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Извини, я снова погрузился в прошлое. Пожалуйста, не надо грустного выражения. Теперь твоя очередь рассказывать мне свою историю. Чувствуешь желание написать стихи? Твои приключения, твои наблюдения, твоя радость и твоя печаль — превратятся ли они в ручьи, текущие от мыслей к пальцам?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6083_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Я всего лишь след, который со временем исчезнет с пергамента, но благодаря нашей встрече я остановился в этот момент. Возможно, это какое-то чудесное явление. Я буду бережно хранить это чудесное явление и творить для вас бессмертные строки Псалтири."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6084_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Кто-то однажды сказал мне, что стихи создаются, чтобы их читали... Могу я послушать твои мысли?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6085_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Был ли у вас такой опыт? Прощать обиды других, но в итоге не получать желаемого результата. Подарив розу, в руках не осталось Оставшийся аромат, лишь острые шипы, пронзившие кожу и оставившие кровавые следы."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6086_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Моя кисть.."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "Неверно.."
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Это благословение от великого существа!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "Покровительство Великого Бледного Существа."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "У меня нет времени на Дрёма, Феномен Растворения уже уничтожил два моих тела. Перед тем как меня настигнет Конец, у меня слишком много вопросов, которые нужно разрешить... Помоги мне, начни с подготовки материалов для эксперимента. Я верю, что ты не настолько глуп, чтобы ошибиться в расчетах, Правда?"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6094_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Мне нравятся витражи Фонтенбло, они окрашивают лица людей в разные цвета: отчаяние фиолетового, лесть синего, конечно, и мой любимый красный амбиций.."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Здесь я часто ощущаю присутствие моего Владыки, но, возможно, я ещё не готова встретиться с ним лицом к лицу… Как бы то ни было, благодарю тебя за предоставленный мне кров."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Предательство превращает человека в монстра, независимо от того, с какой стороны ни посмотри. Поэтому я ненавижу предателей."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Хамлин, к вашим услугам."
  },
  Voice_60985_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_60986_AwakerVoiceContent = {
    Text = "Я когда-то встречал человека, который обладал почти инстинктивным пониманием музыки, его концерт и симфонии невозможно забыть.\nЭто был Реальность гений."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О старом друге"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Я не люблю тратить время на интриги. В сравнении с музыкой, их художественная ценность ничтожна. Но для устранения препятствий на пути это необходимый инструмент. Чтобы достичь вершины музыкального совершенства, я не против использовать его."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О стратегии"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "Непочтительно."
  },
  Voice_60988_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Снова эта мелодия. Что же это такое? С тех пор как я услышал её в прошлый раз, она не выходит из головы и не даёт покоя."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_60989_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "С точки зрения техники, планирование и музыкальное дирижирование не имеют различий. Человеческая природа, эмоции, желание... они столь же четки и послушны, как ноты на пятилинейке, выстроенные передо мной, следуя траектории дирижёрской палочки. Поняв музыку, вы поймете всё."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Пустые разговоры · О общности"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Ещё одна точка, всего одна точка, я должен завершить это, я должен услышать это!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_60991_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Ммм."},
  Voice_60992_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_60993_AwakerVoiceContent = {
    Text = "Непочтительно."
  },
  Voice_60993_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Ммм."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "Музыка превосходит язык, превосходит слова, превосходит всё. Если это не совершенство, то Не знаю, что это такое."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_60995_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Обратите внимание на ритм."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Настройка завершена."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Я очень рад, что ты тоже понимаешь важность тренировок."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Я принесу прекрасное выступление."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Завидуешь? Эти прочные чешуйки являются доказательством благородного происхождения."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "Я тоже когда-то получал похвалу, но... это Не истинным талантом.\nМои работы — всего лишь подражание предшественникам."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Поболтать·О произведении"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Духовые, струнные... переплетаются в восходящем движении, потом снова переплетаются, мотив воспроизведение... Я пришёл, это мой Реквием, для того рано ушедшего гения, для той звезды, что пала."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_61001_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Хм? У тебя есть новая мелодия, которую ты хочешь показать мне?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Этой мелодией почти́м души умерших."
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "Та зелёная танцовщица обладает такой грацией, что вполне может стать примой придворного балета.\nЕсли бы только можно было, я бы с удовольствием с ней поработал."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Лиз"
  },
  Voice_61004_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Лиз\" будет разблокировано"
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "В оркестре может быть концертмейстер, но одни концертмейстеры не составят полноценный оркестр. Мой оркестр не нужен в тех, кто думает только о самопрезентации."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Кажется, я услышал мелодию, здесь кто-то проводит репетицию?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_61007_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6100_AwakerVoiceContent = {Text = "Умри!"},
  Voice_6100_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Верно, верно, именно так! Это и есть финальная месса, Реквием, посвящённый самой музыке!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_61010_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ах, Страж, ты пришёл как раз вовремя. Скажи, что думаешь о твоём видении этой мелодии?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Струнные, звучать."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_61013_AwakerVoiceContent = {
    Text = "Крещендо, крещендо!"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Оно стало ясным — извилистая мелодия, подобная стону души... Я подтверждаю, что слышал её где-то раньше."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_61014_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Разум, порядок, я использую их, чтобы создать ступени, подниматься по ним вверх, и в конце концов открыть двери того храма. А за этой дверью разум и порядок больше не существуют — — истинная вечная музыка будет выше разума."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Разговоры · О разуме и порядке"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Смотри, моя рука, раз, два, три."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Я послушал выступление вашего так называемого оркестра, в нём было множество ошибок. Но ничего страшного, я уже составил подробный план, и к Серебряному Источнику мы подготовим идеальную программу."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Я до сих пор не могу забыть тот день, когда впервые услышал мелодию де,глубине сознания. Между этими нотами и аккордами всё в реальном мире перестало существовать, осталась только музыка, чистая и возвышенная музыка."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "К сожалению, похоже, что нужно усилить репетиции."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Это приказ."
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "Я обычно не делаю таких приглашений, но… Не хотите попробовать? Возьмите дирижерскую палочку и вдохните новую жизнь в музыку."
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_61020_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Вместо словесного выражения я больше предпочитаю выражать себя через музыку. Но процесс общения с тобой подобен дирижированию оркестром, прошедшим бесчисленные репетиции, — плавно и полный неожиданных моментов.\nНезависимо от того, говорим ли мы о самой музыке или обо мне ещё, ты остаёшься специальным существом."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_61021_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "В симфонической музыке очень важно взаимодействие между инструментами. То, как различные партии вступают и выходят, создает разное настроение произведения. \n Я хочу сказать, если пробуждающее тело — это выступление, ты показал себя отлично."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_61022_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Тебе тоже нравится эта мелодия? Всего четыре такта для полного представления мотива, медные духовые толкают мелодию вверх, пока она не достигнет темы. Такой подход оказал влияние на бесчисленное множество потомков... Извини, я слишком много говорю?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_61023_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Совершенное исполнение."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_61026_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "В каждом из нас скрыта своя собственная мелодия, она заперта в разуме и теле, и только в моменты безумия может полностью расцвести."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Только музыка достойна похвал!"
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "Только музыка достойна похвал!"
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Иди."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Слушайте, это последний Реквием!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Проси пощады!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Слушайте, это последний Реквием!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(стон)"},
  Voice_6104_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Вы тоже хотите погибнуть в зелёном пламени?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Смеешь отвлекаться?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "Концентрируйся!"
  },
  Voice_6108_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = "Как же в университете ещё есть такие милые дети~ Я только что спросила его: «Не надо ли стать моим рабом», и он покраснел, заикаясь, пробормотал что-то вроде «Я уже рыцарь Хранителя тайн»...\nВедь это же вообще не противоречит~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Оргр"
  },
  Voice_6109_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Оргр\" будет разблокировано"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Не думай приближаться к принцессе."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Навык: |·Девятый вал"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Принять судьбу."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Навык: |·Волны прибоя"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Ворота родины удаляются от меня... Нет... Не надо ещё раз.."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Не мешай!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Не мешай!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Возмите ответственность за свои действия."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Хочу умереть?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Я думаю, у меня снова началось Раствориться... Моё сердце растворяется! Нужно только несколько таблеток аспирина, немного дисциплины и капля боли... Этого должно хватить, чтобы поправиться.."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Даже ты не можешь справиться с этой чертовой проблемой? Ты всё ещё гоняешься за растворением, совсем безрассудно."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Я последний римский воин —— Юу Хаши!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6120_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Я последний римский воин —— Юу Хаши!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Растворение…? Конечно, я знаю, это же означает снять отношения между хозяином и слугой, что тут сложного."
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Я уже призван, граница между божественным и глупостью стала размытой."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6123_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Мм...... с правильным балансом силы, массажные движения просто великолепны~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Не слишком ли старомодный Ежедневное обслуживание здесь? Жутко и мрачно, как будто здесь водятся привидения."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Здесь есть пышная растительность, спокойный воздух де это может исцелить болезнь сестры. Для нас двоих это самый прекрасный, новый дом."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Не ожидала, что смогу встретиться с вами здесь... Не знаю, как она жила после того случая. Как бы я ни спрашивала, она всегда отвечала, что всё в порядке... Извините, и благодарю вас за то, что помогли нам сестрам воссоединиться."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Фейнт"
  },
  Voice_6127_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Фейнт\" будет разблокировано"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "В дар моему господину."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "В дар моему господину."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Спокойно спокойно спокойно.."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "В моём теле живёт много «Я»: счастливых, грустных, Негодование... Они любят бисквитный торт, они ненавидят дождливые дни в Лентиниене, их всех зовут «24», и они все почитают вас."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6131_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Я раньше работала до глубокой ночи, ткала, стирала, убирала, была няней, даже драила полы... Я делала всё, лишь бы заработать. В то время жить означало просто существовать.\nсейчас у нас есть свежая еда, тёплые постели и такие добрые господа, как вы... Это даже не могло присниться."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6132_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Независимо от обстоятельств, мы разделим один стейк, одну кровать и никогда не доставим вам хлопот."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6133_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Хе-хе, та женщина боится, что я выйду, и ночью даже спать не смеет. Расслабься, ради подарка, я не собираюсь тебя убивать.\nКто я? Конечно, «24», хаха!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6134_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Сейчас я чувствую себя прекрасно. Что, вы говорите, что мой разум уже захвачен чем-то другим? Ха, чушь... э.."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6135_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Как подданному, ты ещё смышлёный. Перед тем как впасть в следующий долгий сон, я временно задержусь здесь."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Мм, сегодняшняя морская вода очень теплая.."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "Белая птица, летавшая в сновидении, Нисхождение."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Как ты и пожелал, моё существование стало более реальным."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Так приятно, так удовлетворён!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6141_AwakerVoiceContent = {
    Text = "Вкусно!"
  },
  Voice_6141_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Доверьте это мне!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Доверьте это мне!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Добро пожаловать на — наш Роскошный Роскошный пир!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Вспышка безумия·неистовство"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "В этой девочке течёт, без сомнения, кровь моего рода... Нет, мне ещё не достаточно лет, чтобы иметь потомство. Но её Огромная Огромная сила действительно того же происхождения, что и моя."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О божественной крови"
  },
  Voice_6145_UnlockDesc = {
    Text = "Получите пробуждающее тело «Ай Джис» или «Морфи» для разблокировки"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Благодарность хозяина, Гарен ни на мгновение не забывает!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—— Сладкое, очень вкусно!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Гарен недавно сидит на диете, не может есть слишком много..."
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Будь моим противником, эти парни не достаточно хороши."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Объяснение искусства так же абсурдно, как объяснение акций железнодорожных компаний — пожалуйста, не надо мучить жалких художников."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Ай Джис... что она сделала не так?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Я услышал(а) вашу молитву."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Я услышал(а) вашу молитву."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "Хм, непочтительный человек."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "А, не тот ли это был великий господин? Нет, ничего. Когда я в последний раз поздоровался с ним, он даже не узнал меня... Я всё время ждал его в тюрьме, надеясь, что он заберёт меня, но до самого бунта он так и не пришёл.."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О «N»"
  },
  Voice_6155_UnlockDesc = {
    Text = "Разблокируется после прохождения «Расследовательская операция» главы 7"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Откликнувшись на пробуждение человека и заключив партнёрство, я стремлюсь выполнить свой долг, который не был завершён. Если ты сможешь вырасти до уровня, позволяющего сразиться со мной, это было бы просто великолепно."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Сестра, Коричневый, трус из дома для бедных — их мне хватит как друзей. Ээ... ладно, ты тоже считаешься. Коричневый, дай Хранителю тайн конфету.\n«Писк чирик?!»"
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6157_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Восточный трущобы не подходят для выживания детей. Хитрый и коварный старый мастер находит способы урезать зарплату мальчикам-газетчикам, придирается к скорости работы молочников... В общем, чтобы выжить на улице, можно рассчитывать только на себя, никому нельзя доверять, ни на кого нельзя положиться."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6158_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Мои «дурные привычки» не могу изменить в одночасье, ты ведь понимаешь? Спать под мостами и в дождевых колодцах, питаться отходами – просто выживать уже достаточно трудно... Ты не можешь требовать, чтобы я сразу привык заправлять постель после подъёма! На Адаптироваться нужно хотя бы полмесяца!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6159_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Потеряться в пространстве — это действительно неприятное чувство. Раз уж ты вытащил меня оттуда, говори прямо, что тебе нужно, но я не обязательно смогу помочь.\nМой возраст налицо, ты же не будешь слишком строг к ребёнку?~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6160_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Эй, западняк! Ты видел Брауна? Этот обжора снова куда-то по запаху побежал."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6161_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "«Те, кто обладает силой, не должны угнетать других, ибо в ваших жилах течет моя кровь» — Я помню наставления бога милосердия и буду использовать эту силу для защиты близких мне людей."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6162_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Знаешь, что я увидел в начале Вселенной? Я могу сказать тебе, там ничего не было."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6163_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Стала ярче."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "Вечный Искра.."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Связать с прежней родиной стала ещё крепче."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Если смогу избавить людей от страдания, я буду удовлетворён."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Дай мне больше команд, бледный посланник, пусть твоё пламя направит меня вперёд."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "Человека закаляют не только тело, но и душу."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Ой!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "Ух! Ваша температура для Шань ещё немного высокая. Но... она и тёплая, и горячая. Мне это нравится."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "А... у вас есть ко мне какое-то дело? Если можно, давайте перейдем за кулисы и поговорим там.."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Не распустившись, уже завяла, словно спящая лилия, поглощенная водой... В том холодном и бурном потоке, в слабой надежде обрести тишину, не смея стремиться к своему счастью... Это я, Страж."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6176_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Я когда-то задавался таким вопросом: может ли боль длиться дольше самой жизни? Если это так, не будет ли Тишь вечного сна счастливее мучительного пробуждения? После того как я проснулся, я тоже некоторое время был погружен в эти мысли, пока вы не предоставили мне этот тихий приют.."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6177_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "В санатории я пытался завести друзей, но никто особо не хотел со мной общаться... Может быть, из-за этого разъедающего «яд»? В общем, когда вы подходите ко мне, нужно быть осторожнее."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6178_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Ночные ветры приносят звуки колоколов, которые успокаивают душу. Хотите присесть на каменное кресло и послушать? Я расстелю для вас шаль."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6179_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Вы слышали о «Морском погребении»? В моем родном городке есть такой обычай: Граждане опускают тела умерших в море, поэтому море является последним пристанищем для всех людей. А я вернулся в море намного раньше.."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6180_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Хм!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6182_AwakerVoiceContent = {Text = "А"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Ой!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6184_AwakerVoiceContent = {Text = "А"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Запись боевого журнала архивирована. Спасибо, Страж."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(стон боли)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(стон боли)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(стон боли)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Ещё можно продолжить"
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "Посетители салона получают наилучшее гостеприимство... В качестве входного билета, подготовили ли Гость подходящие секреты для этого пира?"
  },
  Voice_6190_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6191_AwakerVoiceContent = {
    Text = "Мне нравятся новые впечатления. В течение тысячелетних путешествий я был свидетелем множества интересных нововведений и изобретений, таких как поэтические жанры, кадры в кино. Люди — действительно интересные существа."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Хм, Лили знает её. Когда мамы нет, Лили живёт у неё дома."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Разговоры · О Давдейле"
  },
  Voice_6192_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Давдейл\" будет разблокировано"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Тот, кто потревожил мой вечный сон, это ты?"
  },
  Voice_6195_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6196_AwakerVoiceContent = {
    Text = "Бог? Только глупцы доверяют свою жизнь такому призрачному и нематериальному существу. Вместо того чтобы полагаться на богов, лучше подумай, как стать сильнее."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Что за Носитель гладиатора, просто презренное насекомое."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Пустая болтовня · Об Агриппа"
  },
  Voice_6197_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Агриппа\" будет разблокировано"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "После победы, пожалуйста, позвольте мне забрать материалы для размножения потомства."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Большой Близкий Близкий друг! Партнёр! Уху, будем настоящими друзьями с Орета навсегда!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Сейчас я в Тревога... Если не хочешь умереть (хочу умереть), лучше держись от меня подальше."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Тот человек... Разве его отношение к другим нормально? Госпожа Сара сказала, что дети не должны капризничать.."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_6201_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "Слава победы с вами."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Есть,не могу больше есть~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Внутренняя пустота, теперь она заполнена~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Снова стало на одну точку жарче~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Я знаю эту девочку, она иногда стоит далеко за пределами сцены, наблюдая за представлением. Ей лучше не подходить, иначе эти маленькие зрители будут «полностью измотаны»!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Фейнт"
  },
  Voice_6206_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Фейнт\" будет разблокировано"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Тинкерт говорил, что нужно отвечать добром на добро. Поэтому, где бы я ни мог помочь, я обязательно сделаю это.."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Привет, Страж, есть ли что-то, чем я могу вам помочь?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Рано или поздно я вернусь на поле боя как Босс атакующих."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6209_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Можешь поверить? Я чувствую, что сломанная кость в ноге срастается."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6210_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Искренне благодарю за ваше доверие, которое позволило мне достичь такого уровня. Похоже, вы также стремитесь к справедливости, поэтому я обязательно продолжу здесь путь воина с честью."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6211_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "День начала пути приближается, кипящая Бурление крови в груди."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6212_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "Честь воина возвращается."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6213_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Ой-ой!"},
  Voice_6215_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6216_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "Сжульничать!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Ой, извините, в следующий раз обязательно будет!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Я слышу, как кто-то кричит моё имя, Агриппа, Агриппа, Агриппина.."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6219_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Я вижу... Он поднимается из тьмы колодца, бесчисленные глаза появляются на мясистых шарах. Они смотрят на меня, зовут меня... бог лабиринта."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6220_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "У меня очень сильное желание наблюдать за дуэлью... Если это произойдет в лабиринте, то будет ещё лучше."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6221_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Контракт... да, я хочу заключить с тобой контракт, контракт господина и слуги, который никогда не потеряет силу"
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6222_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Хм... неплохо. Давай ещё одну точку, мне нужно накормить паучат."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6223_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Какая грязь, отвратительно! Ахх—— Прекратите! Умоляю вас! Не надо заставлять меня видеть это, и не надо упоминать об этом в моем присутствии.."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Моё прошлое было спокойным и предсказуемым, словно воды экваториальных морей, и в нём не было ничего достойного упоминания."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6225_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Мм...? Мамочка, обними меня... Мм, так тепло.."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Звёздная пыль.."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Ой, ты заблудился?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "Бесполезный."
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "Каждый раз, когда я вспоминаю, как предатели на коленях плакали и просили пощады, я испытываю чувство облегчения, и пламя в моем сердце словно ослабевает."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Капитан забрал меня из дома и возложил на меня миссию корабельной святой. С тех пор смысл моей жизни больше не зависит от меня. Мне сказали, что хотя бы в этой Часть 2 жизни как пробуждающее тело, я должна жить, следуя своим желаниям... Ты поможешь мне? Помоги мне обрести Эгоизм, помоги мне найти мои желания."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6231_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Агриппа. У меня нет ничего тебе сказать — если решишься добровольно стать гладиатором под моим началом, то это будет другое дело."
  },
  Voice_6232_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6233_AwakerVoiceContent = {
    Text = "Тави... она гораздо опаснее, чем мы думаем. Если я когда-нибудь не смогу быть рядом, ты хочешь быть крайне осторожен с ней."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Разговоры · О Тави"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Этим дедуктивным методом... интерпретировать мир!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "Этим дедуктивным методом... интерпретировать мир!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Мигайте вовсю!"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "В меру своих сил."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "В меру своих сил."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Так и Гниение."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Так и Гниение."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Улыбка и вежливость — это доспех, который помогает мне и другим людям поддерживать дистанцию и избегать скучных конфликтов. Что касается моей настоящей стороны... я не против показать её вам."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6242_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Мои мысли накапливаются, превращаясь в белый известняк, а затем смываются, становясь красивыми кораллами. Они сливаются со мной, внутри них бьётся мой пульс... Согласны послушать?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6243_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "Вдохновение похоже на пузырьки, поднимающиеся в морской воде: при легком касании они исчезают без следа. А у вас так же?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6244_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Война, грабежи, слава и богатство — всё это желания людей. Смиренный скульптор не интересуется тем, за чем гоняются люди, она желает быть только рабом красоты."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6245_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Прекрасная жизнь заключается в увлечении. Иногда не следует слишком сильно давить на себя."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6246_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Небольшая царапина.."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6249_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "Проклятие!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "Феномен растворения приносит различные аномалии и катастрофы. Возможно, именно из-за них моя страна и оказалась погружённой в глубокое море.."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Пей!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Йя~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Величие гиганта."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Попробуй это!"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Неизбежное Жертвенный ритуал."
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Неплохо, в этом и заключается честь воина."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Ты, как смеешь впустить такую женщину! Объявляю запретную зону для этой девушки! Не позволяй ей приближаться ко мне на пятьдесят шагов!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Болтовня · О Мириам"
  },
  Voice_6259_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Мириам\" будет разблокировано"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Почему хочу стать сильнее? В моём племени слабых раздевают догола, сбривают волосы и подвергают самому отвратительному унижению, которое только можно вообразить — цена слабости не каждому по силам."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6260_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Божественная Матушка удачи, благослови меня!"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "В конце концов... Огромная Огромная сила человека действительно имеет предел.."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Тело немного расслабилось."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6263_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Пусть моя любовь станет ещё глубже, это и есть проявление вашего желания?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6264_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Действуй по своему усмотрению!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "Ох, это непростительно.."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Давай, смелее!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6272_AwakerVoiceContent = {
    Text = "Биу——"
  },
  Voice_6272_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "Продолжай в том же духе, твои итоговые оценки внушают надежду."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Слышал, что пришёл вор из трущоб и привёл с собой толстую крысу? Ха-ха-ха-ха... Посмотрим, как я исполню долг перед небесами и избавлю хозяина от беды!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_6274_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Вот, глубокий вдох —"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "Интересно, твой рост в бою превосходит мои ожидания. Возможно, со временем ты станешь следующим... Как странно... Через время я всё ещё питаю надежду на такое слабое существо, как ты."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6276_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Может быть, сейчас самое время сказать это, слушай внимательно.\nКосмическое чудовище Ротань официально приглашает тебя на решающую битву... Конечно, пока ты не достигнешь своего пика, я буду защищать твою безопасность. Я не допущу, чтобы избранный Противник погиб во Часть 2 раз."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6277_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Хм... Не понимаю, как Рамона могла признать тебя своим напарником. Я чувствую в тебе запах сильного бойца, но до уровня моего противника тебе ещё очень далеко."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6278_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Да, именно так, смотрите на меня с поклонением. Я — древнейшее создание планеты, и мне подобает уважение со стороны малых существ. Я страж этой планеты уже миллионы лет, и требовать за это яркого и захватывающего противостояния в качестве награды — разве это слишком?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6279_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Ха-а, у меня нет сил играть в детские игры. Если понимаешь, что к чему, то найди уголок и сиди там смирно."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6280_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Души, не нашедшие защиты, я дарю вам последний покой."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6282_AwakerVoiceContent = {
    Text = "Настороженность."
  },
  Voice_6282_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6283_AwakerVoiceContent = {
    Text = "Предупреждение."
  },
  Voice_6283_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Что-то плачет в моей голове.."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6284_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Кажется, мои мысли окутаны тонкой белой дымкой."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6285_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Звук становится всё громче, белая вуаль становится всё плотнее."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6286_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Это звук движения часовой стрелки?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6287_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Когда прозвенит колокол, я ещё буду здесь?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6288_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Этих жалких средств... хм, несведущий в своих возможностях человек, как ты мог подумать, что я так легко позволю себя Связывание?"
  },
  Voice_6289_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6290_AwakerVoiceContent = {
    Text = "Пожалуйста... вы не видели мою сестру, Дженкинс? Это агрессивная девочка с мышью... Я бы не перепутала."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_6290_UnlockDesc = {
    Text = "После прохождения главы 2 в «Расследовательской операции» разблокируется"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Благодарю за вашу благосклонность."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "Готово."
  },
  Voice_6293_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "С нетерпением ждите."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Пою для вас."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Новый Страж? Используйте все свои силы, позвольте мне увидеть, достойны ли вы стать моим противником."
  },
  Voice_6296_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6297_AwakerVoiceContent = {
    Text = "Хотя я и пацифист, но «они» явно так не думают.."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ха!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6299_AwakerVoiceContent = {
    Text = "Отступить!"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Как ты смеешь так унижать меня.."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Готово! Магическое шоу Касии начинается! Не отводите глаз и не пропустите самые захватывающие моменты. It's showtime!"
  },
  Voice_6301_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ха!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "Я получил твой расписание от Сильвии, это слишком сурово для новичка. Я понимаю, что вы делаете правильные вещи, но возложение тяжёлой ноши на новобранцев может создать ненужные проблемы для команды. \n Ты говоришь, что не новичок? Нет, я вижу это по твоим глазам, ты ещё не пережил многих вещей."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6304_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Я ненавижу свою недобросовестность... Ах! Вам не нужно меня утешать! То прошлое уже стало опорой для моего роста, я уже стал вашей помощью, не так ли?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Я не могу поладить с тем мужчиной. В жизни разве так много грехов и наказаний? Важнее наслаждаться моментом, не так ли?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Болтовня · О Сальвадоре"
  },
  Voice_6306_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Сальвадор\" разблокируется"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Время мало, выдвигаемся."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Ненавижу свечи, которые легко гаснут, ненавижу черный хлеб, ненавижу нитки на подоле юбки... Никаких причин, разве это не само собой разумеющееся?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Раз уж вы нарекли меня Святой Девой, то вам следует покориться!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "Раз уж вы нарекли меня Святой Девой, то вам следует покориться!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "Пойте."
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "«Гардероб леди» и «Справочник мастерицы» — замечательное чтиво… Даже если не можешь себе позволить, просто полюбоваться красивыми платьями — уже приятно."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Странно, мне всегда сложно запоминать что-то другое, но я запомнил тебя всего за несколько дней... Что? Уже прошло три месяца? Извини, я снова забыл."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Попробуйте."
  },
  Voice_6314_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "Продолжить улучшать осанку."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Потренируйтесь ещё двадцать раз в технике вращения с хлыстом."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Мои действия достаточно точны?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Пожалуйста!"
  },
  Voice_6319_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "Быстро уводи Браун!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Встать на колени перед троном."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Встать на колени перед троном."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Человеческие выражения лица при столкновении с желаниями всегда удивляют меня. К сожалению, люди всё ещё слишком хрупкие, слишком ничтожные... Только это вызывает дискомфорт, как будто кошка царапает сердце."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Из её памяти я увидел многое о «Раствориться»... Но каждый раз, когда хочу рассказать тебе об этом, моё сознание внезапно прерывается, и я боюсь, что это её проделки."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Такова аннигиляция, разве это плохо?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Квалифицированный Сквайр должен быть слабым и пустоголовым — мне нравятся смиренные овечки."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "То, что мы встретились, должно быть, обещание богов страдальцам — ты являешься бледным пламенем, устраняющим бедствия, а я буду твоей опорой и сопровождать тебя."
  },
  Voice_6327_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6328_AwakerVoiceContent = {
    Text = "Вот и всё!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Пробовали влить растворенную лаву в тело? Черная жидкость словно ядовитая змея, обвивает сердце, и затем... бах! Ваше тело взрывается теплой жижей. Омерзительно, но крайне эффективно."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Хм, убежище для слабаков, ищущих поддержки Близкий Близкий друг в друге."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Периодически девушка на мотоцикле помогает мне с обслуживанием протеза. Однако, не слишком ли часто она проводит Ежедневное обслуживание в последнее время?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Беседа · О Нодире"
  },
  Voice_6331_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Нодира\" будет разблокировано"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Наше отношение? Разве это нужно спрашивать? Это именно то, что ты себе представляешь."
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Не моя специализированная область, но если тебе так хочется."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Твои черные круги под глазами снова стали заметнее... Зачем так изнурять себя работой? Ты должен научиться, как и я, наслаждаться часами досуга."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6334_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Подождите, без моего разрешения.."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6335_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Хорошо... Начало приближаться к первоначальному виду."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6336_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Это Огромная Огромная сила, способная противостоять «Зелёной коррупции»... Ты коснулся того, до чего не следовало дотрагиваться. Я уже не смогу тебя отпустить."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6337_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Шш... утренний Погоня за светом в долине реки, наверное, ты видишь это впервые? Это награда за твою Верность."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6338_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Дарую тебе этот «@1@2Апокалипсис». Поможет пробудить разум… или быстро уснуть."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6339_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "В мире всё ещё слишком шумно, если бы ты мог найти для меня тихий уголок в академии, это было бы прекрасно... Нет, мне не нужен камин. Только через аскезу боги услышат мои молитвы.."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Это воск или ещё мёд капает с этого тела, лизни — и узнаешь."
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6341_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Рада познакомиться... Меня зовут Ай Джис... Пожалуйста, просто считайте, что меня здесь нет!"
  },
  Voice_6342_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6343_AwakerVoiceContent = {
    Text = "Пока я остаюсь «Рамона», мы всё ещё партнёры, верно?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Та барышня с тёмными кругами под глазами однажды спрашивала у меня о способе «вечно жить под солнцем»… Действительно, достаточно лишь перемещаться между двумя мирами. Но она ни за что не соглашается ступить в пространственный тоннель… Вот незадача."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Разговоры · О Венкоре"
  },
  Voice_6344_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Венкор\" будет разблокировано"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Добро пожаловать в мой рай! Готовы ли вы Принять порку?"
  },
  Voice_6345_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6346_AwakerVoiceContent = {
    Text = "Раз Он признал тебя, я не буду считать тебя врагом."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Что ты имеешь в виду, что я взял? Не обвиняй невиновного! Когда её старые болты пропали, я был — Браун, нет!... Хе-хе, ты просто считай, что ничего не видел, ладно?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Беседа · О Нодире"
  },
  Voice_6347_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Нодира\" будет разблокировано"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Приключения действительно так же увлекательны, как в историях! Та история... Какая же это была?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "......гык. Ах, извините, случайно снова поглотил слишком много энергии."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "После того, как я вошёл в человеческое тело, я потерял связь со всеми своими сородичами. Я боюсь, что другие не смогли убежать от демонов, боюсь, что я уже последний представитель своего вида... Спасите меня, Страж, позвольте мне остаться рядом с вами, не надо оставлять меня в темноте.."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6350_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Когда планета уничтожалась, я отказался от тела и перенес сознание в человеческое тело… Но черный демон преследовал меня, связывая дух и не давая мне освободиться! Он хочет втянуть весь мир в черную трясину!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6351_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Пожалуйста, Страж... Лишь бы я мог оставаться на позиционировании и не покидал его, кроме как войти в Мрак и встретиться с этим, этим чёрным... Я готов на всё! Я не могу покинуть позиционирование, скоро я смогу определить координаты обломков родной планеты! Всего двенадцать миллиардов операций осталось!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6352_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Можешь использовать свою долю снабжения, чтобы Требование две упаковки кофеиновых добавок? ... Я не могу спать, зачем спать? Не надо спать! Когда закрываешь глаза, всё становится тёмным... тёмным.."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6353_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Вау! Не подходи ко мне! Сначала, сначала докажи, что ты не Сквайр тьмы! Да, Сквайр, только сними одежду и позволь мне проверить, нет ли на тебе этой мерзкой чёрной слизи... И я смогу подтвердить, являешься ли ты демоном или нет"
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6354_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Не спрашивай, не спрашивай...! Ты ведь знаешь, что я больше всего ненавижу и боюсь! Тьма, бесконечная тьма!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Способ излечения от растворения? Такой вещи нигде не существует.\nТы спрашиваешь, как мне удается не заразиться? Хех... Достаточно просто оставаться «не быть замеченным»."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Спасибо, Носитель!"
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Они тоже очень счастливы."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Лили, выросла."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Давить?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Как ты смог его призвать! Этот бесполезный соня! Сам себя загубил, ни о чём не думает... Я так разочарован, ведь я возлагал на него большие надежды! Пойдём! Не хочу больше видеть этого парня!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Болтовня · О Тулу"
  },
  Voice_6361_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Отвратительно!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Не раздражай!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "В следующий раз давайте вместе сходим посмотреть на море. Можно отправиться в Февр, я буду вашим гидом, или куда-нибудь ещё – хоть на край света, я мечтаю показать вам все эти места."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6364_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "Море имеет свой язык.\n...Вот так, я иногда могу поболтать с маленькими рыбками в бассейне о темах родного дома. Если вам интересно, я могу помочь вам перевести, согласны?"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6365_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Я часто до жути счастлива быть спасённой вами... Пожалуйста, скажите мне, это не сновидение, и вы не исчезнете беззвучно в море, Правда?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6366_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Можно ли назвать это «счастьем»? Раньше... я никогда не мечтал об этом."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6367_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Тело теплое, словно окружено нежным теплом моря, это невероятно."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6368_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Это Его срез? Впечатляет, действительно величественный и царственный вид."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Болтовня · О Тулу"
  },
  Voice_6369_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Не надо, не надо продолжать... Оно найдет меня, оно найдет меня!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Так можно будет оставаться в сознании всё время."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Всё пропало, всё пропало, всё пропало... Так нас обязательно обнаружат.."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Мы выиграли, ты счастливый? Что за чувство «счастливый»?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Любимые вещи? Мне нравится колыбельная Тинкерта... Конечно, ты поёшь очень красиво!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Он хороший воин, я когда-то считал его «товарищем»... Что, как ты говоришь, у меня есть проблема с определением «товарища»? Хотелось бы узнать подробнее."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Голиаф"
  },
  Voice_6375_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Голиаф\" разблокируется"
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "Метеор.."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6379_AwakerVoiceContent = {Text = "А——"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Неистощимая Огромная Огромная сила, наполняющая всё тело.."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6381_AwakerVoiceContent = {Text = "Лети!"},
  Voice_6381_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Неплохо, ты оказался намного полезнее, чем выглядишь."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Двадцать, двадцать один, Двадцать четыре... ой, погоди, до какого числа я досчитал? один, два, три.."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6383_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Я наконец выяснил, сколько материалов было раньше, так что теперь смогу быстрее завершить Ежедневное обслуживание — Что это? Хо Фэн это взялось?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6384_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Последние ремонтные работы проходят быстрее, спасибо за твою помощь, так мы скоро сможем отправиться на приключения."
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6385_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Кажется, я Начало что-то помнить... Вчера ты случайно не передал мне гаечный ключ номер 7?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6386_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Вперёд, к победе! Неизвестно приключения, таинственный мир, я пришёл!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6387_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6388_AwakerVoiceContent = {
    Text = "Бум——"
  },
  Voice_6388_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "Не обманывай себя, оковы разума также являются оковами, и это нельзя назвать справедливостью."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Таким образом, граница между мной и пробуждающим телом становится ещё более размытой. Следи за мной хорошенько, ладно?"
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6390_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Пойдём, спасать мир ."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6391_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Ощущение такое, будто прочитал «Происхождение видов» на одном дыхании — так же освежает."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6392_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Стал сильнее, может быть, на следующей задаче дадите мне возможность действовать самостоятельно?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6393_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Кроме боя, кажется, что память и логические способности не улучшились значимо, видимо, всё-таки нужно полагаться на собственное мышление."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6394_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Я хочу, чтобы они тоже попробовали, что значит, когда жизнь переворачивается с ног на голову, не остается ничего и все топчут тебя."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6395_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "Мое унижение, всё, что я потерял... Я хочу, чтобы все люди заплатили."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6396_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Какая сладкая Досаждение, если сопроводить её кровью врага, это, несомненно, самое вкусное блюдо в мире."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6397_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Ах! Не надо внезапно подходить сзади!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Пылающее пламя горит у меня в груди... Да, я никогда не забывал и не забуду."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6399_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Возгорайся, душа стихов."
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6401_AwakerVoiceContent = {
    Text = "(легкое хмыканье)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(легкое хмыканье)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(легкое хмыканье)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(легкое хмыканье)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Щекотно! Как будто Служанка щекочет подошвы ног перышком, ты *цензура* Не нарочно, да?"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6405_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Спокойной ночи, сладких снов!"
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Спокойной ночи, сладких снов!"
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Даруй тишину...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Действуйте с изяществом."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Слышите меня? Мой звук."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Слышите меня? Мой звук."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Идет дождь. Дождевая вода смывает все: испорченную еду, упрямую грязь и даже таких, как я... лишних.."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "Волны мщения никогда не утихают."
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "Кровь, омывающая всё тело!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6415_AwakerVoiceContent = {Text = "Ой!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Смотри сюда!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Я совсем не боюсь."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6418_AwakerVoiceContent = {
    Text = "Осторожно!"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Мир, не знавший горечи, не заражённый печалью, не подвергавшийся мукам болезни, не разъеденный тёмным горем——возможно, это никогда не достижимая Иллюзия, но идеал, который я всю жизнь стремлюсь достичь."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Поддайтесь великолепию Вечного Королевства!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Поддайтесь великолепию Вечного Королевства!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "Снова пришла покорно принести дары? Какая послушная."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6422_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Больно?"
  },
  Voice_6423_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6424_AwakerVoiceContent = {
    Text = "Концентрируйся."
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Тысячелетие заставило меня расслабиться."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "В тот день пламя черной зависти распространилось, словно кроваво-красные розы распустились... Все стихи превратились в Пепел в языках пламени.."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6426_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Научился новому приёму!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Будьте осторожны."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "Волшебная палочка хочет танцевать!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Мм, это знакомое пустое ощущение!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Суставы стали двигаться более плавно."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Та зловещая черная похожа на мой бесформенный меч и щит... Ах! Успокойтесь, мой господин! Мой защитный меч никогда не причинит вам вред!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "Приходи."
  },
  Voice_6433_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Еле-еле справился."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Я сделаю всё возможное."
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "Сыграем сегодня здесь?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "В подвале много воды, мягкой и холодной. поэтому тело всегда окружено водяным паром... как будто между небом и землей я единственная плоть. иногда я действительно хочу растаять в воде.\nно тогда я больше не буду существовать и не встречу тебя."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6437_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Расскажу вам один секрет... На самом деле, я ненавижу кровь. Ненавижу её цвет, ненавижу её вкус. Но я не могу без неё обойтись.\n... Я проглатываю кровь, а потом вырываю всё обратно... Я гнушаюсь собой."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6438_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Оу! Ваша кровь... пахнет медовым вином. Думаю, я единственный, кто знает этот секрет, верно?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6439_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "В моих фантазиях храбрый рыцарь вытащит меня из тёмного и закует в цепи. Он может бить меня, ругать меня, делать со мной всё, что захочет — боль станет доказательством того, что я живу. \n Вы согласны стать моим рыцарем?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6440_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Кровь течёт как река. Я принадлежу вам — это чувство никогда не было таким сильным."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6441_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Это воля Эриний!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "Острие выходит из ножен."
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "Не получается!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Очень грязно! Очень грязно!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...Ай Джис, вижу!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Ай Джис, вижу!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Чаевые, конечно, чаевые. Посмотрите на этих медлительных официантов в школьной столовой! Они даже не подготавливают шезлонги заранее. И после этого они ещё хотят каких-то дополнительных вознаграждений? Смешно!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6449_AwakerVoiceContent = {
    Text = "Чёрный."
  },
  Voice_6449_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Пусти меня наружу!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Навык: |·мания"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Не делай так..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Навык·Первый·депрессия"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Не стоит быть таким вежливым, посланник с бледным лицом. Между нами не должно быть преград, так как мы оба являемся созданием бога и вместе передвигаемся вперёд по этому пути, полному грязи и испытаний."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6452_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Конечно, я не боюсь их, этих жалких существ, страдающих от проклятия таяния. Я лишь чувствую печаль за них. Я знаю, что не могу принять на себя их страдания, но я могу дать им всё, что могу, если это может принести им немного утешения."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6453_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Хочешь помолиться со мной, бледный Искра? Чтобы помолиться за тех, кто сегодня умер в нашем бою, страждущие. Даже если они впали в безумие из-за проклятия таяния, они всё равно остаются созданиями милосердного бога, твоими и моими сёстрами и братьями. Пусть они обретут заслуженный покой."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6454_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Даже если красное пламя вызывает у меня напряжение, я снова взойду на горящий помост, чтобы быть с тобой. Не стоит переживать об этом, Белое пламя, перед теми благами, которые ты можешь принести, моя жертва не имеет значения."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6455_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Сожалею? Нет, конечно нет. Моя смерть облегчила их страдания и дала им больше времени, этого достаточно. Но... ты был честен со мной, поэтому я тоже не буду скрывать от тебя: Искра того дня ещё оставил шрам в моём сердце."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6456_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Можешь заключить со мной договор? Э-э... Давай договоримся, что, что бы ни случилось, ты всегда будешь помнить «Рамона», хорошо?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6457_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Я не жалею о выборе стать таким, как сейчас. Если бы представился ещё один шанс, я бы снова так поступил. Но, Страж, мне очень страшно... страшно, что «Рамона» не оставит никаких следов в этом мире."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6458_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Нет беспокойства, повязка на глазах не мешает мне видеть. Наоборот, так я могу не воспринимать все вокруг."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6459_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Моя Эмоция кажется незнакомой? Я ведь старался контролировать... Похоже, её присутствие становится всё сильнее."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6460_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Неразгаданные загадки, люди, которых нужно спасти, чересчур много. Я не знаю, как долго я смогу продолжать, и не могу защитить всех... Сложная задача."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6461_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Ещё собираешься делать ставки на мне? Похоже, жить так, как хочется, не так-то просто. Не волнуйся, я помогу тебе решить проблемы, но при этом немного отдохну."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6462_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Дело дошло до того, что нельзя не показать настоящие способности? Где место Обнаружение преступления? Даже если придётся сжечь все мою удачу, я обязательно верну подозреваемого в установленный срок!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6463_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Ой, ты так много для меня сделал, не могу не поделиться секретами: возможно, я самый неудачливый здесь."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6464_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Ты, кажется, не обращаешь внимания на то, что я говорю... Ладно, ладно, я ещё помогу тебе Разрыв врагов. В общем, эти когти и зубы я получил случайно, да?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6465_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Моя удача не обязательно передастся моему спутнику. Ты ведь знаешь эту фразу? «Кроличья лапка для кролика ничего не значит»"
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6466_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Хотите, чтобы в вашей душе остался Отпечаток моего присутствия?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Так сильно жаждешь моей силы?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Не смотрите на мой вид, я тоже когда-то была дамой... Я умела вышивать, читать Теннисона... Кстати, я ещё и петь умею: Она как вечная река, течёт в моей крови~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Пикман и я сотрудничаем над некоторыми интересными инсталляциями, исследуя, как через деконструкцию визуального примитивизма можно пересобрать абстрактный представительский образ... Эй, почему Орета потеряла сознание?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Об Орета"
  },
  Voice_6470_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Орета\""
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "Вы хотите, чтобы я улыбнулась?\nЛили, ты улыбаешься?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О улыбке"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Действительно свежо, я даже завела равноправную дружбу. \nТем не менее... Я прошу оставить за собой право управлять тобой, как одна точка в наших отношениях. Загляни ко мне в спальню сегодня вечером, мне еще многое нужно узнать о чувствах между людьми.."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6472_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Знаешь, где ты самая милая? Когда говоришь мне «нет». Твой носик морщится, брови слегка поднимаются... Да, прямо как сейчас."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6473_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Я люблю своих слуг. Эти милые маленькие создания, дрожащие от страха перед растворением, прячутся за моей спиной, выглядя такими трогательными. Слёзы красавицы всегда пьянят сердце. А ты, ты боишься растворения?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6474_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Страж, есть ли у тебя кто-то, кого ты ненавидишь? В качестве благодарности, я могу взять на себя его воспитание. За неделю я заставлю его измениться, и он будет послушно лизать твои пальцы ног."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6475_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Эй... ты, хотя и глуповат, но не вызываешь раздражения. С завтрашнего дня ты будешь служить мне.\nТы не хочешь...? Это не просьба, это приказ."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6476_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Давно не было такого настроения, я выйду на сцену во всеоружии и подарю вам звуковую волну, пронзающую вселенную."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6477_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Знай, это бессмысленно."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6478_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "После того, как я сорвал цветок победы, я хочу Требование одну точку награды.."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6480_AwakerVoiceContent = {Text = "А"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Удар·уныние·три"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "Тот дирижабль был тесным и узким, как металлический гроб, дрейфующий в космосе. Я ждал свою Венеру, до тех пор, пока вы не появились."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6481_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Как так?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Удар·ярость: |"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Нгх…"},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Удар·меланхолия: |"
  },
  Voice_6484_AwakerVoiceContent = {
    Text = "Больно.."
  },
  Voice_6484_AwakerVoiceTitle = {
    Text = "Удар·депрессия·два"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Небесное наказание!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Небесное наказание!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6487_AwakerVoiceContent = {
    Text = "Скучно."
  },
  Voice_6487_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Ещё могу продолжать."
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "О, нечестивец, нейтрализуйся в огненной тишине."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Будь осторожен, если засунешь руку в другую размерность, её уже не вернёшь!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Группа бесполезных, если не хотите закончить в банке как мясное пюре, в следующий раз будьте внимательнее."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Ой, капризничаешь передо мной?\nТрудно, такими темпами я не дождусь, пока Страж полностью созреет.."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Погрузись в глубокое Вдаль от берегов!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "Ненавистные вещи... Видимо, это все-таки тот, кто ещё бросает дела на полпути. При мысли о таком человеке, у меня подступает к горлу вчерашний ужин."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Бесконечные головы, позвольте мне увидеть ваш облик здесь!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "Бесконечные головы, позвольте мне увидеть ваш облик здесь!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Пей!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Пей!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Так ты доверяешь Я?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6502_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "Возвращайся."
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6504_AwakerVoiceContent = {
    Text = "Хорошо!"
  },
  Voice_6504_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Конечно, я знаю, что это другая моя сторона. Но почему она сопротивляется? Принять судьбу избранной, разве то, о чем молишься, не должно быть под рукой?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Посторонние разговоры · О «Морфи»"
  },
  Voice_6505_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Здравствуйте, меня зовут Давдейл. Я когда-то совершила обмен с одним посетителем, и тот попросил меня помочь вам. Так что, давайте расскажите мне о ваших потребностях. \n Ох... то, чего вы желаете, стоит весьма внушительную цену?"
  },
  Voice_6506_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6507_AwakerVoiceContent = {
    Text = "*тише* что ты делаешь! веришь, что я могу отрубить тебе руку!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6508_AwakerVoiceContent = {
    Text = "Ха-ха-ха-ха!"
  },
  Voice_6508_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6509_AwakerVoiceContent = {
    Text = "Ха-ха-ха-ха!"
  },
  Voice_6509_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Роза ранила палец, истекая поэзией."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "Склонившись под грузом этой тоскливой туши, стань песней скорби.."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "Смотри на меня...!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6513_AwakerVoiceContent = {Text = "М...!"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Бедствие наступает!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "Можно мне."
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = "......имя, эх, никак не могу вспомнить.\nВерно, «24», они все так меня называют... Нет! Не выходи! Ты не можешь, сейчас нельзя.."
  },
  Voice_6516_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6517_AwakerVoiceContent = {
    Text = "Направление чернильных следов.."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Всплеск.."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Я не достоин такого титула, как «Небесный голос»... Главное, чтобы вам понравилось мое пение."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Разговор · О пении"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Грязная одежда, надо переодеться до следующего мероприятия."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Оно догоняет меня, вечный Мрак, никто не может убежать.."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Каждый раз, когда я вижу тебя, я думаю о невидимых оковах, которые ты наложил на меня. Оставить тебя в живых — это уже мое максимальное Выдержка."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Сколько бы раз ни начиналось заново, я всегда буду передвигаться вперёд вместе с тобой."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Пусть любовь Божья согреет твою душу."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Мне нравится бродить. Бродить без цели. Болота, кладбища, палаты больниц, заброшенные замки... В этих местах я всегда нахожу неожиданные находки."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Почувствуйте честь, врата Вечного царства находятся здесь."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Хи-хи—— Так щекотно! Орета тоже будет щекотать в Лечение!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "«Умирающий лебедь» — номер, в котором танцовщица языком тела передаёт жажду жизни и борьбу. Разве не так же выглядят фигуры, корчащиеся в пламени?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Разрезать, разрезать, Разрыв. как те люди со мной поступали в прошлом... хехе...... хехехе!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Ты лучше не сближайся с девушкой Тайис... Нет, я не ревную, просто боюсь, что кто-то может попасться на удочку у женщины."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Разговор · О Тайис"
  },
  Voice_6530_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тайис\" разблокируется"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Спасибо."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6531_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Отлично... У тебя есть проницательный взгляд, способный распознавать людей."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6532_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "Родина Гарен очень красива! Это каменный город, расположенный на озере.\nКаждую полнолунию мы молча танцуем в пламени, совершая жертвоприношения...\nЧестно говоря, когда Гарен только пришла в университет, каждый вечер она скучала по дому и тайком плакала в постели. Но сейчас у Гарен новый дом и семья, и всё наладилось!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6533_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Ох~ Тебе всё ещё недостаточно? Приходи, дай мне время как следует обучить тебя~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Мышцы слабые, лицо измождённое, только эти глаза, как у мертвеца, и представляют какую-то ценность—— вырежем их и отдадим паукам на съедение."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Спасибо, спасибо за всё, что вы сделали для Ай Джис. Ай Джис постарается, постарается не подвести вас!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Восклицание от страха)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6538_AwakerVoiceContent = {
    Text = "Не надо!"
  },
  Voice_6538_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "Отпусти меня.."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Восклицание от страха)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "Мечевое искусство девушки Рамона сильно отличается от того, что я освоил. Если мой господин позволит, я действительно хотел бы с ней потренироваться... Конечно, конечно! Это только для самосовершенствования!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6541_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Вы спрашиваете, почему я не играю с другими детьми? Очень трудно сказать... При жизни у меня не было возможности играть, единственным моим другом была принцесса, которой я когда-то служила...ещё... Ах! Как я могла упомянуть другого правителя в присутствии своего господина, пожалуйста, простите за мою ошибку.."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6542_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Вы являетесь признанным Хранителем тайн Университета Мисаг, поэтому я предоставлю вам соответствующие права доступа."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О «Главном герое»"
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Господин, вас интересуют «Семь искусств рыцаря», которые я изучил? Превосходно! Ах... э-э... ранее я был невежлив. Я имел в виду: если вы хотите практиковаться в стрельбе верхом, то я с удовольствием стану вашим партнером по тренировкам!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6544_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Я не являюсь достойным рыцарем. Независимо от той злобной эпидемии, ещё от нападающих врагов, я не смог защитить своего прежнего господина. Теперь, когда вы доверяете такому, как я, это великая честь для меня... Клянусь честью рыцаря и этой ничтожной жизнью, я буду вечно защищать ваш путь вперёд."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6545_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Не причиняй Урон."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6547_AwakerVoiceContent = {
    Text = "Нет-нет~"
  },
  Voice_6547_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Тих!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Не убивай."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "Как приятно~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Сейчас, мы просто несмешиваемая вода и масло."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "У меня нет особых предпочтений. Если приходится выбирать, то чувство выполнения задач на выезде довольно приятное!"
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Почему, почему меня держат здесь? Хех... Не позволю тебе добиться своего, я разорву эти путы, эту тюрьму... на фрагменты!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Защитить всех."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Вы несколько, каждый раз приходите смотреть шоу магии, не устаете? Будьте послушными и сидите хорошо! Если снова побежите на сцену, я отправлю вас в другое измерение!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Разговоры · О детях"
  },
  Voice_6555_UnlockDesc = {
    Text = "Получите одно из следующих пробуждающих тел: «Ай Джис», «Дженкинс», «Лили», «Морфи», «Гарен», «Орета» для разблокировки"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Ваш Подарок я принимаю с большим уважением."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Какой ответный Подарок может соответствовать вашим усилиям?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Какая роскошь.."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Обнаружен сильный электрический ток, начинаю обслуживание механизма... Исправление, почему не произошел перегрев?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6559_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "С тех пор как прошла последняя церемония активации духа, я в состоянии спячки вижу обрывочные кадры. В них у меня есть тело из мяса и крови, как у тебя, и я проливаю слезы. Это, сон?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6560_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "После каждого ритуала в части тела груди обнаруживается высокая температура, но там нет компонентов, связанных с энергией. Вы знаете почему?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6561_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Я вижу, всё <Del:должно умереть в вечном токе> об-извините, модуль кажется — предупреждение, предупреждение, активность несознательной Эрики увеличилась, пожалуйста, уничтожьте, уничтожьте, уничтожьте... привет, чем я могу помочь?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6562_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "После тщательного анализа я пришел к выводу, что то, что я видел во время своего состояния анабиоза, не было обычным сновидением, а памятью о том, что <Del:мое жалкое тело из мяса и крови должно быть уничтожено>. Что касается того жара, который пылал, как перегрузка, это, возможно, была Эмоция, называемая «Недовольство»."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6563_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Хотите посмотреть выступление? Удобно устраивайтесь на зрительских местах!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6564_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Пламя ненависти пылает ярким пламенем, никогда не угасая."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "Воля, с которой я слился, — это шумный парень, чем больше я развиваюсь, тем четче становится звук «Него»... как гуси в Гайд-парке, довольно громко."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6567_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Я использую эту силу для поглощения предателей."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Спасибо."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Страж? До чего же смешно, этот нереалистичный сон пора бы уже закончить."
  },
  Voice_6570_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6571_AwakerVoiceContent = {
    Text = "Месть в крови, кипит.."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Двигайся, Сквайр!"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "Не тони!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Шу-шу!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Я выбросил ловушку для мышей у задней двери столовой — слишком опасно! Что, если Браун, этот неосторожный парень, наступит на неё!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Это чувство странное... Может, я скоро умру? Нет, спасите меня! Не надо!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6576_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Я хочу лампу, которая никогда не погаснет, а она сказала обменять её на «экземпляр гидры, которая летает без крыльев». Как же я найду такое невероятное существо!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Разговоры · О Давдейле"
  },
  Voice_6579_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Давдейл\" будет разблокировано"
  },
  Voice_6582_AwakerVoiceContent = {
    Text = "Опасность."
  },
  Voice_6582_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "Предупреждение."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6584_AwakerVoiceContent = {Text = "Удар."},
  Voice_6584_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "Сокровище, которое блестит как обертка от конфеты…… Ай Джис будет бережно хранить его."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Получает Урон."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Мой маленький магазин может существовать в любой размерности, в любом положении вселенной, конечно, он также может находиться здесь. К тому же, мне очень нравятся те недостаточно осторожные дети Мисаг?"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Ненавижу... зелёный перец такой невкусный."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Мои отношения с вами подобны отношениям между парусом и лодкой. Без лодки парус не должен существовать; без паруса лодке трудно отправиться в дальнее плавание. Разве не так?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "Благочестивый танцор умер, и тот, кто совершал Осквернение против искусства, тоже умер в огне с запахом дегтя. Смерть не является концом, а началом, потому что умирают только люди, танец и искусство вечны."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6590_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Спасибо за ваше понимание. Возможно, сейчас настало время примириться с моим прошлым я... Я верю, что делаю правильную вещь и не опозорил имя семьи танцоров. Я выйду на сцену, которую вы приготовили, и, как вы пожелаете, буду сиять в полную силу."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6591_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Будьте осторожны."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Ты хочешь, чтобы я поднялся на сцену и засиял там?\nЭто уже невозможно. Эти глаза поглощены ненавистью. Я могу только всё уничтожить."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6593_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Понимаешь это чувство? Вращение, вращение, вращение, безостановочно. Колено, напряжённое до предела, болит, чёрная кровь сочится из пальцев ног, промачивая балетные туфли, но я не останавливаюсь ни на мгновение. Всё потому, что я не желаю принять судьбу игрушки.."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6594_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Я сжёг не искусную танцовщицу при дворе, не элегантного руководителя балетной сцены, не благородного знатока высокого и прекрасного, а продажного похотливого ничтожества, беспринципного льстеца, погрязшего в греховных желаниях... Ты ведь поймёшь меня, Правда?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6595_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Мне не нравятся люди с липкими щупальцами, и мне не нравятся глубины океана... Не делай понимающую эмоцию! Я ведь не ребёнок, который боится родителей!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6596_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Ваша щедрость вызывает глубокую благодарность.."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Исчезни!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Исчезни!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Быстро уводи Браун!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "Не надо..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "защита·уныние"
  },
  Voice_6602_AwakerVoiceContent = {
    Text = "Убирайся!"
  },
  Voice_6602_AwakerVoiceTitle = {
    Text = "защита·бешенство"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Кто такая Рея? О, та женщина, которая просила меня её ударить. хаха, интересно... Здесь не так скучно, как я думал."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Разговоры · О Рея"
  },
  Voice_6603_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Рея\""
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Маленький холм и Закат часто заставляют меня вспоминать дни в Кливленде… Кливленд, я даже не верю, что помню это имя, место, где я получил эти шрамы…"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Пустые разговоры · О закате"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "А... звёзды... вот так и угаснут.."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Без сомнения, это люди. Есть ли более грязные существа, чем люди?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "Сейчас!"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6608_AwakerVoiceContent = {
    Text = "Привет!"
  },
  Voice_6608_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "Растворение? Мм... да! Мороженое действительно тает! Но если поделиться с друзьями, можно успеть съесть его до того, как оно полностью превратится в крем!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Я буду вашу защиту с помощью этой силы."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6610_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Извините, товары, проданные в нашем магазине, не подлежат возврату или обмену. Если хочешь погрузиться в глубокое море, действительно нужно подводную лодку, да?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Разговоры · О Кекесе"
  },
  Voice_6611_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Кекес\" разблокирует"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Лучшая сцена! Ученики и преподаватели университета Мисаг могут понять, что я демонстрирую настоящую магию! Это и есть те, кто понимает мага, верно?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "Порядок Вселенной, здесь изменяется; будущее уничтожения, это Твёрдая Твёрдая вера магии!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6613_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Можно ли оставить Ай Джис здесь ещё на некоторое время? Я буду вести себя тихо, не издавать ни звука и постараюсь вас не беспокоить.."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6614_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Через разум человека... раскрой суть мира!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "В моих сновидениях часто раздается звук прилива, этот звук становится всё дальше и дальше. Я знаю, возможно, я останусь здесь навсегда, человече."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Разговор · О глубоком море"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Больше памяти, больше эмоций, больше снов ——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6617_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Начало меняться!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Не надо мигать!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Когда Он родится... я больше не буду терпеть это унижение.."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Выбери меня, выбери меня! Где есть вечеринка, там есть Гарен!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Хм? Вы интересуетесь мной? Полагаю... вы уже готовы заплатить цену, а?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Никогда не прощать, никогда не прощать...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Всё ещё воспевают цвета, нисходящие со звёзд."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "Пой, пой!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Любить Матушка!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6627_AwakerVoiceContent = {
    Text = "Приходи."
  },
  Voice_6627_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Будьте осторожны."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Пробуждающие тела могут есть из любопытства, но пища не является необходимой для нашего существования. Поэтому нет нужды звать меня на каждый послеобеденный чай. Потребление сахара лишь ускорит износ сферических суставов этого тела."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О чае после обеда"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Пожалуйста, оставьте в покое хозяина, Гарен... Гарен готова к любой расправе!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Всё это Лили может съесть?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6633_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Ненавижу? Можно сказать, Ай Джис больше всего ненавидит то, что постоянно чувствует себя бессильной... Но если я так скажу, Дженкинс будет очень-очень злиться.."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Превратись в Пепел."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Превратись в Пепел."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Хорошая работа, Страж. Говори, кого на этот раз ты хочешь, чтобы я убил?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6637_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Растворение — это причина создания этой академии и также причина нашей встречи. Чтобы спасти Искра человечества из рук растворения, давай, приложим все усилия, напарник."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Я могу почувствовать враждебность той девушки, наверное, моя любовь к вам вызвала у неё зависть... Видите, даже пасть большого кита от зависти широко раскрыта."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Ротань"
  },
  Voice_6639_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Ротань\" разблокируется"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Носитель, Носитель! Гарен сегодня увидела в универмаге Харолл супер——красивую брошь камио! Носитель, не могли бы вы купить её для Гарен? Это моя самая заветная просьба!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Я буду твоим ориентиром в темноте, но этот срок временный."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Матушка, очень больно, Матушка.."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Сдавайся! Победа уже в моих руках!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Сдавайся! Победа уже в моих руках!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "Растворение... У меня ограниченные возможности для понимания, я не могу разобраться в таких крайне сложных заболеваниях... Если понадобится починить механическое устройство, обращайтесь ко мне!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "О! Орета была найдена! В качестве наказания за проигрыш, ты можешь попросить у Ореты исполнить одно желание — но только не отправляй её на уроки, пожалуйста"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "... для Его возвращения устранить препятствия"
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "В один прекрасный день дядя Орн встретит меня и вернёт в подводный дом. До этого момента я не против временно дружить с тобой."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6648_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "«В нашей семье течёт великая кровь, избранный насладится вечным покоем в глубоком море.»\n Не ожидал, что, покинув Океан и прибыв в академию, смогу ощутить этот покой. Ты не такой, как те, кто меня обижал, и я не позволю другим тебя обижать."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6649_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Сверхтвердые специальные материалы!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "Находиться в этой оболочке, смешанной с человеческими элементами, вызывает у меня отвращение. Чуть было не освободился от прошлого, и теперь вот, приходится снова вспоминать.."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6651_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Я знаю, потомок великого рода снова стал слугой человека. Но даже не пытайся меня подчинить."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6652_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Хм, ты, слабый человек, действительно обладаешь некоторыми талантами в области командования, но это низкокачественное тело не позволяет мне раскрыть свой полный потенциал."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6653_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Тело становится всё горячее."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Убегай... нужно бежать отсюда!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "Убегай... нужно бежать отсюда!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Спасибо за ваши усилия, тогда позвольте мне дать вам заслуженную награду."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Ничего страшного."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(приглушенный стон боли)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "Человек, ты слаб, но твоя Твёрдая Твёрдая вера тронула меня. Я готов стать твоим оружием, вместе создадим большой переполох!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6660_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Это мой салон."
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "Академия равных возможностей... Не знаю, какие глупые мечты вы лелеете. Даже если вы не совершили никаких ошибок, они всё равно будут топтать вас ногами. Я знаю это чувство."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Это корень всех нечистот.."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Вспышка безумия · меланхолия"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Я был наказан за то, что не смог защитить членов экипажа. Они сказали, что из-за моей халатности исчезнувшие Члены экипажа никогда не смогут вернуться к своим семьям... Так вот что такое Раствориться?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Подошёл ближе к моему господину.."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Почему? Почему вы... не хотите Очнувшись?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Я Орла с Западного острова... У меня есть псевдоним, но я обещала не раскрывать его никому. Простите, пожалуйста, но зовите меня просто Орла."
  },
  Voice_6669_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6670_AwakerVoiceContent = {
    Text = "Я противлюсь всем несправедливым поступкам, и самым серьезным из них является предательство. В армии, если нельзя доверить спину товарищу, весь Отряд превращается в разрозненный Отряд."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Почему ты выглядишь таким черным и в то же время таким ярким?.. Нет, ничего, просто считай, что я несу чушь."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "(вопль боли)"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(упорный стон)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Что?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Мне нравится жизнь, мне нравится Погоня за светом. Хочу, чтобы Фейнт вышел из своей закрытой оболочки и воспринял этот мир всеми своими чувствами."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Я невидим!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Нужно ли продолжать работы по обслуживанию?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Подготовка запчастей завершена."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "У человека может возникнуть предательство, но инструмент всегда остаётся верным. Если использовать правильно, то Раствориться тоже может стать инструментом мести."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Тысячелетнее затаивание, этот момент наконец настал...... Я и есть единственный владыка филистимлян!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_6680_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Тот, кто только что прошёл мимо, это Гибрид глубокого моря? Ух... Взгляните на эту прямую спину. Этой ночью я заставлю его пасть на колени."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Разговоры · О Кекесе"
  },
  Voice_6681_UnlockDesc = {
    Text = "Получение пробуждающего тела \"Кекес\" разблокирует"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Огромная Огромная сила постепенно возвращается в руки... Следующий шаг, захватить мою Независимый!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6682_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Ещё неплохо, и теперь мы на шаг ближе к тому, чтобы сорвать лицемерную вуаль с этой женщины."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_6683_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Спокойно спокойно спокойно.."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Не стесняйтесь. Мой порог боли может быть намного выше, чем вы можете себе представить."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6685_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Скажу тебе, красивые, но глупые вещи - лучшие. Жаль, что здесь слишком много умных, но бесполезных голов."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Используя реакцию ядерного синтеза красного гиганта и энергию, высвобождаемую при коллапсе звезды, можно запустить вечный двигатель и зажечь вечную лампу... Эй? Ты говоришь, что здесь нет условий для создания вечного двигателя и нет красного гиганта? Хм.."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Кровь врага ещё не истекла."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Отдай их... все мне!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "Отдай их... все мне!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "Пришло время отправляться на поле боя!"
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Пришло время!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Когда я сплю, изливающиеся сновидения вызывают кипение духов. Поэтому, не надо приближаться ко мне, когда я крепко сплю, и тем более не надо пробуждение меня без причины."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О спячке"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Пришло время!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Хотя Герберт и является очень страшным человеком, его кошки очень спокойные... нет, точнее говоря, это две кошки?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Герберте"
  },
  Voice_6695_UnlockDesc = {
    Text = "После прохождения главы 2 в «Расследовательской операции» разблокируется"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Та женщина по имени Морфи одета слишком вызывающе... Нет, Гарен не может проиграть ей!\nИли, может, просто убить её.."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Разговоры · О Морфи"
  },
  Voice_6696_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ой~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "Комфортно ли вам?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Когда мы заключили соглашение с Университетом Мисаг, было ясно сказано, что меня не будут отправлять в бой…"
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6699_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Не слишком радуйся. Иногда между возвышенным и низким всего шаг от."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6700_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Фалост приветствует тебя. Призывая меня сюда, думаю, ты уже готов к плаванию."
  },
  Voice_6701_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_6702_AwakerVoiceContent = {
    Text = "Уху — так устала, можно уже пойти играть!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Аа... Его сияние так жарко и ярко, его нельзя игнорировать, это Слепой фанатизм затмил мои чувства... Нет, я не могу найти никаких оправданий своей глупости.."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Болтовня · О Тулу"
  },
  Voice_6703_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тулу\" будет разблокировано"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Звёзды в сновидении спячки, идите куда следует, указывая путь к божественной стране!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "Не кажется ли тебе, что толкать всё к завершению, останавливать ход законов мира — это очень интересно?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6707_AwakerVoiceContent = {Text = "Пей!"},
  Voice_6707_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "Весело!"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Введите боевую команду."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "В дни, когда я блуждал между звёзд, мне не раз снился этот день... Благодарю вас, что помогли мне воссоединиться с Тинкерт."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Тинкерт"
  },
  Voice_6710_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тинкерт\"разблокируется"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "Университет Мисаг — отличное место, особенно подпольное казино, которое открывается каждую неделю...\nЭй, вы действительно не знали об этом? Ой, кажется, проговорилась.."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "«Сопротивление растворению кризиса», ха, человеческая гордыня, до смешного нелепо."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Разговоры · О университете Мисаг"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "В конце концов, человек — это всего лишь поверхностное животное. Достаточно нескольких слов, малейшего намёка, чтобы спровоцировать взаимную борьбу... Вздох... этого явно недостаточно, чтобы взбодриться."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Разговоры · О людях"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Может быть, считать тебя обычным человеком было моей узколобостью и предвзятостью. Мне очень интересно, как ты, не имеющий веры, удерживаешь свою крепость? Это не вопрос Святой Матери Моря, а вопрос Мириам. Ты можешь... ответить на этот вопрос?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6714_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Такой особенный, как ты, разве не устаёшь от мелких и суетных мирских дел? Я искренне верю, что только вечная страна станет твоим истинным прибежищем. Ты будешь ходить по земле богов, наслаждаться купанием в священных источниках, пустить корни в обширной плодородной земле... Присоединяйся к моему святому пути и вместе со мной вознесёмся над мирской суетой. В тот момент мы вместе встанем рядом с троном, разделяя радость от перелить божественную страну.."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_6715_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Мы с тобой — ползущие по земле слабые люди, но тот святой не такой. Он является исполнителем воли, воплощением божества на земле. Его наставления подобны пробуждающим словам богов, ведущим цивилизацию к бессмертию... Я не надеюсь, что ты сейчас сможешь понять веру в него, но однажды ты преклонишься перед его троном."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6716_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Блаженны призванные, разве ты не считаешь так? Они получили божественную силу и обрели более долгую жизнь. Когда Царство Бога снова прибудет, и Его воля будет исполняться на земле, они станут славными последователями. Разве это не великое счастье и благословение для слабых людей?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6717_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "Радость, омываемая божественным светом, безверные, такие как ты, не могут понять... Да простит тебя мой бог, прости за невежество и неуважение."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6718_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Быстро и решительно, Страж."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6720_AwakerVoiceContent = {
    Text = "Эй-хей ——"
  },
  Voice_6720_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_6720_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Умри, спартанское отродье."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Мисс Дора сказала, что я могу временно избежать Раствориться, отказавшись от своей физической оболочки... Не могу, не могу, не могу... Во время операции я потеряю сознание, и тьма проникнет внутрь.."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О дора"
  },
  Voice_6722_UnlockDesc = {
    Text = "После получения пробуждающего тела \"дора\" будет разблокировано"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Хм... Что? Хочешь обрести судьбу аннигиляции?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Носитель всё ещё страдает от бессонницы? Гарен приготовила для вас снотворное Добби~! Хотя дозировка немного превышена, но хороший сон важнее всего!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_6724_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Тогда мы пили Прекрасное Прекрасное вино, пели песни, и вдруг превратились в монстр! Но ничего, зелёная кожа тоже довольно интересна!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_6725_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Мечта Гарен? Эм... купить красивую жемчужную цепочку, надеть её на бал и стать ярчайшей звездой!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_6726_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Желаемая материя Тиффанийезод, она также искала свой Средства выживания. Перед неизвестно никто не может судить о благородстве или низости средств."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Пустые разговоры — О субстанции желания"
  },
  Voice_67276_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тайис\" разблокируется"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Пройдя через Серебряный Ключ, достигните Его Трона."
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Не подведите его учение и память."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Протираем слева, протираем справа, пыль и заботы исчезают ——"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_6727_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Я не здесь."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Фрагмент бесконечного пространственно-временного континуума прибыл в моем духовном сознании."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Я полностью понимаю ситуацию."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Всё находится в пустоте."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Ты уже зашел очень глубоко и далеко. Вскоре ты коснешься необычного чуда. Надеюсь, к тому времени ты сохранишь текущую рассудительность и спокойствие."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_67284_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "«Игнорант». Нет, усердное стремление к познанию по сути не является игнорантизмом; истинные невежды живут в тумане, не в силах осознать даже то, чего они не знают."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Я покажу тебе моё сновидение. Всё странное и хаос, что ты увидишь во сне, ближе к истинной сути мира, чем твоя воспринимаемая реальность."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_67286_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Это мой совет тебе: не надо торопиться. Когда ты чувствуешь усталость, сразу прекращай думать, сохранить силы и энергию. Иначе ты навсегда потеряешься в сновидениях."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_67287_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "Космический цикл не прекращается."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "Между нами синхронизация не требует столь долгой притирки, однако, чтобы защитить твой интеллект от иллюзий, я буду продвигаться постепенно."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_67289_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Растворение... Я тоже случайно брался за дело, связанное с этим, но как бы это сказать, я считаю, что исчезновение — это вполне естественная вещь. В конечном итоге все мы когда-нибудь исчезнем."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Первая Ворота. Бесконечная Вселенная родилась из точки."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_67290_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "Вторые врата. Точки образуют линию, уходящую к бесконечным полюсам."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_67291_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Четвёртая Ворота. Вечный прототип застыл в пространстве одной из размерностей."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_67292_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Третья Ворота. Плоскость здесь выступает как символ ограниченного и частичного восприятия."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_67293_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Ворота предела. Ссылка с бесчисленными вселенными в конечной пустоте, Пересечение Врат предела откроет перед тобой тайну мира."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_67294_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "Пятая Ворота. Изменения во времени — это лишь твоя Иллюзия, в этом мире никогда не было начала, и естественно, нет конца."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_67295_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Я должен был быть лишь твоим откровением, ведущим тебя на этот путь, затем погрузиться в спячку в иллюзорном пруду. Теперь ты мое связующее звено, и связь между нами стала настолько прочной, что её уже невозможно Разрыв.."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Хочешь подтвердить что-то? Увы, чувства и разум этого тела слишком ограничены и скованы. Если бы ты и я встретились в абисс, я смог бы показать тебе намного больше.."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Она также является одним из моих фрагментов, прибывших из другой размерности, из мира, который уже навсегда погиб в результате аннигиляции. К сожалению, хотя она освоила способ отката времени, ей не удалось постичь истинную суть, выходящую за пределы пространства и времени, и теперь она снова и снова тонет в страданиях. Это моя ошибка."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Разговоры · О кольце Рамоны"
  },
  Voice_67298_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Кольцевая · Рамона\"разблокируется"
  },
  Voice_67299_AwakerVoiceContent = {
    Text = "Я знаю."
  },
  Voice_67299_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "Так сильно беспокоишься о внешности этого тела? Пожалуйста, не надо думать лишнего. Когда я родилась, у меня было человеческое лицо."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "Я вижу."
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "Как это ничтожно."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Сохраняйте рассудок."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Прямая ссылка с плазмой повредит твой интеллект... Однако, раз ты настаиваешь, я обязательно откликнусь на твой призыв."
  },
  Voice_67303_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_67304_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Тот ребёнок из-за фрагментов моего сознания уже перенёс слишком многое, что не предназначалось для него. К счастью, его душа всё ещё чиста, словно струящееся серебро.."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Рамона"
  },
  Voice_67305_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Рамона\" функция будет разблокирована"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Войдите в Его сны, проникайте в тайны запретного космоса."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Ммм."},
  Voice_67307_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "Ворота предела открыты для тебя. Прими мир мертвой тишины за ними."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_67308_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Моя цель в создании этой школы заключалась в том, чтобы«хранить». Вы сделали больше, чем я ожидал."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Растворение — это дар богов. Оно приносит не слишком много боли, ровно столько, чтобы Паралич наши нервы, позволяя нам наслаждаться деликатесами и красным вином, а затем вместе праздновать и двинуться к гибели."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Болтовня · О растворении"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Прошлое, сейчас, будущее, миллионы сияний связаны с этим!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Прошлое, сейчас, будущее, миллионы сияний связаны с этим!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "Ворота предела уже открыты. Здесь всё возвращается к единству!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "Ворота предела уже открыты. Здесь всё возвращается к единству!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "Внемли голосу мудрости."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Бесконечность, безграничная, неисчерпаемая, бескрайняя."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Специальный навык·3"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Это Его воля... нет, точнее, это не воля, а бессознательное. Его бессознательный взгляд включает всё сущее в Своё дыхание."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Не удалось тщательно изучить... мельчайшие улики.."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Я покажу настоящее."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "«Ответ». Я храню эту Ворота из любви, и из любви передаю Ключ от врат в твои руки."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Обязательно... вернусь.."
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "Все явления неба и земли, круговорот причины и следствия!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "Все явления неба и земли, круговорот причины и следствия!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "Это лезвие ещё не потускнело."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "На тренировках нельзя расслабляться."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Более гибкий."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Невидимая сущность будет служить вам."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_6737_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Почувствуйте это жгучее дыхание ——"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "Мы все станем... частью зелёного пламени.."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Мой щит будет сиять, чтобы защитить вас, мой повелитель."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_6740_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Снова немного прогрессировал, несказанно благодарен!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_6741_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Фырк"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(презрение и Выдержка)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(презрение и Выдержка)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(презрение и Выдержка)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "Время, проведенное вместе с другими, всегда кажется спокойным.."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Кровавая цепь, посланник Тихифона, лезвие ненависти... Это они дали мне эти титулы. Конечно, я не против стать таким человеком, так уж и быть."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О себе"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_6750_AwakerVoiceContent = {
    Text = "Всё или ничего!"
  },
  Voice_6750_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(восклицание)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Можем ли мы пойти ещё дальше поиграть? Давай отправимся к морю!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Вау—— спасибо, партнёр~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Партнёры~больше партнёров~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Юу Хаши... Он очень особенный. Думаешь, откуда у нас появились процветающие дни? Всё благодаря тому, что он, как безумный воин, сражался на арене. Именно он наш максимальный Генезис дохода."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Пустая болтовня·О Юу Хаши"
  },
  Voice_6757_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Юу Хаши\"будет разблокировано"
  },
  Voice_6758_AwakerVoiceContent = {
    Text = "Глупо!"
  },
  Voice_6758_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Хм."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Вперёд! Отдать боевые Команды!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "В абисс... будет Погоня за светом правосудия."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "Свет правосудия зажигается здесь!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "Чувства человека, как цветы, хрупки, но в то же время так же ценны.."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Пустые разговоры·О Колетт"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Не сопротивляйся, не плачь, не выживай!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Не сопротивляйся, не плачь, не выживай!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Дверь, включить."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_79297_AwakerVoiceContent = {Text = "О."},
  Voice_79297_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_79298_AwakerVoiceContent = {Text = "Й...?"},
  Voice_79298_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "Гидротерапия, электрошоковая терапия, принудительная терапия, всё это не лечение, а пытки, поэтому во время сеансов я буду лечить пациентов психиатрической больницы по-своему, в конечном счёте они все вызовутся и найдут истинную свободу."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_80092_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Бедный Уайт, его семья заперла его в свинарнике, потому что близлежащий приют переполнен. Я бесплатно провел ему лечение, после этого он наконец понял, что он человек, а не скотина, и сам вернул себе достоинство как человека."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_80093_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Ткачиха, адвокат, барон... Я никогда не откажу пациенту из-за денег, все они для меня просто нуждающиеся в лечении пациенты."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_80094_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Я признаю, что действительно недооценил тебя, твое существование — это сама боль. На этот раз не нужно послевизита, я хочу остаться рядом с тобой, видеть, как приходит финал."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_80095_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Эти пациенты принесли мне прекрасные воспоминания. Теперь твоя очередь, Страж, я уже выбрал для тебя исход. Это будет самая запоминающаяся консультация в моей карьере."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_80096_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Отказ от помощи доктора не принесет тебе пользы. Возможно, в следующий раз нам стоит попробовать глубокий гипноз."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Тёмная Комната, одна, и в голове снова и снова звучит множество мучительных шепотов — таков лучший способ насладиться временем."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Хотя это немного невежливо, говорить с тем ребенком только делает меня скучным — ты всегда видишь только одну эмоцию, это улыбка."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Пустые разговоры · Об Орета"
  },
  Voice_81140_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Орета\""
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Прошу прощения за непрошеный визит, я просто заметил, что у тебя упал психоэнергетический Уровень и пришёл позаботиться. Теперь, Страж, готов начать духовное путешествие?"
  },
  Voice_81141_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_81143_AwakerVoiceContent = {
    Text = "Метод лечения пациентов психиатром - это трепанация черепа - расслабьтесь, это было давно, сейчас у нас есть множество способов измерить и глубже понять разум пациента."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_81143_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Чтобы понять Близкий Близкий друг друга, нужно открыть сердце — потрогай здесь, и мое серебряное сердце откроется для тебя."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Если ты хочешь услышать, что я думаю, то, возможно, ты разочарован. Я лучше слушаю, чем делюсь."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ах, я слышала Его голос, эти бредни, каждый слог полон самой ужасной боли!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Я запомню боль этого момента и буду постоянно вспоминать и наслаждаться…"
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Будучи фрагментом этого существа, ты обладал его аурой, насыщенной страданием, что делает любые твои воспоминания невероятно вкусными."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Вспоминайте страхи, подробно описывая свои болезненные ощущения, суть эмоционально-ударной терапии заключается в том, чтобы противостоять боли и победить ее. Давай, протрите слезы и медленно расскажите мне эти воспоминания..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_81149_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Поздравляю вас, вы уже выздоровели – да, галлюцинации и иллюзии - это нормальное явление, они являются свидетельством вашего исцеления."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_81150_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "В твоей голове, должно быть, полное чудесных видений; не переживай, это нормально. Нарисуй их, твое подсознание и инстинкт откроют тебе всё."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_81151_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Далее идет моральная терапия Филиппа Пинарда. Вам нужно высказать самые глубокие желания и страхи, это необходимый процесс для снятия душевных цепей и восстановления спящей человечности."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_81152_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Страж, ты можешь помочь мне пройти небольшой тест? Это всего лишь тест Роршаха. С его помощью я смогу увидеть твои сокровенные, никем не известные глубины, став единственным пробудившим, который раскроет тайны сердца Хранителя."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Беседа·О психоанализе"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Сначала давайте послушаем музыку. Слышите? Нежная и мелодичная музыка. Теперь позвольте своему телу и разуму резонировать с музыкой, погрузитесь в духовное расслабление..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_81154_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Смотри на маятник, глаза следят за его движением..."
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "Шшш— Тихо, а затем идите ко мне, к тому финалу, которого я направляю."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Оцепеневшая душа не вызовет ни малейшего интереса. Их души уже мертвы, и как бы ни пытаясь разбудить, не возникнет ни малейшей волны."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Я слушаю, продолжайте."
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "Пожалуйста, сохраняй тишину."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Доверяй мне чуть-чуть больше."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Покажи больше боли!"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "Не нужно скрывать и стесняться, я твой единственный доверенный слушатель. Иди, выскажи мне свою самую глубокую боль……"
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Сегодняшняя Айгис выглядит гораздо более жизнерадостной. Конечно, если моему маленькому гостю нужно что-то, я с радостью помогу. Я имею в виду, настоящую помощь."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Разговоры · Об Ай Джис"
  },
  Voice_81165_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Ай Джис\" будет разблокировано"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Покажи мне свою истинную сторону."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Я буду тщательно наслаждаться этой сладкой болью."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Не нужно скрывать и стесняться, я твой единственный доверенный слушатель. Иди, выскажи мне свою самую глубокую боль……"
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Психические расстройства не являются исключительной проблемой нашего времени, они выходят за рамки времени и пространства, как и Раствориться. Оба явления превышают границы человеческого сознания, не так ли?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Шшш— Тихо, а затем идите ко мне, к тому финалу, которого я направляю."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "Это место полно следов истории, а в определенном смысле история означает память — страдальческую память о ушедших."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Глубокий вдох..."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Страдание, отчаяние, смерть... все эти воспоминания на вкус как десерт после ужина."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Не стоит так волноваться, это всего лишь обычная психологическая консультация."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Следуй моим указаниям."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Церемония столкнулась с неожиданным происшествием. Пожалуйста, простите меня за то, что я ударил вас по руке с помощью флага, я должен поддерживать вас в сознании."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_84185_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Здесь можно увидеть различные модели кораблей, использовать более современные навигационные устройства, мне это нравится, и самое главное, я считаю, что этот «корабль» движется по правильному пути в истории человечества."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Церемония прошла успешно, спасибо за ваше сотрудничество. В следующий раз я создам несколько специализированных сигналов, чтобы помочь нам безопасно и успешно завершить церемонию."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_84187_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Я не знаю, почему это существует, но я знаю одно: я должен успешно вести судно, благополучно вернуть всех моряков и пассажиров, вышедших в море."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Не волнуйтесь, я использую эту силу для безопасного направления корабля и никогда не злоупотреблю."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Пожалуйста, остановите сопротивление."
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "Я испытываю к вам только уважение и клянусь выполнить все приказы, которые вы мне дадите."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Извините, я не разбираюсь в людях, но знаю о кораблях. Пожалуйста, простите меня за такой параллель: ваш киль не деревянный и не металлический, а стальной, крепкий и устойчивый, внушает уважение."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_84192_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "Сдавайся."
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "Вместо того, чтобы говорить о любви, мне больше нравится использовать слово «объятие». Когда я смотрю в глаза этого невыразимого бога, мой разум теряет разум и впадает в безумие, да, я должен бояться Его, но не могу себя контролировать."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Я не позволю шторму сломить меня."
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "Если нет порядка, что остаётся в этом мире? Только хаос и беспорядок."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "В следующий раз я хочу попасть на корабль не в качестве штурмана. То есть... я готов и согласен действовать под вашим руководством. Вы заслуживаете моего полного доверия."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_84197_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Я лишь выполняю свои обязанности как навигатор и не нуждаюсь в каких-либо отчетах о похвале."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Система маяка может значительно снизить давление навигации, и его Погоня за светом особенно яркий, я очень рад выйти в море вместе с Фаросом."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Разговоры · О Фалосте"
  },
  Voice_84199_UnlockDesc = {
    Text = "Разблокируется после получения Пробудившего «Фарос»"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Моряки, следуйте моим указаниям, и мы обязательно достигнем порта безопасно."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Связать духа установлена, я почувствовал ваше сознание... Это мой первый раз в навигации в пустоте, пожалуйста, укажите, если столкнусь с проблемой."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_84201_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Наблюдая за катками облаков и постоянным падением ртути в барометре, все внимание, корабль скоро будет в шторме."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Этот беспорядок произошёл из-за того, что я неправильно спланировал маршрут, я готов принять наказание по правилам."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Измерьте угол высоты небесного тела."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Это головокружение похоже на морские болезни. Пожалуйста, закройте глаза, возьмитесь за мою руку и опритесь на меня, так будет легче."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_84205_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Убери передние паруса, поклонись левому борту, штурман, отрегулируй курс согласно моим расчетам."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Этот опыт бесценен, я запишу его подробно в журнал плавания, оставлю для будущих моряков."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Ритуал углубления связи сопряжен с риском и неизвестными результатами, но, пожалуйста, будь уверен, что я стану твоим лоцманом, чтобы ритуал завершился успешно."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_84208_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Перенастройка баланса."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Обратите внимание на защиту судов."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Некоторые как пароходы, медленно реагируют, но могут развивать высокую скорость, другие как дизельные суда, быстро стартуют, но имеют ограниченную мощность. А вы, Страж?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_84211_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Я твердо верю, что за усилия следует вознаграждение, поэтому в будущем я буду работать еще усерднее."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "В ходе многочисленных операций вы доказали свою способность. Я считаю вас таким же выдающимся штурманом, как и я, нет, возможно, вы гораздо лучше меня."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_84213_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Коперсант в любое время к вашим услугам, если потребуется."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_84215_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Моряки, следуйте моим указаниям, и мы обязательно достигнем порта безопасно."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Навигатор Кеперсанг прибыл! Флаг установлен, личное состояние в порядке, просьба хранителю дать приказ на вылет."
  },
  Voice_84218_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_84219_AwakerVoiceContent = {
    Text = "Я непременно приведу корабль в правильное русло."
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "Это шляпа сдвинута? Извините, я не совсем понимаю ваше намерение, пожалуйста, дайте мне ясную команду."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Флаг — это язык штурмана и его надгробная надпись. Когда судно тонет, спасатели могут прочитать мои последние сообщения по обломкам флага."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Беседа·О флагах"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Ощущение баланса корпуса."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Убери передние паруса, поклонись левому борту, штурман, отрегулируй курс согласно моим расчетам."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "E флаг передает команды."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "В необходимый момент навигатор, обученный работе в машинном отсеке, может выполнять роль штурмана, но чтобы обеспечить безопасность судна, я все же надеюсь передать эту задачу специалисту."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Разговоры · О Хилестере"
  },
  Voice_84225_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Хилестер\" будет разблокировано"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Возникает чувство невесомости, следующее ощущение — резкое тряска корабля. Следите за моими движениями, ощущайте центр тяжести тела и сохраняйте равновесие."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_84226_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Начало корректировки морской карты."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Специальный навык·3"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "Команда активации флага C."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Специальный навык·3"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Не думай перешагнуть через меня."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Как, по-вашему, должны отношения дружбы выглядеть? Поллукс любит поручать мне множество дел, даже если сам прекрасно мог бы их выполнить. И я с удовольствием помогу ему, ведь это наша форма общения. Если хотите, я сделаю что-то и для вас."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_90334_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Этим бессмертным телом противостою любой беде!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Даже до того, как мы прочли ту книгу, нас не переставало интересовать, что находится за внешним миром, за озёрным островом и тёмно-красной стеной. Но когда Поллукс страдал, я никогда не думал восстанавливаться, и по сравнению с ним, я был намного слабее и неуклюже."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_90336_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Я выгляжу как идиот? Простите, простите за мое невежество, кроме знаний о богах, которые дала нам лампа, я мало что знаю. Я буду быстрее учиться, расскажите мне, что вам нравится и не нравится, я обязательно это запомню."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_90337_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Свидетельствуйте, воля к свободе."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Магазин, способный исполнить любое желание, с товарами для каждой просьбы, внушает уважение... нет, я не сомневаюсь в силе этой дамы, но «хочешь чего-то, плати соответствующую цену» — этот принцип мы с Поллуксом познали слишком много раз."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Разговоры · О Давдейле"
  },
  Voice_90339_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Давдейл\" будет разблокировано"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Могут ли эти проклятые крылья действительно парить в небе?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Вы не сможете уничтожить меня!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "Вы хотите прикоснуться к этим перьям? Пожалуйста, мне раскрыть крылья пошире?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Находясь под чужой помощью, я часто задумывался, не были ли те особые благодеяния, те драгоценные тексты, которые вы подарили, и великолепные метеоритные минералы, скрытыми долгами? Простите меня, я не должен вас так судить."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_90343_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Птица, наконец, воспарит в вышине."
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "Мастера по приготовлению еды... знание приготовления пищи действительно необходимо, хотя мои требования к еде невысоки, Поллукс очень привередлив. Надо найти время, чтобы обратиться за советом... Не ходить? Почему, ведь еда, приготовленная этим господином, выглядит очень аппетитно?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Сплетни · О Дуллсайне"
  },
  Voice_90345_UnlockDesc = {
    Text = "Разблокировано после получения Пробудивший «Дулесайн»"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Теперь, размышляя, кажется, что те прислужницы, что были при свете, ничем не отличаются от нас с Поллуксом, мы все живем в цепях, но они всегда послушны и терпеливы. Зелёная Служанка, однако, выглядела иначе. Она... полна энергии, кажется, она любит делать эти вещи, возможно, она уже обрела самое ценное - свободу."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Гарене"
  },
  Voice_90346_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Гарен\" будет разблокировано"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Вы не сможете уничтожить меня!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Все же не удалось... улететь?"
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Рассеется с ветром!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Специальный навык·2"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Приветствую, рад встрече, я Кастор... нужно ли ещё что-то сказать? Извините, я не слишком красноречив, если вам что-то нужно от меня, пожалуйста, зовите меня в любое время."
  },
  Voice_90351_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_90352_AwakerVoiceContent = {
    Text = "Всего лишь..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_90353_AwakerVoiceContent = {
    Text = "Падайте!"
  },
  Voice_90353_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "Я видел много неизведанных предметов, не делал многого. Эти глубокие зеленые озера и затяжные туманы больше не будут нас удерживать. Океаны, мегаполисы, пасторальные пейзажи — места, о которых сказано в этой рукописи, я хочу их все увидеть вместе с вами и Полидевкусом."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_90354_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Когда ты слышишь шелест листьев на деревьях, знай, что я уже рядом с тобой."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_90355_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Эти темные перья стали еще глубже."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "На самом деле я завидую больше всего вашему доверию и взаимопониманию с вашими товарищами, отсутствие подозрений, чувство, что вас забыли или предали... это действительно слишком больно."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Та воровка сказала мне, что научит самым крутым навыкам выживания на улице, только нужно заплатить ей пятьсот Рео Клыков... меня обманули? Нет, я считаю, что это очень стоящая наука, это как раз то, чего мне и Поллуксу не хватает... это вопрос денег? Понимаю, так что, я пойду обсужу с ней, как насчет четырёхсот пятидесяти Рео Клыков?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Пустая болтовня - О Дженкинс"
  },
  Voice_90358_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Дженкинс\""
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Я все еще могу выдержать..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Когда мы были маленькими, контроль над нами со стороны факела не был таким строгим, иногда Поллукс каким-то образом удавалось попросить у кого-нибудь конфету. Вкус этих конфет... как и сейчас."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_90360_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Этим бессмертным телом противостою любой беде!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Вы можете научить меня знаниям о торговле с людьми? Как обмениваться предметами, как управлять заработанными деньгами — это действительно глубокая наука. Получение свободы — это только Начало, а для того чтобы жить самостоятельно, мне и Полидевкусу еще многое предстоит учить, так что в будущем мы попросим вашей помощи."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Рассеется с ветром!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Ветер, неси это в пасть смерти!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Поллукс... хотя он был наполнен многими неправильными идеями о свете, в его сердце нет зла. Он просто отчаянно хочет признания от света, признания от верующих, настолько, что чрезмерно заботится о их нуждах. Вместо того чтобы говорить, что он слишком эгоистичен, следует сказать, что он всегда боялся потерять ту «самость»."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Праздные разговоры: о Поллуксе"
  },
  Voice_90365_UnlockDesc = {
    Text = "После того, как вы получите пробуждающее тело \"Поллукс\", оно будет разблокировано"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Извините, я неосознанно задумался... Вы спрашиваете, что это за перо? Это самое важное для него, и также самое важное для меня. Красивое, Правда?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "В то время мы каждый день учились теологии под наставлением Альбино или хранителей. Моим самым заветным желанием было, чтобы однажды эти рукописи были пересмотрены, чтобы они стали короче и проще. Тогда я бы не достиг состояния изнурения, запутываясь в них, под строгими выговорами хранителей."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_90367_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Спасибо вам за то, что дали мне ключ к обретению свободы."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Эти крылья наконец-то стали самыми полными, такими мощными и крепкими. Теперь я могу однажды взять вас и Поллукса, когда вы захотите в небо, просто позовите меня громко."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_90369_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Спрячьтесь за крылом!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Наконец-то... я увидел обширное звездное небо, описанное в той книге."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Был момент, когда проповедник... Жюльетта дарила нам теплые мгновения, она всегда с готовностью улыбалась каждому, вызывая Страх подвести ее ожидания. Стоило ей коснуться вашей головы с улыбкой, и любые слова сопротивления оказывались невысказанными. Теперь это не так, можете свободно касаться моей головы."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_90372_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Я долгое, долгое время был погружен в эти черные липкие массы, так долго, что забыл о времени, так долго... что даже Полидевкус забыл обо мне. Это не приносит физической боли, а вызывает Страх того, как ты исчезаешь на глазах."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "С детства нам не позволяли активно общаться с другими людьми, слово \"Близкий Близкий друг\" мы узнали лишь через много лет. Я и Полидевкус не имели ничего, кроме Близкий Близкий друг друга. Мы были братьями, друзьями и узниками одной и той же темницы, только мы. Теперь настало время завести новых друзей."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_90374_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "Назад!"
  },
  Voice_90375_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Школа, где каждый может свободно общаться и заводить друзей по собственному желанию? Ты сказал, здесь не изучают теологию, есть возможность выбрать самые разные курсы... и даже прогуливать занятия? Хм, какое прекрасное место."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "Отойди!"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Нечестивые... обязательно получат наказание..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Я полон света!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "Грязное существо."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Слишком фанатичная верующая, возможно, в глазах людей просто необъяснимый безумец, хотя она тоже когда-то сбилась с пути, но такая Решимость отдать всё ради Божества — это нечто, чего подавляющее большинство простых людей не способны добиться. Что касается меня... мне лишь грустно видеть подобных."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Мириам"
  },
  Voice_95053_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Мириам\" будет разблокировано"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Я принесу руководство и Трибунал, светлая ночь прогонит ваше зло!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ах....... прошло так много времени, а он все еще не изменился. Я, будучи ребенком, возможно, никогда не думала, что однажды я так сильно наврежу и буду в долгу перед братом, так сильно, что это заставляет меня чувствовать стыдно, даже если эта трагическая Колесо Судьбы не была под нашим контролем. Мы пережили столько разлук, но, поскольку я вернулась, в будущем ничто не сможет нас разлучить, даже смерть."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Болтовня: о Касторе"
  },
  Voice_95055_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Кастор\""
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Раньше я ненавидел много вещей. Неповоротливые слуги, которые не соблюдали нормы, слуги, пренебрегающие иерархией, язычники, оскверняющие бога… Но сейчас, лишь Фонарь, единственный Фонарь! Жюльетта и ее секта принесли мне и брату невосполнимую боль. Клянусь именем святого сына, я не позволю, чтобы эта боль появлялась у других!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Я буду следовать этому светлому пути, пока не исчерпаю свою жизнь."
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "Сияние Держателя Света обязательно осветит долгую ночь!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Вы всегда так щедры и добры, я постараюсь впитать это сияющее тепло."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Апостол Держателя Света, рожденный в ночи, рассекающий тьму, святосердечный Сын, я, Полюкс, пришел по вашему призыву, чтобы даровать вам мою темную силу и светлую душу."
  },
  Voice_95060_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_95061_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Избавься от своих грехов!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Когда-то все говорили мне, что этот черный цвет, как бездна, это моя Твёрдая Твёрдая вера, то, что я принесу верующим благословение. Теперь эта тьма уже поглотила меня и слилась со мной... но то пульсирующее сердце внутри этого греховного тела — это место, которое никогда не может быть уничтожено. Не беспокойтесь, я обязательно использую эту силу, которую мне дала тьма, чтобы принести истинное благо людям!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Я буду Развеивание ваше великое имя, все нечистое и грязное в конечном итоге будет очищено светом."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Все прошлые грехи были совершены, и не следует их избегать. Я должен исправить ошибки с фонарем, направив заблудших людей к правильному пути. Позволь мне нести мои грехи. Затем я отвечу на этот Погоня за светом, отвечу на ваш призыв, и ступлю на этот истинный путь, принадлежащий Святому Сыну."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_95065_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Какое благородное сердце, что вы готовы простить человека, полного грехов, я могу почувствовать, как в вашей душе сияет чистый Погоня за светом, ярче огня, возможно, вы можете направить мое блуждающее сердце..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_95066_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Та тьма, тьма, расползающаяся из заклинаний Жюльетты, всегда окутывает мой разум... Но теперь в этой тьме появилась искра света! Эта слабая точка света хочет сообщить мне что-то?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_95067_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Слышал, она когда-то тоже была святой, но такое грубое поведение, нахальная речь… Что? Она даже не может продекламировать молитву? Такое отсутствие благочестия действительно заставляет небожителей стыдиться её."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Болтовня: о Мерфи"
  },
  Voice_95068_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Морфи\"будет разблокировано"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Тот, кто способен вести людей через туман, поистине является носителем света, сотворенным из чистого серебра. Невинный землебит, о котором говорит Жюльетта, на самом деле построен на телах павших последователей. Будучи святым, я распространю новую евангелие среди всех верных, которые достойны спасения."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Ведущий меня, дарующий мне Погоня за светом, когда-то я был ослеплен ложным смыслом, но теперь под твоим руководством я нашел свое истинное предназначение - исправить тех невежественных и искаженных псевдобогомолей, принести миру вечный Погоня за светом. Я осознаю твою бескорыстность, тебе не нужны моя преданность и жертвы, так что позволь мне следовать за тобой, записывая каждое твое святое слово и деяние, чтобы они указывали мой путь в темноте."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_95070_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "С кандалами, купая в темноте, шагая к тому свету, Шаг за шагом... Это то, что ты хотел мне сказать?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_95071_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Светлый Сквайр потерял Искра в своих руках, эта слепая боль действительно беспокоит меня, я искренне прошу вас спасти эту потерянную душу, пожалуйста, возьмите меня за руку, приближая к этому святому сердцу, пожалуйста, дайте мне указание к свету……"
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_95072_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Несчастный ребенок, но так как она уже посвятила себя следованию за вами, она непременно получит окончательное спасение. Но почему её обезьянообразный Близкий Близкий друг тоже удостоен вашей милости? Этот злой ребенок даже украл мой молитвенный артефакт! В её душе, несомненно, скрыты потоки греха, это так нечестиво! Нечестиво!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Айгис и Дженкин"
  },
  Voice_95073_UnlockDesc = {
    Text = "Разблокируйте, получив пробудившуюся сущность «Айгис» и пробудившуюся сущность «Дженкин»."
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Убегайте быстро."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "Сияние Держателя Света обязательно осветит долгую ночь!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ах…… я увидел, могучую силу, истину мира…… я уже осознал свои прошлые заблуждения, вы поистине истинный носитель лампы! Позвольте мне стать вашим верным апостолом, это сердце, рожденное для носителя лампы, впредь будет радостно биться и трепетать в покорности вам……"
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_95076_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Слепое искупление того священника является недопустимым безумием; божественная весть может быть дарована только благочестивому праведнику. Если даже посланник бога не имеет проницательных глаз, как может наградить нераскаянных злодеев, запятнав святое царство бога? Это разве не предательство божества и праведников?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Сальвадор"
  },
  Voice_95077_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Сальвадор\" разблокируется"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Я полон света!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_95079_AwakerVoiceContent = {Text = "Пей!"},
  Voice_95079_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "В детстве я мечтал вырваться из клетки, тогда я считал, что это место, которое только причиняет страдания, совсем не стоит любви. Но теперь, пережив две жизни, я понял, что свобода — не единственное, что я жажду, видеть, как те, кто верит, узнав о своем спасении, с искренностью, надеждой и благодарностью на лицах, — вот что действительно значит быть святым."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Время, проведенное с Жюльеттой, я сделал много ошибок, я не должен был получать такое доверие. Но вы все равно выбрали меня... Не волнуйтесь, я снова найду свою веру. Святой сын больше не разочарует своих подданных и вас."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_95081_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Я буду с благодарностью использовать то, что вы предоставили."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Непристойно!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "Проклятие."
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Во имя меня!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Я увидел! Этот Погоня за светом, этот сияющий в глубине сознания Погоня за светом, он становится все ярче! Он зовёт меня..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_95087_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "В детстве Кастор и я служили Святыми Сынами. Тогда я всегда думал, что он слишком простодушен и неуклюж, и мне нужно направлять его пути в будущее. Теперь, узнав о вашем пути, я понимаю, что основы мира зиждутся на таких честных и стойких людях, как вы и он."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_95088_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Мой светильник, с тех пор как я получил ваше указание, думаю, я на правильном пути. Однако ваш глупый ученик всё еще запутался: та легендарная невинная земля, действительно ли она под вашим контролем? Разве такого не существует? Вы хотите сказать, что... невинная земля находится среди людей, в чистом сердце праведных?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Это сердце, слышащее божественную волю, стало ближе к вам."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Вы… имеет ли вы какое-то сообщение, которое хотите передать мне? Ваш посланник всегда готов выслушать ваши наставления."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Освети меня, путеводитель заблудших! С вашим светом, я уже увидел все, что необходимо увидеть... Я использую это проклятое тело, чтобы очистить все прошедшие, и чтобы все будущие находились под этим сиянием!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_95092_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Пойте о свете!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Среди жестокого мира ты стремишься к спасению? Вперёд, полон надежды, малыш."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_95391_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Вот, бери это и играй с этим, говорят, что это запрещённые реликвии, выкопанные из каких-то руин. Мне неинтересны эти вещи, пропитанные их дыханием, я собирался просто сжечь их, но подумал, что, возможно, это может быть полезно для тебя, поэтому я принес их.\nТы спрашиваешь, как я их получил? Конечно, некоторые люди «добровольно» их мне передали, не переживай, с гарантией чистого происхождения."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_95392_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Охота завершена, награда пусть будет улыбкой маленького."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Знаешь ли, малыш, из этих двух пистолетов не стреляют пули, а сжатые желания и злые намерения.\nЭти хаосы составляют Искра, подобный крови и мясу, и в момент седьмого выстрела на той стороне он погрузит всё в ад и сожжет."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О ружьях"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Не нужно так сильно себя заставлять, мой хранитель. Хотя я знаю, что это дорога с потерями и опасностями, малейшая ошибка приведет к фатальным последствиям. Но, если это продолжится, однажды ты упадешь от истощения. Если нужно, давай поговорим, как семья."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_95395_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Гори, разруши, стоните!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Исчезни."
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "Мой взор стал яснее, я увидел вещи, скрытые во Бездна… Ради вас, я должен обрести больше силы…"
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_95398_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Давай, Страж, подойди сюда, сейчас это выглядит слишком неловко.\nТы знаешь, когда я впервые встретил тебя, я никогда не думал, что однажды смогу снять ту оболочку, которая называется жестокостью и хладнокровием. Звучит немного глупо, не так ли? Господин взрыва, желающий найти семью, которой можно довериться.\nПообещай мне, если в тот день ты не сможешь выдержать... просто в сердце позови мое имя, и я возьму тебя с собой в мое королевство. Хотя это лишь отсрочит всё настание, по крайней мере в последний момент, ты сможешь немного отдохнуть в моих объятиях."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_95399_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Встретьте Конец."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Нгх!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "В огне миллионов желаний и злости, сжигайте!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "После удачной охоты всегда нужна пирушка, присоединяйтесь, попробуйте сделанное мной жареное верблюжье Инкарнация и свежеприготовленный текилу. Постойте, малыш, похоже, вы не можете пить... тогда попробуйте мой специальный сок~"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_95403_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Что случилось, малышка? Хочешь получить объятие? Иди сюда, моя горячая грудь всегда открыта для тебя... Ха-ха, не стесняйся, заботиться о младших как старшая сестра - это нормально, разве нет?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "Проклятие."
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "Встретьте янтарную смерть."
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Давай отступим, я прикрою... Не переживай, я вернусь живым."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Давайте же, сожжём всё в Пепел!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Взрывное пламя, разгорись вновь здесь!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "Огонь все больше разгорается, хочет ли этот малыш увидеть великолепный фейерверк?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Эта группа, топчащая человечность, скрывающаяся в тенях, использует @1 для своих грязных жертвоприношений и исследований... Рано или поздно, я всех их убью."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Бах!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "Я найду его, где бы он ни прятался в уголке вселенной, я в конечном итоге найду его.\nЭтот грязный крысенок заплатит за все, когда я найду его, и вся радость и наслаждение в мире сгорят в аду.\nНе беспокойся, на его похоронах я оставлю тебе специальное место, чтобы мы могли вместе насладиться его последним криком."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Болтовня: о N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Слушайте, это вопли dying звезд."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_95415_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Встретьте Конец."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Ты - моя Надменность, будь уверен в себе, мой Страж! Что бы ни случилось, я - твоя самая сильная защита."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Те безликие существа пожирают этот мир, и ты неизбежно будешь с ними враждовать. Но это не имеет значения, потому что я буду стоять за твоей спиной."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_95418_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Гори, разруши, стоните!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "Сохраняй спокойствие."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_95422_AwakerVoiceContent = {
    Text = "Отступить."
  },
  Voice_95422_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Ты спрашиваешь, как я смотрю на Растворение? Это все равно что спросить, как мышь, блуждающая по канализации, видит высокомерного лорда. У меня только один Лечение: отвращение, исходящее из глубин тела. Если бы это было возможно, я бы пил вкусное верблюже молоко, любуясь, как они вскрикивают, умирая под моими выстрелами."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Хотите, чтобы Искра стал еще ярче?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_95424_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Я сюда прихожу лишь когда получаю заказы, если маленькому человеку нужно меня найти, используй это заклинание. Итак, скажи вместе со мной:……………… Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Когда-то мы били́сь за выживание в этом ветхом городке с жестокостью и хитростью. Даже став так называемыми «великими силами», мы должны были проявлять всю свою волю, сталкиваясь с бароном, охраной и «рыцарем», который не намерен покидать сцену истории. Но теперь всё иначе, все стали моими «потомками», больше не нужно смотреть на лица других. Ну, хотя один маленький товарищ ещё блуждает в миру, я верю, что с ним всё будет в порядке. Ведь каждый раз, когда я занят, именно этот парень заботится о других."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Болтовня: о семье"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Это враг маленького паренька? Тогда — охота начинается."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Я — владыка некогда забытого взрыва! Объявляю! Всё погибнет!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Сжигание и Разрушение – это всё для меня, я увлекаюсь смертью, приносимой охотой... Ты думаешь, я бы сказал это?\nХа-ха, шутка, для меня самое важное — это все вокруг. Ничто не важнее, даже... я сам неважен."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Маленький парень попал в беду? Следуй призыву, Кэтигура придет с разрушением. Пусть все проблемы растворятся в пыли — «пух»."
  },
  Voice_95430_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_95431_AwakerVoiceContent = {
    Text = "Вкус силы, не попробовать ли на каком-нибудь неудачнике?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_95431_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Я — владыка некогда забытого взрыва! Объявляю! Всё погибнет!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "Легендарная королева Алан, великий объект желаний Тифрей Ясод, я однажды видела ее во время преследования Н. Хотя я не одобряю все, что она сделала, но честно говоря, если это единственный способ, который я смогу найти для того, чтобы выжить в «Его» взгляде... Я сделала бы тот же выбор. В этом смысле, я не отличаюсь от нее."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Пустая болтовня: О Таис"
  },
  Voice_95433_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Тайис\" разблокируется"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Чувствуется отлично, оружие хорошо подготовлено."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Я — Искра, я — пламя, я — неугасимая Хаос… Я соберу всех… домой…"
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_95435_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Готическая башня здесь излучает классический аромат, а у пробудившихся здесь есть вкус, которого я никогда не испытывал: здесь есть аромат мертвецов, а также легкий свежий запах живых, действительно… немного хочется попробовать."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Пустая болтовня · О Мисаг"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Ищущий смерти, я исполню твоё желание."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Вспышка безумия: II"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Я уже не могу дождаться, чтобы начать."
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "Возвышение"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "Тебе вдруг стало интересно, не так ли? Иди сюда, мой дорогой Гость, становись моей почетной гостьей вкусной этой пиршественной. Позволь мне повести тебя, чтобы вместе насладиться каждым тонким послевкусием душ."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Активация духа·расцвет"
  },
  Voice_96364_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 15"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Шшшт, пожалуйста, не говори, давай тихо послушаем голос духа."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Согласованность·I"
  },
  Voice_96365_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 2"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Вечная красота — это наша Твёрдая Твёрдая вера. Медленное разложение, накладываемое на живых, стирает все следы существования... это чистая и жестокая пытка для жизни."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Пустая болтовня о кризисе"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Как и я, Пикман стремится к вечному искусству, мы должны стать лучшими друзьями. Но он считает еду разрушением вечного, это явно ограниченное мнение в искусстве."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Болтовня·О Пикмэне"
  },
  Voice_96367_UnlockDesc = {
    Text = "После получения пробуждающего тела \"Пикман\" станет доступно"
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ха!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Ударить: |"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Ни одно прилагательное не может описать тот манящий аромат, который исходит от тебя, он как послевкусие терпкого, но богатого бордоского вина и как густые и насыщенные сливочные кексы, ах... ожидание твоей смерти может стать самым важным событием в моей жизни."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Пустые разговоры · о Хранителе тайн"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Я видел сцену преступления, где Мужчина медленно отрывал куски кожи, ногти, руки и ноги у девушки, но при этом постоянно её лечил. Он не хотел, чтобы она умерла, и никак не хотел, чтобы она жила. Я, конечно, не мог одарить его спокойной смертью, я просто заставил его переживать тот же опыт, что и эта девушка, уже кажется, прошло лет несколько... Для оскорбляющих смерть это вполне справедливо, не так ли?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Разговоры · Неприятные вещи"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Я — бог, управляющий смертью, но, пожалуйста, не поймите меня неправильно, я никогда не создаю смерти. Я просто следую за смертью и собираю её спелые плоды."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Активация духа · дальновидение"
  },
  Voice_96371_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 1"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Ты тоже испытываешь жажду ко мне, Страж?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Разговор · Прикосновение"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Кого же сегодня положить на завтрак?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Расследование началось"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Я дарую вам стать величием сегодняшнего банкета."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Расследование успешно"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Это так неэлегантно."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Удар·три"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Я принесу чистый покой."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Навык·первый"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Перед каждым приёмом пищи я всегда разговариваю с душами. Для них быть осознанно съеденными и продегустированными — это продление жизни и последний блеск. Как мы жаждем их, так и они жаждут нас."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Согласованность·3"
  },
  Voice_96377_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 6"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Будь потише."
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "Удар·4"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Растворись в тенях！"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Лучше держать дистанцию."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "защита·I"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Растворись в тенях！"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Навык: четвертый"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Почему ты так насторожен по отношению ко мне? Ты не должен и не обязан волноваться, это противоречит моей эстетике, нападать на живых."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Болтовня·О еде"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Ищущий смерти, я исполню твоё желание."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "Вознесение"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "Это так неэлегантно."
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "Удар·I"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "Будь осторожен."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "защита: II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Хотя энтузиазм той девушки был весьма трогательным, её запах имел некий затхлый аромат, как будто что-то перебродило. Даже когда она постоянно умоляла меня попробовать, это всё равно не соответствовало моему вкус, и действительно ставило меня в трудное положение."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Разговоры · О Рея"
  },
  Voice_96386_UnlockDesc = {
    Text = "Разблокируется после получения пробуждающего тела \"Рея\""
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Знаешь ли ты? Каждая жизнь, когда она уходит, имеет долгий эхо. Они различаются по высоте и тону, и будут замедляться с момента прихода смерти, пока постепенно не рассеются по всему миру, как некий вздох."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Согласованность·вторая"
  },
  Voice_96387_UnlockDesc = {
    Text = "Достигнув уровня согласованности 4, разблокируется"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Не переживайте, Страж, я всегда буду рядом с вами, пока ваша жизнь не встретит неумолимое исчезновение. В этот момент я обязательно с почестями поглощу ваше тело. Я навсегда оставлю вашу душу в своем теле."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Согласованность Часть 5"
  },
  Voice_96388_UnlockDesc = {
    Text = "Разблокируется при достижении уровня согласованности 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Не чувствуешь своего собственного запаха? Это слишком жалко, ты пропустила самый сладкий в мире, самый... ой, зачем ты отворачиваешься?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Согласованность·4"
  },
  Voice_96389_UnlockDesc = {
    Text = "Разблокируется при уровне согласованности 8"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Я вижу всё больше смерти, образы того мира становятся всё более четкими..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Получить повышение - три"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Доверьте свое тело мне, чтобы я могла внимательно вас дегустировать, каждую каплю крови, каждый кусок мяса, каждую кость."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Чрезмерная вспышка безумия"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Разные ингредиенты требуют различной обработки. Внутренности нужно мариновать, сухожилия на ногах лучше тушить, жирные части подходят для ферментации, особенно текстурированные участки можно жарить, запекать или даже делать изысканные мясные желе, все это требует тщательного выбора. Конечно, сохранять и подчеркивать естественный вкус ингредиентов - это обязательное уважение."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Активация духа·осознание"
  },
  Voice_96392_UnlockDesc = {
    Text = "Разблокируется при уровне духовного пробуждения 7"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Здесь немного холодно."
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "Уголёк: БДЫЩ!"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "Сочетание блюд — это тоже важный вопрос, кислое и сладкое, хрустящее и нежное, освежающее и тяжелое, тонкое и грубое, слои вкусов и противоположные текстуры сталкиваются Близкий Близкий друг с другом, при входе, жевании и послевкусии создавая различные ощущения; вот что доставляет бесконечное и удивительное удовольствие хорошей еде."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Активация духа·формирование"
  },
  Voice_96394_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 11"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Большое спасибо за ваше гостеприимство, для меня большая честь."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Улучшить·2"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Вкусная еда всегда стоит того, чтобы подождать."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Расследование приостановлено"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Конечно, я не чудовище, пожирающее кровь, процесс наслаждения смертью должен быть торжественным и элегантным, ты должен с уважением общаться и понимать уникальные вкусы каждого ингредиента."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Активация духа·взор"
  },
  Voice_96397_UnlockDesc = {
    Text = "Разблокируется при достижении уровня духовного пробуждения 2"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Спокойные мертвецы красивы и ароматны не потому, что их тела отличаются в жизни и смерти, а потому, что их души — это понимание смерти, привязанность к жизни и желание быть запомненными, такие дары, которые я жажду."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Лёгкая беседа · Вещи, которые нравятся"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Ни один парфюм не может сравниться с естественным ароматом человеческого тела, угадать человека по аромату - это самое замечательное."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Активация духа·размышление"
  },
  Voice_96399_UnlockDesc = {
    Text = "При достижении уровня духовного пробуждения 3 разблокировать"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ах, как же это запоминающийся аромат... Я уже не могу дождаться, чтобы встретить тебя в моем храме."
  },
  Voice_96400_AwakerVoiceTitle = {
    Text = "Пробудить"
  },
  Voice_96401_AwakerVoiceContent = {
    Text = "Доверьте свое тело мне, чтобы я могла внимательно вас дегустировать, каждую каплю крови, каждый кусок мяса, каждую кость."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Сверхграничный взрыв безумия · Часть 2"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Я принесу чистый покой."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Навык: Часть 2"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "Будь потише."
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "Удар: II Удар"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Твой цветущий аромат действительно опьяняет."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Получить повышение: |"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "В огне миллионов желаний и злости, сжигайте!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Специальный навык · I"
  }
})
return Text_Voice
